pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into usable residue classes.
    // Residuals that can still host common small items are valuable.
    let small_threshold = 20u32;
    if post_residual > 0 && post_residual < small_threshold {
        // Dead space penalty: tiny residuals are hard to fill
        score += 25.0 * (small_threshold - post_residual) as f64;
    }

    // Modulo arithmetic on post_residual vs capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual % quarter == 0 && post_residual > 0 {
        // Residual aligns with quarter-capacity classes (25/50/75) -> reusable
        score -= 10.0;
    }

    // Lookahead coupling: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally
            score -= 15.0 + 0.25 * next_item_size as f64;
            // Bonus if next item fits EXACTLY (chained perfect fit)
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; penalize if we leave awkward gap
            let gap = post_residual;
            if gap > 0 {
                score += 0.5 * gap as f64;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless they are bad fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if many items remain and open bins are nearly full, allow new bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
        if progress > 0.5 && open_bins_count > 0 && mean_residual < 0.3 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to mean (balance load)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer tighter fits overall: reward small post_residual relative to item
    if item_size > 0 {
        score -= 0.3 * item_size as f64 / (post_residual + item_size) as f64 * 10.0;
    }

    // Integer division threshold: penalize residuals in (0,10) hard
    if post_residual > 0 && post_residual / 10 == 0 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Two-step lookahead with graded bands (borrowed strength from best-so-far).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Exact chain fit is gold.
            score -= 55.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 4 {
                score -= 7.0;
            } else if slack < 8 {
                score -= 2.0 + 0.15 * (8.0 - slack);
            } else if slack < 16 {
                score -= 0.06 * (16.0 - slack);
            } else {
                // Too much leftover for the next item: penalize the excess.
                score += 0.02 * (slack - 16.0);
            }
            // General tightness reward.
            score -= 11.0 + 0.22 * slack;
        } else {
            // Next item cannot follow: penalize stranded slack proportionally.
            let stranded = nxt - post_residual as f64;
            if post_residual > 0 && post_residual < 21 {
                score += 15.0 + 0.32 * (21.0 - post_residual as f64);
            }
            if next_item_size > post_residual + 4 {
                score += 0.42 * stranded;
            }
            score += 0.10 * stranded;
        }
    }

    // Perfect closure of the current bin is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Drain fat bins relative to the mean.
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: discourage proliferation unless crowded or
    // the fit is bad, but give a small graded nudge toward tiny residuals.
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * post_residual as f64;
        if post_residual < 10 {
            score += 6.0 - 0.5 * post_residual as f64;
        }
        let bad_fit = post_residual as f64 > 60.0;
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < 20.0;
        if bad_fit || crowded {
            score -= 30.0;
        } else {
            score += 25.0;
        }
        if fitting_bins_count <= 1 && post_residual > 40 {
            score -= 3.0;
        }
    }

    // Exact-fit bonus for the current placement.
    if item_size == bin_residual {
        score -= 5.0;
    }

    // Late-stream tightening: waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always prefer
    } else if post_residual < 10 {
        score += 500.0; // unusable dead space (min item is 1..100, small gaps often dead)
    } else if post_residual < 25 {
        score += 120.0; // poor fit zone
    } else if post_residual <= 50 {
        score -= 20.0; // medium gap still usable
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 150.0;
        } else {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 60.0; // next item cannot use this bin's remainder
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual below the mean (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Late in the stream, be slightly more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 30.0 * (1.0 - progress); // new bins are cheaper early, expensive late
        }
    }

    // New-bin candidate baseline: only attractive if it enables a large future packing.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) {
        score += 60.0;
    }
    // Gaps too small for any plausible item (below typical minimum) are dead space.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0;
    }
    // Gap below the lookahead item but nonzero: future-unusable, penalize scaled by lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to residual).
    if bin_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 20.0 * tightness;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins, favor consolidation
    // unless this is a last-chance fit.
    if fitting_bins_count == 1 {
        score -= 35.0; // last chance before opening a new bin
    } else {
        score += 0.8 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose leftover deviates favorably from the mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: default moderate score; only attractive when all fits are bad.
    if bin_residual == bin_capacity {
        score = 120.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is fine early in the stream or when many bins exist.
        if step_index < total_items / 10 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Slight progression bias: later in the stream, avoid opening new bins.
    score += 10.0 * (step_index as f64 / total_items as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly favor minimal post-residual (tight fit)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += 12.0 * (1.0 - fit_ratio);

    // Penalize large unusable dead space (post_residual below next item size is reusable)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host the next item: reward
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).abs().min(20.0);
        } else {
            // dead space penalty grows with gap to next item
            score += 2.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: purely minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strong reward to use it, avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // global residuals are fragmented or fit is perfect
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_is_huge = (item_size as f64) > 0.8 * bin_capacity as f64;
        let fragmentation = mean_residual / (open_bins_count.max(1) as f64);
        // Prefer new bin when item is huge, or open bins are too full to be useful,
        // or early in the stream with many bins already open
        let mut new_bin_bonus = 0.0;
        if item_is_huge { new_bin_bonus -= 10.0; }
        if fragmentation < 15.0 { new_bin_bonus -= 6.0; }
        if progress < 0.5 { new_bin_bonus -= 2.0 * (1.0 - progress); }
        // discourage opening bins when plenty of slack exists elsewhere
        if mean_residual > 40.0 { new_bin_bonus += 5.0; }
        if fitting_bins_count > 2 { new_bin_bonus += 3.0; }
        score += new_bin_bonus;
        // empty-bin baseline: post_residual is item_size complement
        score += 8.0;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.15 * open_bins_count as f64;

    // Non-linear coupling: exact fills are gold
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize leaving gaps that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        score = 40.0 + avg_waste * 0.5 - poor_fit * 0.2;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let small = 30u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
        score += (small - post_residual) as f64 * 0.6;
    }

    // Perfect-fit harmonic classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0;
    } else if frac >= 0.2 && frac <= 0.5 {
        score -= 2.0;
    }

    // Strong lookahead coupling (merged with best-heuristic near-miss terms)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 2.0;
            }
        }
        // tight near-miss bonuses
        if post_residual >= next_item_size && post_residual - next_item_size < 4 {
            score -= 7.0;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64;
        }
        // unusable sliver for the next item
        if post_residual > 0 && post_residual < next_item_size.min(21) {
            score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
        }
        // graded penalty when next item does not fit at all
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64;
            if next_item_size > post_residual + 4 {
                score += 0.42 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mostly discourage, but cheaper when open bins are crowded
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean residual coupling
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Current item tightness bonus
    if item_size >= bin_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "wasteful" is the leftover space?
    // Residuals that are exact multiples of common item sizes (10, 20, 25, 50) are
    // reusable; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is ideal
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 {
        -18.0 // highly reusable leftover
    } else if pr % 5 == 0 {
        -6.0
    } else {
        // penalize prime/awkward residuals proportionally
        8.0 + (pr % 7) as f64 * 2.0
    };
    score += harmonic_bonus;

    // Integer-division threshold: small post-residuals are dead space
    let dead = pr / bin_capacity; // 0 for pr < 100
    let _ = dead;
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: does post_residual still fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0; // chain placement possible
            // harmonic match: leftover after chaining is a nice class?
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 || chain_left == 0 {
                score -= 8.0;
            }
        } else {
            score += 10.0; // this bin will be stranded after this placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        // among many options, prefer tighter fit: scale by fraction of bin used
        score += (item_size as f64 / bin_capacity as f64) * 4.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no open bin
    // fits well (post_residual large) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin baseline: slightly worse than a good existing fit
        score = 30.0 + progress * 20.0 - (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // fresh bin pairs well with upcoming large items
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small to hold any plausible
    // future item are dead space. Penalize heavily with a non-linear curve.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Open-bin pressure: penalize bins when many bins are open to encourage
    // consolidation; relax pressure near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all existing bins
    // would create severe dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish baseline for a new bin, modulated by mean residual of
        // open bins: if open bins are already fragmented, a new bin is fine.
        score = 55.0 + (mean_residual / bin_capacity as f64) * 20.0 - pressure * 0.3;
        if next_item_size > 0 && next_item_size as f64 >= bin_residual as f64 * 0.95 {
            // Next item nearly fills a fresh bin: encourage opening it.
            score -= 30.0;
        }
    } else {
        // Lookahead: if the next item fits the post_residual, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Dead space for the known next item: mild penalty.
            score += 5.0;
        }
    }

    // Discourage wasting a large residual bin on a tiny item when alternatives exist.
    if bin_residual > 60 && item_size < 20 && fitting_bins_count > 1 {
        score += 15.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64 ;
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.2 * waste_ratio ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
        }
    }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        if fitting_bins_count <= 1 && post_residual > 40 { score -= 3.0 ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if next_item_size > 0 && post_residual >= next_item_size && progress > 0.85 { score -= 4.0 ; }
        if next_item_size > 0 && post_residual == 0 { score -= 20.0 ; }
    } else {
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
    }
    if item_size >= bin_residual { score -= 5.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead gap: penalize proportionally to how much of the gap is unusable.
        let unusable = (next_item_size - post_residual) as f64;
        score += 2.0 * unusable + 10.0;
    } else if next_item_size > 0 {
        // Gap that still fits the next item: reward proportionally to snugness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 0.5 * slack;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it enables a good future pairing
    // with the next item, or when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin gives perfect 100 residual; reward if mean residual is low
            // (existing bins are nearly full) or next item is large.
            if mean_residual < item_size as f64 * 0.5 || next_item_size > 50 {
                score -= 5.0;
            } else {
                score += 25.0; // prefer filling existing bins
            }
        } else {
            score += 25.0;
        }
        let _ = fragmentation;
    }

    // Slight progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Moderate dead space (hard to fill later) gets a graded penalty.
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.2;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual was already tight (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item fits badly everywhere.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * -1.5;
        // Late in the stream, prefer consolidating into open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.3;
        }
    }

    // Slight preference for bins below the mean residual (keep big gaps for big items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let small = 30u32;
    let mid = 50u32;
    let large = 70u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
        score += (small - post_residual) as f64 * 0.6;
    }

    // Perfect-fit harmonic classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0;
    } else if frac >= 0.2 && frac <= 0.5 {
        score -= 2.0;
    }

    // Strong lookahead coupling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact match: take it
        } else if next_item_size <= post_residual {
            score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 2.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // near-miss bonus: post_residual just above next item
        if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64;
        }
        // unusable sliver for the next item
        if post_residual > 0 && post_residual < next_item_size.min(21) {
            score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mostly discourage, but cheaper when open bins are crowded
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean residual coupling
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Current item tightness bonus
    if item_size >= bin_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter chain fit -> bigger reward.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much of the next item is left stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.5 * stranded;
        }
        // Exact pairing is gold.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Perfect closure of the current bin is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Relative-to-mean-residual coupling: prefer consuming bins with
    // above-average residual (drain fat bins), penalize draining lean bins.
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the current fit is terrible; otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 60.0;
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < 20.0;
        if bad_fit || crowded {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, tighten up: waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how close it is to a "small item" slot
    let small = 30u32;
    let mid = 50u32;
    let large = 70u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
        score += (small - post_residual) as f64 * 0.6;
    }

    // Perfect-fit harmonic classes: post_residual exactly divisible slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Fractional capacity logic
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0; // tiny unusable sliver
    } else if frac >= 0.2 && frac <= 0.5 {
        score -= 2.0; // sweet spot for medium items
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // harmonic bonus if next item nearly fills remaining space
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 2.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: prefer only when open bins are crowded
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Stream progression: tighten early, loosen late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean residual coupling: if this bin's residual is below mean, it's tighter
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Strong reward for near-perfect fill.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space penalty scaled by how much next item overflows.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last chance: strongly favor using the only bin that fits, to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // If this bin is looser than average, penalize slightly (keep big residuals flexible).
    let avg_gap = (bin_residual as f64 - mean_residual).max(0.0);
    score += 0.1 * avg_gap;

    // Time horizon: early in stream, keep residuals large (penalize tight fills mildly);
    // late in stream, allow aggressive packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * fit_ratio;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when current bin would waste a lot
        // or when open-bin count is high and mean residual is large.
        let waste = (bin_residual - item_size) as f64;
        let mut new_bin_score = 70.0 + waste * 0.3;
        new_bin_score -= 10.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a bin
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but non-trivial.
    if post_residual > 0 {
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: small unusable leftover (below min item size 1..100 range, treat <10 as dead).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many fitting bins: mild penalty to encourage diversity of choices elsewhere.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead: if next item could fit into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.15;
    }
    // If next item almost fits (within 10), mild reward.
    else if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(10) {
        score -= 3.0;
    }

    // New-bin candidate logic: only attractive when open bins are fragmented or this is a big item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins early, more when few bins open and mean residual is high (existing space usable).
        let mut new_bin_score = 30.0
            + (bin_capacity as f64 - item_size as f64) * 0.4
            - progress * 10.0
            - (open_bins_count as f64) * 0.5;
        if mean_residual >= item_size as f64 + 5.0 {
            new_bin_score += 15.0; // plenty of usable space already open
        }
        if fragmentation < 5.0 {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    // Time horizon: late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for bins below mean residual (keeps residuals balanced).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver (min item size baseline)
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap cannot hold the lookahead item: dead space relative to lookahead.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit tilt).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when current item is large relative to
    // available fits and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = 55.0 + fragmentation * 0.8 + 20.0 * (1.0 - progress)
            - (item_size as f64) * 0.25;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // pairing lookahead with a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between the
    // remaining space and the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            // Perfect fit for the next item: place here at almost any cost.
            score -= 1000.0;
        } else {
            // Proximity bonus decaying quadratically with distance.
            let prox = 120.0 / (1.0 + (diff as f64) * (diff as f64) * 0.02);
            score -= prox;
            // Penalize leaving a dead sliver that the next item cannot use.
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size as f64 - post_residual as f64) * 1.5;
            }
        }
    } else {
        // Last item: pure tightness objective.
        score += 0.0;
    }

    // Compare against the fleet's mean residual: prefer bins that are
    // already tighter than average (consolidation), penalize loose bins.
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in the stream, be more willing to open new bins (keep options);
    // later, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // Penalize creating near-empty leftovers that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Slight penalty for very many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Prefer filling bins deeply relative to capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (min item size is 1, but tiny gaps fragment capacity) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // next item fills this bin exactly
        } else if gap < 0 && gap > -10 {
            score += 20.0; // just barely can't fit next item: bad fragmentation
        } else if gap > 0 && gap < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by open-bin pressure and stream position.
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let mut nb = 45.0 + 12.0 * pressure;
        // Late in the stream, opening fresh bins is fine; early on, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 20.0 * progress;
        // If this bin's fit is bad (large post_residual relative to mean), new bin looks better.
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality > 0.5 {
            nb -= 25.0;
        }
        // If next item is large, a fresh bin with full capacity is valuable.
        if next_item_size >= 60 {
            nb -= 15.0;
        }
        score = score.min(nb) + nb * 0.0; // new-bin score is just nb
