        score -= 0.05 * (mean_residual - bin_residual as f64);
        // Open-bin count pressure: discourage spreading across many bins.
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps that no plausible item (>=1) could still use well.
    if post_residual > 0 && post_residual < item_size.min(20) as f64 {
        score += 15.0;
    }

    // Reward tight fits (small post residual relative to item).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 30.0 * fit_ratio;

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // a large usable residual that the next item can consume.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0;
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead: reward leaving residual that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mild mean-residual alignment: prefer bins near the mean residual (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Late-stream tightening: as stream progresses, favor fuller bins more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * fit_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no item (1..=100)
    // can ever use is worthless; space usable by small items retains value.
    let dead = post_residual < 10; // nothing in [1,100] fits if < 10 residual? items 1..100, so residual 1..9 is dead
    if dead {
        score += 50.0;
    }

    // Classify post_residual into harmonic remainder classes mod 10
    // (residuals that are multiples of common item sizes are reusable).
    let pr = post_residual;
    if pr > 0 && pr <= 100 {
        if pr % 10 == 0 {
            score -= 8.0; // highly reusable residual class
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else if pr >= 50 {
            score -= 3.0; // half-bin or more still flexible
        }
    }

    // Lookahead coupling: reward when next item exactly fits the post residual,
    // penalize when next item cannot fit this bin's remainder anyway.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr && pr - next_item_size < 10 {
            score -= 25.0; // near-perfect chain
        } else if next_item_size > pr {
            score += 2.0; // next item won't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a decent fit,
    // better than a terrible fit. Encourage new bins early when few bins open.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 20.0 - (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score += 10.0; // big next item may want a fresh bin
        }
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up items are "dead space". Penalize quadratically.
    if post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 30.0;
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 4.0;
    } else if post_residual < 60 {
        score -= 15.0; // sweet zone: enough room for a mid-size follow-up
    }

    // Perfect or near-perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual < 40 {
            score -= 40.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if existing bins fit poorly.
        score += 60.0 + pressure * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin pairs well with a big next item
        }
        if post_residual == bin_capacity as f64 as u32 && open_bins_count > 0 && fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        score -= pressure * 3.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 120.0;
        } else {
            score -= 20.0;
        }
    }

    // Alignment with mean residual: bins closer to the mean residual
    // keep the bin population homogeneous and packable.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills the post residual -> huge reward.
    if next_item_size > 0 {
