    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize the brand-new bin candidate mildly so it only wins on poor fits,
    // but reward it when the current bin would leave awkward dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 200.0; // opening a fresh bin beats making tiny dead space
        }
    }

    // Late in the stream, prefer tighter packing (consolidate into few bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Penalize large dead space after placement (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < item_size.min(30) {
        // residual too small for typical future items: dead space penalty
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize leaving awkward residual
            let waste = post_residual as f64 - (next_item_size as f64 * 0.5);
            if waste > 0.0 {
                score += 0.25 * waste;
            }
        }
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (spread load); late in stream, pack existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * tightness;
    score += progress * 0.05 * post_residual as f64;

    // Many open bins with high mean residual: prefer consolidating
    // into existing bins rather than opening more.
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // or the current bin fit is poor.
        let poor_fit = if bin_residual >= item_size && post_residual < bin_capacity {
            (bin_residual - item_size) as f64 / bin_capacity as f64
        } else { 0.0 };
        score += 30.0 - 6.0 * poor_fit - 0.5 * open_bins_count as f64;
        // Late in stream, opening a fresh bin is more acceptable.
        score -= 10.0 * progress;
    }

    // Mild penalty for bins whose residual is far below mean (already
    // fragmented); prefer bins with residual near or above mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.1 * diff.abs();

    score
}

