    score += norm_pr * norm_pr * norm_pr * cap * progress;

    // Perfect fit reward, stronger late in stream
    if post_residual == 0 {
        score -= 10.0 + 10.0 * progress;
    }

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 2.0 * (1.0 - ((pr - nx) / cap)) * (0.5 + progress);
        } else {
            score += 1.5 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for scattering across many open bins, scaled by mean residual gap
    let gap = (mean_residual - bin_residual as f64).abs() / cap;
    score += gap * gap * (1.0 + open_bins_count as f64 * 0.05);

    // New-bin candidate shaping: only attractive early or when residuals are tight
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + mean_residual / cap)).min(10.0);
        score += 3.0 + 12.0 * progress * (1.0 + openness * 0.1) - 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how close it is to a "small item" slot
    let small = 30u32;
    let mid = 50u32;
    let large = 70u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
        score += (small - post_residual) as f64 * 0.6;
    }

    // Perfect-fit harmonic classes: post_residual exactly divisible slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Fractional capacity logic
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0; // tiny unusable sliver
    } else if frac >= 0.2 && frac <= 0.5 {
        score -= 2.0; // sweet spot for medium items
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // harmonic bonus if next item nearly fills remaining space
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 2.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: prefer only when open bins are crowded
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Stream progression: tighten early, loosen late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean residual coupling: if this bin's residual is below mean, it's tighter
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small to hold
    // even the smallest plausible item (dead space = wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2):
    // they are likely to become dead space unless something smaller arrives.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward residuals that exactly accommodate the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins (tight fits) over spreading; with few bins, mild leniency.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the fit
    // here would create large dead space; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        score -= 10.0;
        if post_residual < 10 {
            score += 80.0; // opening a bin for a huge item alone is fine
        }
    }

    // Tight-fit bonus: near-zero post_residual is ideal packing.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead: next item fits with tiny slack left over.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 40.0 - slack * 4.0;
        } else if slack <= 15.0 {
            score -= 20.0 - slack * 0.8;
        }
    }

    // Penalize dead space too small for typical items (hard-to-fill residue).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Compare post_residual against mean residual: leaving this bin near the
    // open-bin average keeps flexibility; extreme divergence is penalized.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (mean_residual.abs() + 1.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when the item fits poorly in a fresh
    // context (large item, no lookahead synergy) — otherwise discourage.
    if bin_residual == bin_capacity {
        let base = 12.0;
        // Large items open bins early (classic best behavior).
        let large_bonus = if item_size >= 50 { -10.0 } else { 0.0 };
        // If next item is huge, opening a fresh bin now is risky.
        let next_risk = if next_item_size >= item_size { 10.0 } else { 0.0 };
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let early = -5.0 * (1.0 - progress);
        score += base + large_bonus + next_risk + early;
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: penalize wasted residual non-linearly.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
        }
        // Penalize if placing here leaves residual that neither fits next item
        // nor is useful (small dead space).
        if post_residual > 0 && post_residual < next_item_size.min(20) {
            score += 15.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (prefer new bins
    // for large residual preservation); late, pack greedily.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * t;

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins to consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.1 * consolidation;
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early and when alternatives exist.
        score += 35.0 + 25.0 * (1.0 - t);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // But if the item is large and would leave big residual elsewhere anyway,
        // a fresh bin is neutral-fine.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Mild preference for bins whose residual was already small (tight packing).
    score += 0.3 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Base: prefer tight packing (small post_residual), smoothed non-linearly.
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * (1.0 - norm_pr));

    // Non-linear coupling with stream progress: late in the stream, dead space
    // becomes increasingly costly (quadratic ramp).
    score += 3.0 * norm_pr * norm_pr * progress;

    // Reward leaving residual that can host the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        let kernel = (-d * d * 40.0).exp();
        score -= 2.0 * kernel * (1.0 - progress * 0.5);
    }

    // Penalize bins whose residual deviates strongly from mean (fragmentation).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * fit_frac;
    }

    // New empty bin candidate: penalize unless it's the only option or the
    // current item is huge relative to open-bin residuals.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (fit_frac - 0.5).max(0.0) * 2.0;
        score += 6.0 - 6.0 * scarcity - 5.0 * big_item * progress - 2.0 * fit_frac;
        // Slight bonus late in stream to consolidate into fresh bins.
        score -= 1.5 * progress;
    }

    // Mild preference for fuller bins overall (waste-aware term).
    score -= 0.5 * fit_frac * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: which "slot" of capacity does it fall into? ---
    let quarter = bin_capacity / 4;               // 25
    let eighth  = bin_capacity / 8;               // 12
    let post = post_residual as f64;

    // Dead space penalty: residuals that no plausible item (1..=100, but realistically
    // small items) can use are wasted. Classify post_residual into harmonic bands.
    if post_residual == 0 {
        score -= 60.0;                            // perfect fit: strongly reward
    } else if post_residual <= eighth {
        score -= 35.0;                            // near-perfect: tiny sliver, almost closed
    } else if post_residual <= quarter {
        score -= 15.0;                            // usable by small items
    } else if post_residual <= quarter * 2 {
        score -= 5.0;                             // mid band
    } else if post_residual <= quarter * 3 {
        score += 8.0;                             // bulky leftover, awkward
    } else {
        score += 15.0;                            // nearly empty bin: poor exploitation
    }

    // --- Modulo coupling: does post_residual align with next_item_size's harmonic class? ---
    if next_item_size > 0 {
        let nxt = next_item_size;
        // Exact / near match between leftover and the lookahead item is gold.
        let diff = (post_residual as i64 - nxt as i64).abs() as f64;
        if post_residual >= nxt {
            score -= (25.0 * (1.0 - diff / (post_residual.max(1) as f64))).max(0.0);
            // Exact match bonus
            if post_residual == nxt {
                score -= 30.0;
            }
            // Modular alignment: post_residual % nxt small => future splits cleanly
            if nxt > 0 && post_residual % nxt == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual at all: leftover is dead for the lookahead
            score += 12.0;
        }
        // Harmonic class match: both in same eighth-of-capacity class
        let class_post = post_residual / eighth;
        let class_next = nxt / eighth;
        if class_post == class_next && nxt <= post_residual {
            score -= 6.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // This is the only bin that fits: opening a new bin is costly, prefer using it
        score -= 20.0;
        // But penalize if the fit is extremely loose (huge dead space created)
        if post_residual > quarter * 2 {
            score += 10.0;
        }
    }

    // --- New-bin candidate: empty bin gets a neutral-to-mild score; prefer it only
    // when every open bin would leave big dead space. ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (amortized, decays as stream progresses)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable
        if next_item_size >= quarter * 3 {
            score -= 10.0;
        }
    }

    // --- Mild pressure toward consolidating bins when many are open ---
    score += 0.02 * open_bins_count as f64;

    // --- Tie-break with mean residual: prefer bins close to the mean (balanced state) ---
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Gaps that no future item (min size 1..100 unknown, but typical small items)
    // could fill: residual below 10 is nearly dead.
    if post_residual < item_size.min(10) {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Fit tightness: reward small post_residual relative to item size.
    if item_size > 0 {
        score += (post_residual as f64 / item_size as f64) * 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer
    // filling existing bins and discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 1.5;
        // Opening a new bin is acceptable only if the item is large relative
        // to typical residuals (i.e., poor fit everywhere else).
        if mean_residual > item_size as f64 * 1.3 {
            score -= 18.0;
        }
    } else {
        // Reward filling bins whose residual is close to the item.
        score -= (bin_residual as f64 - item_size as f64).abs().min(20.0) * 0.4;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Late in the stream, consolidate: penalize leaving any residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Slack left after also placing the next item; smaller leftover is better.
            let two_step_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * two_step_left;
        } else {
            // Next item cannot follow into this bin: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Reward tight fits relative to current mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless it's truly empty usage.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost so only bad fits elsewhere trigger opening.
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin for a large item followed by another large item is fine.
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Dead space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual, non-linear).
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 18.0 * tightness * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize wasting space the next item could have used in this bin.
            let waste = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { post_residual.min(next_item_size.max(1) as u32) } else { post_residual };
        let _ = best_possible;
        // Base penalty so we prefer filling existing bins when fit is decent.
        score += 45.0;
        // But if this bin would be a great host for the next item too, soften.
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 20.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // Many open bins with high mean residual: prefer reusing them.
        score += 0.05 * open_bins_count as f64;
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.3;
        }
    }

    // Slight preference for bins with residuals close to the item (best-fit flavor).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let norm_pr = pr / cap;
    let npr2 = norm_pr * norm_pr;
    let npr3 = npr2 * norm_pr;

    // Early stream: prefer tight fits (low post_residual) mildly; later: strongly.
    score += progress * (npr2 * 30.0 + npr3 * 60.0);
    score -= (1.0 - progress) * npr2 * 10.0;

    // Penalize leaving residuals that no plausible item can use (dead space),
    // smoothly via cubic in normalized residual.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * 25.0;

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress) + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Slight penalty for spreading across many open bins when mean residual is high.
    score += (open_bins_count as f64).ln() * 0.5 * (mean_residual / cap);

    // New-bin candidate: neutral baseline, penalized when good fits exist.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in
    // "usable" classes (multiples of small divisors) are more likely to
    // absorb future items, so reward them.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward small post_residual strongly (best-fit core), super-linear.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class penalty: residuals in (0,10) are almost unusable
    // for items >= 1..100 typical sizes; penalize tiny nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo arithmetic on post_residual: leftover divisible by common
    // item granularities (5, 10, 20) is more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 25.0; }
        else if pr % 5 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 10.0; }
    }

    // Integer-division thresholds: classify residual into harmonic bands.
    let band = pr / 25; // 0..=4
    match band {
        0 => score += 20.0,          // very tight leftover: good fill
        1 => score -= 5.0,           // 25-49: decent
        2 => score -= 10.0,          // 50-74: roomy
        _ => score += 15.0,          // nearly empty bin: wasteful use
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward chaining.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this leftover; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // Harmonic pair check: item + next divisible into capacity nicely
        if (item_size + next_item_size) % 100 == 0 && bin_residual >= item_size + next_item_size {
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive
    // when current bin fits are poor; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 30.0 + crowd * 4.0;
        if fitting_bins_count > 0 {
            score += 45.0; // discourage opening when alternatives exist
        }
        if post_residual as f64 > mean_residual {
            score -= 20.0; // fresh bin keeps mean residual high
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    score += progress * 15.0;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mean-residual alignment: bins far above mean residual are less
    // attractive targets (keep balanced residual portfolio).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - res) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (11 - post_residual as i32).pow(2) as f64 * 4.0;
    }

    // "Awkward gap" band: residuals that few typical items can use.
    if post_residual >= 10 && post_residual <= 25 {
        score += 6.0;
    }

    // Reward tight fits (small relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is near the mean (keeps residuals homogeneous
    // and predictable for future items).
    score -= 1.5 * (bin_residual as f64 - mean_residual).abs().min(30.0);

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item does NOT fit in the gap and gap is small, penalize.
    if next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It is only attractive when no open bin offers a decent fit, i.e. when
    // the best available placement is poor or this is the last-chance bin is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins already fit.
        let mut nb = 55.0 + open_bins_count as f64 * 1.5;
        // Early in the stream, opening bins is cheaper (build a pool).
        if progress < 0.2 {
            nb -= 20.0;
        }
        // If the next item is large, having a fresh bin is valuable.
        if next_item_size >= 60 {
            nb -= 15.0;
        }
        // If several bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            nb += 30.0 * (fitting_bins_count as f64 - 2.0);
        }
        score = score.max(nb);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny post residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // next item fits exactly or nearly exactly after this placement
            let chain_slack = post_residual as f64 - next;
            if chain_slack == 0.0 {
                score -= 45.0;
            } else if chain_slack < 10.0 {
                score -= 25.0 - chain_slack;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward medium gaps
            let gap = post_residual as f64;
            if gap >= next && gap < next + 10.0 {
                score += 5.0;
            }
            // dead space: gap too small for typical items (min size ~1..100 unknown, use 10 baseline)
            if gap < 10.0 {
                score += 8.0; // unusable sliver
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // prefer filling loose bins when post_residual stays near mean.
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it attractive only when this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Opening fresh is neutral-good baseline; a near-perfect fit in existing bin beats it.
        score = cap - item_size as f64;
        if next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 15.0; // fresh bin can host item + next item
        }
        // discourage opening new bins when many bins are already open and fit is decent
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_f / cap);

    // Mild penalty for very large leftovers that no typical item can use.
    if post_f > cap * 0.8 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space non-linearly; small residuals (<10) are nearly useless.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // dead space smaller than min item is wasted
        } else {
            score -= 4.0 / (pr / 10.0); // mild reward for larger usable leftovers
        }
    }

    // Lookahead: reward if next item fits exactly in post_residual; penalize if it barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain placement
        } else if (next_item_size as u32) <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            let miss = (next_item_size as u32 - post_residual) as f64;
            score += 6.0 * (1.0 - miss / cap); // next item won't fit here
        }
        // Bonus if this bin's residual would fit next item better than average
        if (next_item_size as u32) <= post_residual && (next_item_size as u32) > mean_residual as u32 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large or fits are bad.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        if fill_ratio > 0.5 {
            score -= 20.0 * fill_ratio; // big items start fresh bins happily
        } else {
            score += 15.0 + 20.0 * (1.0 - fill_ratio); // small items should fill open bins
        }
        // Late in the stream, opening fresh bins is less costly (no need to consolidate)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * fill_ratio;
    }

    // Global state: many open bins with high mean residual -> encourage consolidating
    // into bins with residual below mean (tight bins), discourage sparse bins.
    if bin_residual != bin_capacity {
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 3.0 * (mean_residual - res) / cap;
        } else {
            score += 3.0 * (res - mean_residual) / cap;
        }
        // With many open bins, prefer bins that reduce open-bin pressure (tight fits)
        if open_bins_count > 4 {
            score -= 8.0 * (item_size as f64 / res.max(1.0));
        }
    }

    // Tightness ratio reward: fraction of bin used by this placement.
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // normalized post-residual
    let norm_pr = pr / cap;

    // smooth non-linear interaction with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress * (1.0 - progress) * 4.0);
    score += 6.0 * poly;

    // penalize dead space more strongly late in the stream
    score += progress * progress * (pr / cap) * 8.0;

    // reward tight fits (small post-residual) with a smooth term
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress * 0.5);

    // last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 4.0 * (gap / cap) * (gap / cap);
        if pr >= nxt {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // penalize fragmentation relative to mean residual
    score += 2.0 * (pr - mean_residual) / cap;

    // mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction of the item: small items are flexible, big items are precious.
    let frac = item_size as f64 / bin_capacity as f64;

    // --- Harmonic class of post_residual (integer division thresholds) ---
    // Class 0: post_residual == 0  -> perfect closure, reward heavily.
    // Class 1: 0 < post <= 10      -> small dead space, mildly bad.
    // Class 2: 10 < post <= 25     -> dead space that can still host a small item.
    // Class 3: 25 < post <= 50     -> usable gap.
    // Class 4: post > 50           -> large gap, fine.
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0 + 20.0 * frac;
    } else if post_residual <= 10 {
        // Dead space: penalize proportionally to how "unfillable" it is.
        // Residuals of 1..9 can only be filled by tiny items; add harmonic penalty.
        score += (11 - post_residual) as f64 * 0.8;
    } else if post_residual <= 25 {
        score += 2.0;
    } else if post_residual <= 50 {
        score -= 3.0;
    } else {
        score -= 6.0;
    }

    // --- Modulo arithmetic on post_residual: gaps that are multiples of common
    // small sizes (10, 20, 25, 50) are more reusable ---
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 2.5; }
        if post_residual % 25 == 0 { score -= 1.5; }
        if post_residual % 20 == 0 { score -= 1.0; }
        // Odd tiny gaps (1,3,5,7,9) are nearly unusable dead weight.
        if post_residual < 10 && post_residual % 2 == 1 { score += 3.0; }
    }

    // --- Lookahead coupling (k=2): if next item fits the post gap, reward strongly ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 - snug.min(8.0); // perfect next-fit bonus up to 8
        } else {
            // Next item will NOT fit here: this gap likely becomes dead space.
            score += 4.0 * (1.0 - post / bin_capacity as f64);
        }
        // Harmonic class of next item: multiples of 25/50 pair well with round gaps.
        if next_item_size % 25 == 0 && post_residual % 25 == 0 {
            score -= 2.0;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good for large items or when existing gaps are poor.
        let mean_gap_quality = mean_residual / bin_capacity as f64;
        if item_size >= 50 {
            score -= 5.0 + 10.0 * (item_size as f64 - 50.0) / 50.0;
        }
        // If open bins are fragmented (many small residuals), fresh bin is attractive.
        if open_bins_count > 0 && mean_gap_quality < 0.35 {
            score -= 4.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    // --- Progress-based tie-breaking: early on, prefer tight packing into
    // existing bins; late, prefer closing bins with near-perfect fits ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - post / bin_capacity as f64;
    score -= progress * tightness * 3.0;

    // Slight preference for bins whose residual is above the mean (keep
    // fragmented bins for small items).
    if (bin_residual as f64) > mean_residual && item_size <= 30 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear waste penalty (kept from parent, slightly sharpened).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 35.0 * waste * waste;

    // Perfect / near-perfect fit bonuses.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Two-step lookahead: reward residuals that can host the next item,
    // with a graded bonus for how flexibly the residual can be reused.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Prefer leaving residuals close to the next item size (less dead space).
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.3 * gap - 0.004 * gap * gap;
        }
        // Dead-space penalty: residual too small for the next item.
        if post_residual < next_item_size.min(25) {
            score += 18.0;
        }
    }

    // Time horizon: early stream = conservative (preserve large residuals),
    // late stream = greedy compaction.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 22.0 * t;

    // Consolidation pressure when many bins are open.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.1 * consolidation;
        score -= 0.6 * open_bins_count as f64;
    }

    // New-bin candidate: open a fresh bin only when fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + 25.0 * (1.0 - t);
        if fitting_bins_count > 0 {
            // Softer extra penalty when many bins compete; the choice among
            // open bins matters more than blocking new-bin usage.
            score += if fitting_bins_count == 1 { 25.0 } else { 15.0 };
        }
        // Fresh bin is attractive for large items that would fragment open bins.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // Lookahead rescue: if the next item is large and no open bin could
        // plausibly hold it, keeping residuals intact via a new bin is good.
        if next_item_size > bin_capacity / 2 && post_residual >= item_size {
            score -= 12.0;
        }
    }

    // Mild preference for bins whose residual was already small (tight packing),
    // with a slight boost for medium residuals that remain reusable.
    score += 0.3 * (bin_residual as f64 - post_residual as f64);
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear waste penalty (kept from parent, slightly sharpened).
    let waste = post_residual as f64 / cap;
    score += 35.0 * waste * waste;

    // Perfect / near-perfect fit bonuses.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving just enough room: penalize slack quadratically.
            score -= 12.0 + 0.25 * slack - 0.004 * slack * slack;
        }
        // Dead space: residual too small for the next item is likely wasted.
        if post_residual > 0 && post_residual < next_item_size.min(25) {
            score += 18.0;
        }
    }

    // Time horizon: early = conservative, late = greedy.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 22.0 * t;

    // Consolidation pressure when many bins are open.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.1 * consolidation;
        score -= 0.6 * open_bins_count as f64;
    }

    // NEW-BIN CANDIDATE handling (bin_residual == bin_capacity means empty bin).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; stronger early in the stream.
        let mut new_bin_score = 35.0 + 25.0 * (1.0 - t);

        if fitting_bins_count > 0 {
            // If alternatives exist, judge them: only open a new bin when every
            // fitting open bin would leave a poor residual for the next item.
            new_bin_score += 20.0;
            // If the next item is large and would fit a fresh bin exactly,
            // opening a new bin becomes attractive (reserved pairing).
            if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
                let pair_waste = (bin_capacity - item_size - next_item_size) as f64 / cap;
                new_bin_score -= 40.0 * (1.0 - pair_waste);
            }
        } else {
            // No open bin fits: new bin is the only option; make it cheap.
            new_bin_score -= 60.0;
        }

        // Large items pack cleanly into fresh bins.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 30.0;
        }

        score += new_bin_score;
    }

    // Mild preference for bins whose residual was already small.
    score += 0.3 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear waste penalty (mutated exponent mix: cubic tail for large waste).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 28.0 * waste * waste;
    if waste > 0.4 {
        score += 40.0 * (waste - 0.4) * (waste - 0.4) * (waste - 0.4);
    }

    // Perfect / near-perfect fit bonuses (tightened near-fit threshold).
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual < 6 {
        score -= 30.0;
    } else if post_residual < 15 {
        score -= 12.0;
    }

    // Last-chance bin: favor strongly when it's the only option.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
        // Extra: if the next item also fits the leftover, this bin is precious.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Lookahead: exact fit for next item is a big win; partial fit scaled by gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 + 0.25 * gap;
            // If the gap itself could host a small future item (gap >= 8), soften.
            if gap >= 8.0 {
                score += 4.0;
            }
        }
        // Dead space: residual too small for the next item AND generally tiny.
        if post_residual > 0 && post_residual < next_item_size.min(18) {
            score += 18.0;
        }
        // Two-step lookahead: penalize bins whose residual would be unusable
        // for anything plausible (below smallest typical item ~ 8).
        if post_residual > 0 && post_residual < 8 {
            score += 8.0;
        }
    }

    // Time horizon: late in the stream, pack greedily into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 22.0 * t;

    // Consolidation pressure when many bins are open.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.12 * consolidation;
        score -= 0.6 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual was already small.
    score += 0.3 * (bin_residual as f64 - post_residual as f64);

    // New-bin candidate: only win when fits are poor or item is large.
    if bin_residual == bin_capacity {
        let mut penalty = 38.0 + 22.0 * (1.0 - t);
        if fitting_bins_count > 0 {
            penalty += 22.0;
            // If some open bin would leave nearly the same residual, new bin
            // is wasteful; but if all fits are terrible (post_residual tiny
            // relative to capacity), allow the new bin to compete.
            let best_possible = post_residual as f64 / bin_capacity as f64;
            if best_possible > 0.5 {
                penalty += 25.0;
            } else if best_possible < 0.15 {
                penalty -= 20.0;
            }
        }
        // Large items pair well with fresh bins.
        if item_size > bin_capacity / 2 {
            penalty -= 32.0;
        }
        // Very small items should almost never open a new bin.
        if item_size < bin_capacity / 8 {
            penalty += 15.0;
        }
        score += penalty;
    }

    score
}

