        // Near-chain: residual can hold next item with small slack.
        score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
    }

    // Open-bins pressure: prefer consolidation when many bins are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
