pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny residuals are pure waste; penalize super-linearly.
    if post_residual < 10 {
        score += (11 - post_residual as i32).pow(2) as f64 * 4.0;
    }

    // Awkward gap band.
    if post_residual >= 10 && post_residual <= 25 {
        score += 6.0;
    }

    // Tightness reward.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (borrowed from best): exact fit for next item is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
        }
        // Residual just below next item size is nearly unusable.
        if post_residual > 0 && post_residual < next_item_size.min(20) {
            score += 15.0 + 0.3 * (next_item_size.min(20) - post_residual) as f64;
        }
    }

    // Last-chance bin: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure grows over the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Homogeneity preference.
    score -= 1.5 * (bin_residual as f64 - mean_residual).abs().min(30.0);

    // New-bin candidate handling: mostly discourage, but allow when the fit
    // into open bins is poor or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let mut nb = 55.0 + open_bins_count as f64 * 1.5;
        if progress < 0.2 {
            nb -= 20.0;
        }
        if next_item_size >= 60 {
            nb -= 15.0;
        }
        // Large items fit well into fresh bins.
        if item_size > bin_capacity / 2 {
            nb -= 30.0;
        }
        // Tiny items should go into existing space.
        if item_size < bin_capacity / 4 {
            nb += 25.0;
        }
        if fitting_bins_count > 2 {
            nb += 30.0 * (fitting_bins_count as f64 - 2.0);
        }
        // If the current item would leave a large unusable gap in any open bin,
        // a fresh bin is acceptable: scale the penalty down.
        if post_residual > 0 && post_residual < item_size {
            nb -= 10.0;
        }
        score = score.max(nb);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold a plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead (k=2): penalize residuals that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        if next_item_size > post_residual + 5 {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward residuals that exactly accommodate the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Bonus scaled by how much of the residual the next item consumes.
        score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
    }

    // Open-bins pressure: consolidate when many bins are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): discouraged unless the current fit
    // would strand large dead space or the item is huge.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 25.0 * (1.0 - t);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        if item_size < bin_capacity / 4 {
            score += 25.0;
        }
        if post_residual < 10 {
            score += 80.0; // opening a bin for a huge item alone is fine
        }
    }

    // Tight-fit bonus: near-zero post_residual is ideal packing.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    score
}

