        score += (30 - post_residual) as f64 * 0.6;
    }

    // Harmonic classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0;
    } else if frac >= 0.2 && frac <= 0.5 {
        score -= 2.0;
    }

    // Strong lookahead coupling (adopted from best heuristic)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // exact next-fit: near-perfect packing
