            score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
        }
        // Sliver that cannot fit the next item: penalize harder
        if post_residual > 0 && post_residual < next_item_size.min(20) {
            score += 15.0 + 0.3 * (next_item_size.min(20) - post_residual) as f64;
