        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 5 {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate logic
    let t = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * (1.0 - t);
