        if item_size < bin_capacity / 4 {
            score += 25.0;
        }
        score += 0.05 * open_bins_count as f64;
    }

    // Stream progression: tighten early, loosen late
    score -= t * 2.0;

    // Mean residual coupling
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

