    score -= tightness * 18.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 55.0;
    }

    // Strong lookahead: exact next-item fit is the best possible placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64;
        }
        // Gap too small for the next item: penalize wasted residual.
        if post_residual > 0 && post_residual < next_item_size.min(21) {
            score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
        }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 {
