        score += 0.42 * (next_item_size - post_residual) as f64;
    }

    // Perfect chain: residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }

    // Reward residuals that comfortably hold the next item (soft chain).
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64;
    }

    // Near-chain bonus: post residual barely above next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 4 {
        score -= 7.0;
    }

