    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): discourage by default; allow only for
    // large items that would otherwise leave big dead space in a partial bin.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 20.0 * (1.0 - t);
        if open_bins_count > 0 {
            score += 15.0;
