        if item_size > bin_capacity / 2 {
            score -= 60.0; // big item alone in a fresh bin is fine
        }
        if item_size < bin_capacity / 4 {
            score += 20.0; // tiny items should never open new bins
        }
        // If no open bin can hold the next item either, a fresh bin is safer.
        if next_item_size > 0 && next_item_size > mean_residual as u32 && open_bins_count > 0 {
            score -= 10.0;
