    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Mean-residual coupling: prefer bins whose post residual stays near the
    // stream's average residual, keeping future fits flexible.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

