pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item fits snugly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let slack = post - nxt;
            // reward perfect / near-perfect chaining
            score -= 30.0 * (1.0 - slack / 100.0);
            if slack == 0.0 {
                score -= 25.0; // exact chain: extremely desirable
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted gap
            let gap = nxt - post;
            score += 0.35 * gap;
        }
        // penalize large leftover space that no plausible item (>=1) can chain into
        score += 0.10 * post;
    } else {
        // last item: just minimize waste
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare post_residual against mean residual: prefer bins that end below-average residual
    // (tighter bins), i.e. reward placing into above-average-residual bins.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it unattractive unless current bin would leave a dead gap
    // that the next item can't use. Empty-bin residual == capacity.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // but if no open bin gives a good 2-step fit, allow new bin:
        // (the lookahead bonus above already lowered good bins; add escape hatch)
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            // next item can't fit in this empty bin either after placement — keep penalty
            score += 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins
    score -= 0.5 * open_bins_count as f64 / (1.0 + open_bins_count as f64);

    // Time-decay: as stream progresses, be greedier about filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) * (item_size as f64 / bin_capacity as f64);

    // Perfect lookahead fit: place item so the next item exactly fills the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // leftover after next item; penalize tiny unusable leftovers
            let after_next = post_residual - next_item_size;
            if after_next < 5 {
                score += 25.0; // creates dead sliver
            } else {
                score -= 0.2 * after_next as f64;
            }
        } else {
            // next item cannot follow into this bin; slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // with many candidates, prefer the tightest, others mild penalty
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize bins whose residual deviates from the mean (keep bin pool balanced),
    // but only mildly so tight fits still win.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: early in the stream, keep residuals flexible (penalize near-full bins less
    // later, since end-of-stream waste matters less).
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 && t < 0.5 {
        score += 8.0 * (1.0 - t); // small residuals early may be wasted flexibility
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits badly everywhere else. A fresh bin has post_residual == bin_capacity - item_size
    // and bin_residual == bin_capacity; make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 15.0 + 2.0 * open_bins_count as f64;
        // if the item is large, a new bin wastes less capacity elsewhere
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 12.0;
        }
        // late in the stream, prefer squeezing into existing bins
        score += 10.0 * t;
    }

    // Mild bonus for filling bins that are already mostly full (waste avoidance).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Tight fits (near-zero post residual) are extra valuable, smoothly
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Stream progress coupling: early on, tolerate loose fits to build flexible bins;
    // late in the stream, tighten aggressively (polynomial ramp)
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 20.0 * ramp * norm_pr * norm_pr;

    // Dead-space penalty: residual too small for any plausible future item
    let small_floor = 10.0 / cap;
    if norm_pr < small_floor {
        score += 8.0 * (small_floor - norm_pr) * cap;
    }

    // Last-chance bin: strongly reward using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits exactly into the resulting post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - fit_gap / cap);
    }

    // Penalize scattering across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    // New-bin candidate: neutral-ish baseline, slightly discouraged unless residual
    // landscape is bad (few fitting bins, large item)
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 5.0 - 18.0 * scarcity - 25.0 * ramp * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0: post_residual divisible by 10 -> likely to fit future items well.
    // Class 1: post_residual odd -> awkward leftover.
    // Class 2: divisible by 5 but not 10.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        0.0
    } else {
        8.0
    };
    score += harmonic_bonus;

    // Integer-division thresholds: small dead zones are penalized quadratically.
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 3.0;
    }

    // Fractional fill level: prefer tight packing (item fills most of the bin).
    let fill = item_size as f64 / cap;
    score -= fill * fill * 30.0;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
        } else {
            // Next item cannot use this bin's leftover; slight penalty scaled by gap.
            score += ((next_item_size - pr).min(20)) as f64 * 0.4;
        }
    } else {
        // Last item: leftover is pure waste; prefer zero residual strongly.
        score += (pr as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when mean residual across open bins
    // is small (fragmented) or no open bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 - fragmentation * 45.0;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer reusing bins slightly more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
