            score += post_residual as f64 * 0.15;
        }
    } else {
        // last item: prefer tightest fill
        score -= 50.0;
    }

    // Compare residual against mean residual: bins with unusually large residual
    // are good targets; bins already tight are poor targets.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        // more attractive later in the stream when many bins are open and fragmented
        if open_bins_count > 0 {
            score -= (open_bins_count as f64).ln() * 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Small penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
