        let mean_relief = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 18.0 - 55.0 * mean_relief + 20.0 * progress - 0.4 * crowded;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Slight preference for filling existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
