    // Coupling: penalize bins whose residual deviates far below the mean (isolated empties)
    // when many bins are open — prefer balanced packing.
    if !is_new_bin && open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let mut score = post_residual as f64 ; if next_item_size > 0 { if next_item_size == post_residual { score -= 58.0 ; } else if next_item_size <= post_residual { score -= 11.0 + 0.24 * (post_residual - next_item_size) as f64 ; } if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; } if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; } if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; } if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; } if post_residual > 0 && post_residual < next_item_size { score += 0.10 * (next_item_size - post_residual) as f64 ; } // dead-space shaping: residual that no plausible future item can use is wasted
