        let diff = (pr - next_item_size as f64).abs();
        score -= (cap - diff).max(0.0) * 0.15 * (1.0 - progress);
    }
    // Last-chance bin: reward strongly to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }
    // Prefer bins below mean residual (consolidate emptier bins)
