    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        return -1_000_000.0;
    }

    // Harmonic class of the residual: capacity fraction buckets.
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as i64; // 0..9 decile class

    // Dead-space penalty: residuals too small for any plausible item (1..100).
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 120.0;
    }

    // Reward residuals in "useful" harmonic classes (large enough for mid items).
    match class {
        0 => score += 200.0,   // 0-10% left: near-dead
        1 => score += 80.0,    // 10-20%
        2 => score += 20.0,
        3 => score -= 30.0,    // 30-40%: good slot for 30-39 items
        4 => score -= 40.0,
        5 => score -= 50.0,    // 50%: prime class
        6 => score -= 45.0,
        7 => score -= 35.0,
        8 => score -= 20.0,
        _ => score -= 10.0,    // 90-100% (new bin)
    }

    // Integer-division threshold: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead fit: reward, more if exact (modulo arithmetic).
            if post_residual % next_item_size == 0 {
                score -= 150.0;
            } else {
                score -= 60.0;
            }
            // Reward proportionally to how much of the residual the next item consumes.
            let consume = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * consume;
        } else {
            // Next item cannot follow here: penalize creating such traps,
            // scaled by how close the residual is to being usable.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(100.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when few bins fit or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 250.0 * scarcity;
        // Mildly discourage hoarding many open bins mid-stream.
        score += open_bins_count as f64 * 15.0;
        score += progress * 50.0;
        // New bin baseline: its residual is full capacity; keep it competitive
        // only when existing residuals are poor.
        if mean_residual > frac * cap {
            score -= 40.0;
        }
    }

    // Tie-break with mean residual alignment: prefer bins whose residual is near typical.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Small noise-free deterministic tie-break via step parity.
    if step_index % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..=12) are heavily penalized: they waste capacity.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }
    // Medium gaps (13..=25) mildly penalized since few items can use them.
    else if post_residual > 12 && post_residual <= 25 {
        score += 6.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 12 {
            score -= 25.0 - 1.5 * gap as f64;
        }
    }
    // Penalize if post_residual is a dead gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // --- Tightness reward: the smaller the fill fraction used, the better ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // --- Open bins pressure: discourage proliferation of open bins ---
    score += 0.8 * open_bins_count as f64;

    // --- Last-chance bin: strongly prefer using it over opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when no open bin fits well,
        // but expensive when many bins are already open and usable.
        score = bin_capacity as f64 - 10.0 + 1.0 * open_bins_count as f64;
        // If this bin is the only fitting option, opening a new bin is natural.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, avoid leaving stragglers: prefer consolidation.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    // --- Mean residual coupling: prefer bins deviating below the mean residual
    // (tighter bins), avoiding dumping into already-loose bins. ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between the
    // remaining space and the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            // Perfect fit for the next item: place here at almost any cost.
            score -= 1000.0;
        } else {
            // Proximity bonus decaying quadratically with distance.
            let prox = 120.0 / (1.0 + (diff as f64) * (diff as f64) * 0.02);
            score -= prox;
            // Penalize leaving a dead sliver that the next item cannot use.
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size as f64 - post_residual as f64) * 1.5;
            }
        }
    } else {
        // Last item: pure tightness objective.
        score += 0.0;
    }

    // Compare against the fleet's mean residual: prefer bins that are
    // already tighter than average (consolidation), penalize loose bins.
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in the stream, be more willing to open new bins (keep options);
    // later, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // Penalize creating near-empty leftovers that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Slight penalty for very many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Prefer filling bins deeply relative to capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a fresh bin: full residual is "waste" unless used later.
        // Make it attractive only when existing fits are poor (large post_residual elsewhere)
        // or when this bin is the last chance but the fit is bad.
        let mut new_bin_score = bin_capacity as f64 * 0.75;
        // Late in the stream, opening bins is more costly (less time to fill them).
        new_bin_score += progress * bin_capacity as f64 * 0.25;
        // If many bins are open, prefer reusing one of them.
        new_bin_score += open_bins_count as f64 * 2.0;
        // Lookahead: an empty bin can absorb the next item too, slightly favorable early.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= 5.0 * (1.0 - progress);
        }
        return new_bin_score;
    }

    // ---- Perfect fit: strongest possible reward ----
    if post_residual == 0 {
        return -1000.0;
    }

    // ---- Tightness reward: quadratic bonus for small leftover space ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // ---- Dead-space penalty: leftover that the next item cannot use ----
    if next_item_size > 0 && post_residual < next_item_size {
        // Wasted space relative to what the lookahead needed.
        let waste = (next_item_size - post_residual) as f64;
        score += 8.0 + waste * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover remains usable: reward proportional to reusability.
        score -= 6.0;
    }

    // ---- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ----
    if fitting_bins_count == 1 {
        score -= 25.0;
        // Extra urgency late in the stream.
        score -= 10.0 * progress;
    }

    // ---- Global residual alignment: prefer bins whose residual deviates from the mean ----
    // Placing into a bin with residual far above the mean reduces fragmentation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.15 * dev.min(50.0);
    } else {
        score += 0.10 * (-dev).min(50.0);
    }

    // ---- Mild pressure to keep the number of open bins low ----
    score += open_bins_count as f64 * 0.3;

    // ---- Late-stream conservatism: favor tight fits even more as the stream ends ----
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize large post residual, but non-linearly (quadratic coupling with progress)
    let mut score = x * (1.0 + 2.0 * progress) - 1.5 * x * x;

    // Smooth interaction: waste term scaled by stream progress (early on, keep bins flexible)
    score += 0.8 * x * x * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * (1.0 + 2.0 * progress);

    // Lookahead coupling: reward post residual that can host next item (smooth logistic-ish gate)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (x * cap - n).max(0.0) / cap;
        let gate = 1.0 / (1.0 + (-8.0 * (x - n / cap)).exp());
        score -= 2.0 * gate * fits_next;
        // penalize post residual just barely below next item (dead space)
        let gap = (n / cap - x).max(0.0);
        score += 1.2 * gap * (1.0 - gap);
    }

    // Last-chance bin: strong smooth reward when few fitting bins
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 1.5 * scarcity * tightness;

    // Mean residual coupling: prefer bins below mean residual (denser bins first), smooth
    let mr = mean_residual / cap;
    score += 0.6 * (x - mr) * (1.0 + progress);

    // New-bin candidate handling: penalize opening a new bin smoothly, less as progress grows
    if bin_residual == bin_capacity {
        score += 2.5 * (1.0 - progress) + 0.5 * open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
