pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let r = post_residual;

    // Perfect fit: overwhelming reward
    if r == 0 {
        score -= 1000.0;
    }

    // Dead space: tiny nonzero residual is nearly unusable -> heavy penalty
    if r > 0 && r < 10 {
        score += 50.0;
    }

    // Harmonic class bonus: residuals aligned to common item granularities
    // (multiples of 10 and half-capacity classes) are more likely reusable.
    if r > 0 {
        if r % 10 == 0 { score -= 8.0; }
        if r % 20 == 0 { score -= 4.0; }
        if r == bin_capacity / 2 { score -= 6.0; }
        if r >= bin_capacity / 2 { score -= 5.0; } // large residual = flexible bin
    }

    // Lookahead (k=2): reward if the next item also fits after this placement
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 15.0 + 0.5 * slack.min(20.0);
        } else {
            // next item won't fit here: residual likely becomes dead space
            score += 10.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Brand-new empty bin candidate: mild penalty so it only wins when
    // existing fits are poor (dead space, no lookahead fit, etc.)
    if bin_residual == bin_capacity {
        score += 20.0 - 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size <= r {
            score -= 10.0; // fresh bin pairs well with the upcoming item
        }
    }

    // Late-stream tightening: as the stream progresses, prefer tighter packing
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.05 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10) are pure waste — penalize heavily.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Small-but-usable residuals (< 20) risk becoming dead space later;
    // mild penalty scaled by how tight the gap is.
    else if post_residual < 20 {
        score += 6.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward very tight fits (near-perfect packing) strongly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    if tightness < 0.10 {
        score -= 25.0 * (0.10 - tightness) * 10.0;
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Dead space that cannot host the lookahead item is worse if the next
    // item would otherwise have fit here.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Bonus if this placement leaves room exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mildly encourage filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate (empty bin): penalize unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Opening a fresh bin is attractive when mean residual across open
        // bins is small (existing bins nearly full / fragmented).
        if mean_residual < 15.0 {
            score -= 45.0;
        }
        // If this item barely fits nowhere well, new bin helps.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to what we consume (minimize
    // fragmentation relative to the fleet mean).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter chain fit -> bigger reward.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much of the next item is left stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.5 * stranded;
        }
        // Exact pairing is gold.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Perfect closure of the current bin is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Relative-to-mean-residual coupling: prefer consuming bins with
    // above-average residual (drain fat bins), penalize draining lean bins.
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the current fit is terrible; otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 60.0;
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < 20.0;
        if bad_fit || crowded {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, tighten up: waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (post_residual as f64 + 1.0).ln();

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 40.0; // next item closes this bin perfectly
            } else if slack <= 10 {
                score -= 12.0;
            } else {
                score -= 8.0 * (bin_capacity as f64 / (slack as f64 + 1.0)).sqrt();
            }
        } else {
            // post_residual too small for next item: dead space unless tiny
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // small dead space acceptable
            } else {
                score += 0.35 * dead;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // Prefer bins with lower residual among comparable fits (best-fit flavor).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Discard near-empty open bins usage when many bins are open early?
    // Time horizon: late in stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is good when item is large
    // relative to residuals or when no open bin fits well.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual = capacity - item_size.
        // Penalize new bin when item is small (waste of fresh capacity).
        let fill = item_size as f64 / bin_capacity as f64;
        if fill < 0.4 {
            score += 45.0 * (0.4 - fill);
        } else {
            score -= 10.0 * fill;
        }
        // If many bins open with decent mean residual, discourage new bin mildly.
        if open_bins_count > 3 && mean_residual > 30.0 {
            score += 12.0;
        }
        // Late in stream, prefer reusing bins.
        score += 20.0 * progress;
    } else {
        // Reward using existing bins slightly to keep bin count low.
        score -= 6.0;
    }

    // Coupling: penalize leaving residuals in the awkward 10..=30 zone
    // (hard to fill later with items 10..80 typical sizes).
    if post_residual >= 10 && post_residual <= 30 {
        score += 0.4 * (30 - post_residual) as f64;
    }

    // Slight penalty scaling with number of open bins to consolidate.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0 ;
        } else if next_item_size <= post_residual {
            score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ;
        }
        if post_residual > 0 && post_residual < next_item_size . min (21) {
            score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ;
        }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 {
            score += 0.42 * (next_item_size - post_residual) as f64 ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 {
            score -= 7.0 ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64 ;
        }
        // lookahead: when many bins can host the next item, mild competition bonus for tight fits
        if fitting_bins_count > 1 && next_item_size <= post_residual && post_residual - next_item_size < 12 {
            score -= 1.5 + 0.08 * (12 - (post_residual - next_item_size)) as f64 ;
        }
        // if next item cannot fit here but fits mean residual elsewhere, penalize leaving this bin chosen
        if next_item_size > post_residual && (mean_residual as u32) >= next_item_size {
            score += 3.0 ;
        }
    }
    if bin_residual == bin_capacity {
        // new-bin candidate: cheaper when few open bins remain tight, costlier when plenty open
        let base = if open_bins_count > 8 { 3.5 } else { 1.8 } ;
        score += base + 0.05 * (post_residual as f64) ;
        // discourage opening a new bin when next item could fill the fresh capacity well
        if next_item_size > 0 && next_item_size as f64 > 0.55 * (bin_capacity as f64) {
            score -= 2.0 ;
        }
    }
    // dead-space pressure: bins whose residual becomes small-but-unusable
    if post_residual > 0 && post_residual < 6 {
        score += 4.0 + 0.5 * (6 - post_residual) as f64 ;
    }
    if item_size >= bin_residual {
        score -= 5.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: penalize leftover space with a convex (quadratic) term so that
    // small residuals are strongly favored over medium ones.
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth cubic coupling with stream progress: early in the stream we are
    // more tolerant of medium residuals (room to consolidate later); late in
    // the stream tight fits dominate. This shifts the polynomial weighting
    // continuously rather than piecewise.
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 1.6 * post - late * 0.5 * (post * post / cap);

    // Reward tight packing relative to the fleet average residual.
    score -= 0.35 * (mean_residual - post);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * late;
    }

    // Lookahead: if the next item can exactly fill the post-residual,
    // this placement is perfect — reward it. If the next item cannot fit
    // into the post-residual, mildly penalize (dead space risk).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
        if nxt > post {
            score += 1.5 * (nxt - post) / cap;
        }
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // crowded or this bin would leave a large awkward residual.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 10.0 - 14.0 * crowd * (0.5 + late);
        // penalize opening new bin when item is small relative to capacity
        score += 4.0 * (item_size as f64 / cap);
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
