pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Dead space penalty grows super-linearly for awkward leftover classes.
    // Classes (harmonic bins): >50% (great), 25-50% (ok), 12.5-25% (poor), <12.5% (dead).
    if frac > 0.5 {
        score -= 30.0 + 20.0 * frac;
    } else if frac > 0.25 {
        score -= 10.0 + 10.0 * frac;
    } else if frac > 0.125 {
        score += 5.0;
    } else {
        // tiny leftover: strong dead-space penalty, scaled by how tiny
        score += 15.0 + 40.0 * (0.125 - frac);
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving space that exactly accommodates the next item.
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * gap;
        if gap == 0.0 {
            score -= 40.0; // perfect two-item chaining
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly more if the leftover is unusable-ish.
        let nl = next_item_size as f64;
        if post_residual as f64 > 0.5 * nl {
            score += 4.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // when open bins look bad; cost shrinks as stream progresses (committing to
    // open bins early keeps packing tight).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 - 20.0 * progress;

        // Opening a new bin is attractive if the item is large and few bins fit it.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // If the next item is small and some bin leaves room for both, discourage new bin.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score += 15.0;
        }
        return score;
    }

    // Prefer tighter bins (small residual before placement) slightly: best-fit flavor.
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Modulo-style tiebreak: leftovers that are multiples of common item sizes (10,20,25,50)
    // are more reusable; reward those classes.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 3.0; }
    if pr % 25 == 0 { score -= 2.0; }
    if pr >= 50 { score -= 2.0; }

    // Slight preference to spread across bins when many are open (balance load).
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up items are "dead space". Penalize quadratically.
    if post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 30.0;
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 4.0;
    } else if post_residual < 60 {
        score -= 15.0; // sweet zone: enough room for a mid-size follow-up
    }

    // Perfect or near-perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual < 40 {
            score -= 40.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if existing bins fit poorly.
        score += 60.0 + pressure * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin pairs well with a big next item
        }
        if post_residual == bin_capacity as f64 as u32 && open_bins_count > 0 && fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        score -= pressure * 3.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 120.0;
        } else {
            score -= 20.0;
        }
    }

    // Alignment with mean residual: bins closer to the mean residual
    // keep the bin population homogeneous and packable.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), slightly superlinear.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: reward proportional to how snugly next item fits the leftover.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize potential dead space,
            // worse when post_residual is tiny (unusable sliver).
            let deadness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 12.0 * deadness;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight fits;
    // placing here when it's a good fit should be encouraged.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 8.0 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; more when many bins are open and mean residual
        // suggests existing capacity is plentiful.
        score += 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 {
            // An empty bin always chains perfectly; dampen its lookahead advantage so it
            // doesn't beat genuine tight fits in open bins.
            score += 15.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference to fill bins with larger residuals when mean residual is high
    // (many bins are loose; consolidate).
    if mean_residual > 0.5 * bin_capacity as f64 {
        score += 0.05 * (bin_residual as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_quality = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 20.0 * fit_quality;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if bin_residual >= next_item_size {
            // Next item fits here only if we don't place current item here.
            score += 6.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins over new bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    if bin_residual < bin_capacity {
        score -= 2.0 * pressure.min(5.0);
    }

    // New-bin candidate: penalize unless existing bins would leave bad residuals.
    if bin_residual == bin_capacity {
        let mean_waste = (mean_residual - post_residual as f64).abs();
        // Open a new bin only when all open residuals are poor (large & unusable-ish)
        // or very few bins exist.
        let poor_existing = if mean_residual > 0.0 { mean_residual } else { 0.0 };
        let worth = (post_residual as f64) - poor_existing * 0.5 + pressure * 3.0;
        score = 60.0 + worth - (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // Never open a new bin when a perfect or last-chance fit exists elsewhere.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        let _ = mean_waste;
    }

    // Early stream: be slightly greedy toward filling bins fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual;

    // Base: wasted space, normalized
    let mut score = pr / cap;

    // Smooth non-linear coupling: post_residual interacts with stream progress.
    // Early on, prefer tight fits less aggressively; later, dead space matters more.
    let tightness = 1.0 - (pr / cap);
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score -= tightness * tightness * progress_weight * 0.8;

    // Polynomial penalty on very small residuals (dead space), smooth in progress
    let dead = (1.0 - pr / cap).max(0.0);
