        }
    }

    // Mild pressure to consolidate into fewer bins as stream advances
    score += (open_bins_count as f64) * 0.01 * (1.0 - progress);

    // Small reward for large items consuming big chunks of residual
    score -= (item / cap) * (item / cap) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
