        3 => 2.0,            // awkward 3/8 zone
        4 => -2.0,           // ~1/2 left, very reusable
        5 => 1.5,            // awkward 5/8 zone
        6 => -1.5,           // ~3/4 left
        _ => 0.5,            // mostly empty bin, mild penalty
