    // common item sizes (items are multiples of 10 in the classic setting).
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 2.0; // residue is exactly reusable by a standard item
    }
    if pr_u % 5 == 0 && pr_u % 10 != 0 {
        score += 0.5; // half-class: partially reusable
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr_u {
            score -= 8.0; // perfect chained fit
        } else if next_item_size < pr_u {
            let chain_waste = pr_u - next_item_size;
            // Harmonic check: does the chain leave a good class residue?
            if chain_waste % 10 == 0 {
                score -= 3.0;
            } else if chain_waste <= 10 {
                score -= 1.0;
            } else {
                score += (chain_waste as f64) * 0.05;
            }
        } else {
            // next item cannot use this residue at all
            score += pr as f64 * 0.02;
        }
    }

    // Integer division thresholds on item_size: big items want tight bins.
    if item_size >= 50 {
        score -= 1.0; // prefer placing large items (fewer alternatives)
    } else if item_size <= 20 {
        score += 0.5; // small items are flexible; don't burn tight bins
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Penalize the fresh bin mildly, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 + 2.0 * (1.0 - progress);
        // But if open bins are all badly fragmented, opening fresh is fine.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 4.0;
        }
    }

    // Prefer consolidating into bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 2.0;

    // Mild preference for keeping the number of open bins from exploding.
    score += (open_bins_count as f64) * 0.02;

    score
}

