        let dead = post_residual as f64 - next_item_size as f64;
        if dead > 0.0 && post_residual < next_item_size + 10 {
            score += 0.6 * dead; // leftover just under next item size is wasted
        }
        // Reward leftovers that can still accommodate the next item (chain potential).
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Relative-to-mean adjustment: bins with residual near the mean are "normal" targets;
    // penalize bins that are anomalously full (small residual) to keep balance.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Tight fit reward: small post_residual is generally good (classic best-fit).
    score -= 0.05 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is attractive early in the stream
    // (many future items to fill it) or when the fit here is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Base competitiveness of a fresh bin.
        score -= 12.0 * (1.0 - progress);
        // Prefer a new bin when this placement leaves awkward leftover space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
        // Late in the stream, consolidation into open bins is better.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64;
        }
        if post_residual > 0 && post_residual < next_item_size.min(21) {
