        }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
        let dead = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual };
        if dead as f64 > mean_residual * 0.6 {
            score += 0.35 * (dead as f64 - mean_residual * 0.6);
