    }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        if next_item_size > 0 && post_residual == 0 {
            score -= 20.0;
        }
    } else {
        if next_item_size > 0 && post_residual == 0 {
