        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual;
            if dead > 12 {
                score += 0.5 * (dead - 12) as f64;
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack as f64 > mean_residual * 0.5 {
                score -= 1.0;
            }
        }
    }
    if item_size >= bin_residual {
        score -= 5.0;
    }
    if fitting_bins_count > 3 && bin_residual == bin_capacity {
        score += 1.0;
    }
    if post_residual == 0 {
        score -= 3.0;
    }
    let frag = (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);
    score += 0.5 * frag;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as f64) < (next_item_size as f64)
        } else {
            post_residual < 10
        };
