            score += 18.0;
        }
    }

    // Lookahead synergy: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual cannot hold next item: mild penalty.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64);
    score += 0.15 * gap;

    // Time horizon: early in the stream, be pickier about wasting space;
    // later, favor consolidation into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - tight);

    // Bin-count pressure: many open bins -> discourage new bins implicitly
    // by boosting preference for existing bins; few bins -> allow opening.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If open bins are mostly full (small mean residual), opening is fine.
        score -= 0.5 * mean_residual;
        // Late in stream, opening a fresh bin is cheaper than fragmenting.
        score -= 15.0 * progress;
        // If many bins fit, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
        // Big items fit perfectly in fresh bin; slight reward.
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward matching against mean residual (balance the pool).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // --- Lookahead chain-fit logic (refined granularity) ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact pairing is gold.
            score -= 55.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tight chain fit reward, decaying with slack.
            score -= 11.0 + 0.22 * slack;
            if slack < 4.0 {
                score -= 7.0;
            } else if slack < 8.0 {
                score -= 2.0 + 0.15 * (8.0 - slack);
            }
        } else {
            let stranded = (next_item_size - post_residual) as f64;
            // Small unusable leftovers are worse than larger ones when the
            // next item nearly fits: penalize sharply for near-misses.
            if post_residual > 0 && stranded < 21.0 {
                score += 15.0 + 0.32 * (21.0 - stranded);
            }
            if next_item_size > post_residual + 4 {
                score += 0.42 * stranded;
            }
            score += 0.10 * stranded;
        }
    }

    // Perfect closure of the current bin is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Relative-to-mean-residual coupling: drain fat bins, spare lean bins.
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: open a fresh bin only when open bins are crowded
    // (mean residual too small for typical items) or the fit leaves a
    // large unusable gap; otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < 20.0;
        let bad_fit = post_residual as f64 > 60.0;
        if bad_fit || crowded {
            score -= 30.0;
        } else {
            score += 2.5 + 0.05 * post_residual as f64;
        }
    }

    // Exact-fill temptation: if the item exactly consumes this bin, boost it.
    if item_size >= bin_residual {
        score -= 5.0;
    }

    // Late-stream tightening: waste becomes costlier as we progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize post_residual, non-linearly (dead space grows quadratically in cost)
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth coupling: tight fits (small post_residual) are extra valuable late in the stream
    score -= 25.0 * (1.0 - pr_norm).powi(2) * (0.5 + 0.5 * progress);

    // Reward bins whose residual after placement matches the next item (lookahead chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (pr - next_norm * cap).abs();
        score -= 18.0 * (1.0 - diff / cap) * (0.4 + 0.6 * progress);
    } else if next_item_size > post_residual {
        // penalize leaving a residual too small for the lookahead item
        score += 12.0 * pr_norm * (1.0 - pr_norm) * (0.3 + 0.7 * progress);
    }

    // Scarcity pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mean residual coupling: prefer bins near the mean (balance), smooth interaction
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight preference for consolidating into fewer bins early; new-bin cost rises with progress
    score += (open_bins_count as f64) * (1.0 + 2.0 * progress) * 0.5;

    // Exact fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by
    // capacity fractions (dead-space classes).
    let post_frac = post_residual as f64 / cap;
    // class 0: tiny leftover (<10) -> excellent fit, reward strongly
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 25 {
        score -= 8.0;
    } else if post_residual > 60 {
        // large leftover is actually reusable, mild reward
        score -= 4.0;
    } else {
        // mid-range dead zone (25..60) is the worst: hard to fill later
        score += 6.0;
    }

    // Modulo arithmetic on post_residual: leftover in "harmonic" residue
    // classes that pair well with small items (typical sizes 10..80).
    let r = post_residual % 20;
    if r == 0 {
        score -= 5.0; // leftover is a multiple of 20: clean packing
    } else if r <= 10 {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Lookahead coupling: does next_item_size fit exactly into leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect continuation
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; leftover becomes a waiting class
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 10.0;

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave bad mid-range dead space and the item is large.
    if bin_residual == bin_capacity {
        let bad_open = fitting_bins_count == 0
            || (post_residual >= 25 && post_residual <= 60 && fill < 0.6);
        if bad_open {
            score -= 20.0;
        } else {
            score += 15.0; // discourage opening bins when fits are decent
        }
    }

    // Mild pressure against bin sprawl late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

