        } else if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit: small residual becomes dead space
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: neutral baseline, only chosen when open bins look bad.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
