        if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ;
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64 ;
        }
        // second-order lookahead: reward residuals that can also host the item AFTER next
        if post_residual >= next_item_size {
            let rem = post_residual - next_item_size ;
            if rem == 0 {
                score -= 3.0 ;
            } else if rem < 12 {
                score -= 0.35 * (12 - rem) as f64 ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // new-bin bias: stronger when few bins fit the item, weaker when many do
        let crowding = if fitting_bins_count > 1 { 1.0 } else { 0.0 } ;
        score += 2.5 + 0.05 * (post_residual as f64) + 1.5 * crowding - 0.02 * (post_residual as f64) * crowding ;
    }
    // scarcity pressure: when item fits in many bins, prefer tighter fits less aggressively
    if fitting_bins_count > 3 && post_residual > 0 {
        score -= 0.6 ;
    }
    if item_size >= bin_residual {
        score -= 5.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: residual waste grows super-linearly,
    // and the penalty intensifies as the stream progresses.
    score += 40.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);

    // Tight fit reward: strong smooth bonus when post residual is small.
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, penalize opening new bins.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress) * (1.0 - progress) + 6.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Dead-space penalty: residuals too small for the smallest plausible item,
    // penalized smoothly via a saturating quadratic.
    let dead = (pr - 1.0).max(0.0) / cap;
    if pr < 10.0 {
        score += 15.0 * (10.0 - pr) as f64 / 10.0 * (1.0 - dead);
    }

    // Mild dispersion pressure: prefer bins near the mean residual to balance load.
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * progress;

    // New-bin candidate: slightly discourage opening a new bin when good fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "dead-space classes"
    let r = post_residual % 10;
    let residue_penalty = match r {
        0 => -6.0,                     // perfectly reusable class
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        3 | 7 => 0.5,
        4 | 6 => -0.5,
        _ => 3.0,                      // residue 5: worst leftover class
    };
    score += residue_penalty;

    // Integer-division thresholds: small post_residual is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Fraction-of-capacity coupling: post_residual in mid-range is valuable
    let frac = post_residual as f64 / cap;
    if frac >= 0.2 && frac <= 0.6 {
        score -= 8.0 * frac;
    }

    // Lookahead: does next item fit into the post-residual harmonic class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or leaves a good residue class
            let nxt = (post_residual - next_item_size) % 10;
            if nxt == 0 { score -= 12.0; } else if nxt == 5 { score += 4.0; }
            score -= 5.0;
        } else {
            score += 6.0; // next item won't fit here; slightly deprioritize
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * progress - 0.4 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0;
        }
    }

    // Slight preference for tightest existing bins via mean residual deviation
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "dead space" as leftover that is smaller than the smallest plausible item (<=10)
    // or too small for the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover can't fit the next item: dead space for lookahead horizon
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leftover accommodates the lookahead item: reward
        score -= 8.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Open bins pressure: discourage proliferating bins when many are open
    // but encourage using existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight; prefer filling tight bins first.
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Penalize the empty bin mildly, but less if many bins
    // are open and residuals are large (fragmentation risk).
    if bin_residual == bin_capacity {
        let base = 20.0;
        let frag_risk = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).powi(2) * 30.0
        } else {
            0.0
        };
        score += base + frag_risk;
        // late in the stream, prefer consolidating into open bins even more
        score += 10.0 * progress;
    }

    score
}

