pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            // Perfect chain: item + next item exactly fills this bin.
            score -= 40.0;
        } else if post >= nxt {
            // Next item still fits; reward tightness of the chain.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin; penalize by the gap size.
            score += (nxt - post).min(60.0);
        }
        // Bonus if after both placements the bin would be nearly full.
        let two_step_residual = post - nxt;
        if two_step_residual >= 0.0 && two_step_residual <= 5.0 {
            score -= 15.0;
        }
    }

    // Penalize large unusable dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current
    // placement would leave large dead space and few bins fit the item.
    if bin_residual == bin_capacity {
        let mut new_bin_score = post_residual as f64;
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            new_bin_score -= 20.0;
        }
        // Opening a new bin is only attractive when many bins fit (no scarcity)
        // and this bin would be left with wasteful residual.
        if fitting_bins_count > 2 && post_residual > 40 {
            new_bin_score -= 10.0;
        } else {
            new_bin_score += 25.0;
        }
        score = score.max(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins that leave little space after placement (tight fit).
    let mut score = post_residual as f64;

    // Normalized fit quality: how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            // Chain bonus scaled by how perfectly the next item fills the leftover.
            let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * chain_tightness;
        } else {
            // Dead space penalty: leftover is too small for the known next item.
            let waste = (post_residual as f64) / (next_item_size as f64);
            if post_residual > 0 {
                score += 6.0 * (1.0 - waste.min(1.0));
            }
        }
    }

    // Last-chance bins: if this is the only open bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving residuals in a "dead zone" (too small for typical items 1..100
    // to be useful, i.e., very small leftovers) — encourages full packing instead.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // consolidate into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;
    score += 5.0 * consolidation * (1.0 - progress);

    // Late in the stream, be more aggressive about closing bins tightly.
    score -= 6.0 * progress * (1.0 - fill_ratio.min(1.0));

    // New-bin candidate: make the empty bin expensive unless the item is huge
    // relative to the capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 1.5;
        // A new bin is attractive if the item is very large (rare good fits)
        // or this is early with few bins open.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late stream: slightly discourage proliferation of bins.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress)
        - 2.0 * progress * (pr * fit_ratio);

    // Reward tight fits via smooth quadratic decay of the item's share.
    let fill = item_size as f64 / cap;
    score -= 4.0 * fill * (1.0 - fill) * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item (smooth hinge via square).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.15 * gap * gap / cap;
        // Reward leaving room for the next item smoothly.
        let room = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 3.0 * room * (1.0 - room) * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when few bins fit.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 6.0 * scarcity * (1.0 + progress);
    }

    // Mild coupling to mean residual: prefer bins deviating below mean early, above mean late.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * (progress - 0.5);

    // Discourage opening new bins when many open bins exist, smoothly.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fits are perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Small dead space classes (mod arithmetic on residual capacity).
    let m = post_residual % 10;
    // Residuals that are multiples of 10 are more reusable for typical sizes.
    if m == 0 {
        score -= 8.0;
    } else if m <= 3 {
        score += 5.0; // awkward slivers
    }

    // Penalize residuals below the minimum item size (dead space).
    if post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // exact chain fit
            if post_residual - next_item_size < 10 || post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fit is poor.
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual - item_size) as f64;
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score = tight_fit + 25.0 - 20.0 * pressure;
        // Early in stream, opening new bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins below mean residual (keep residuals balanced-ish).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Slight preference for fuller bins.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // tiny gaps heavily penalized
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (good fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // with few bins, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open
        score += 15.0 + pressure * 12.0;
        // If no existing bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Early stream: opening bins is cheap
        score -= (1.0 - progress) * 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0 - slack * 2.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space for the known next item
        score += 15.0;
    }

    // Slight preference for bins below mean residual (consolidate fullness)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: opening a new bin should only win when it
    // genuinely promises a good future chain; otherwise bias toward existing bins.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If the next item would fit perfectly in the fresh bin after this one,
        // opening is attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 14.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Two-step lookahead: perfect chaining reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact match: this bin's leftover is consumed exactly by next item.
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Next item fits with slack remaining; reward mildly, scaled by closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the leftover; penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer tighter bins relative to the fleet mean residual.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Mild penalty for very small leftovers that are hard to use later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let small = 30u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
