    }

    // Perfect-fit harmonic classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0;
    } else if frac >= 0.2 && frac <= 0.5 {
        score -= 2.0;
    }

    // Strong lookahead coupling (merged with best-heuristic near-miss terms)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 2.0;
            }
        }
        // tight near-miss bonuses
        if post_residual >= next_item_size && post_residual - next_item_size < 4 {
            score -= 7.0;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 {
            score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64;
        }
        // unusable sliver for the next item
        if post_residual > 0 && post_residual < next_item_size.min(21) {
            score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
        }
        // graded penalty when next item does not fit at all
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64;
            if next_item_size > post_residual + 4 {
                score += 0.42 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mostly discourage, but cheaper when open bins are crowded
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mean residual coupling
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Current item tightness bonus
    if item_size >= bin_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: small penalty proportional to wasted potential.
            let wasted = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.15 * wasted;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item fits poorly
    // everywhere (post_residual here would be large relative to alternatives).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening fresh bins is cheaper (more future structure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If mean residual is high, open bins are fragmented; a new bin is less harmful.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    } else {
        // Reward using already-open bins, more so when many bins are open.
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // Penalize leaving residuals that no plausible item (>=1) can use well:
    // tiny residuals are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for bins whose residual is above average (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 40.0 * coupling;

    // Penalize dead space more as stream progresses (wasted capacity matters later)
    score += 10.0 * norm_pr * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits: subtract when post_residual is small
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * t);
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / cap) * (0.4 + 0.6 * t);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize leaving residual that strands it
        score += 8.0 * (pr / cap) * (1.0 - t);
    }

    // Slight preference for consolidating into fewer bins early
    score += 0.5 * open_bins_count as f64 * t;

    // Keep new-bin candidate slightly penalized unless residuals elsewhere are large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - t) - 3.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible into
    // common item-size classes are more reusable.
    let pr = post_residual as u32;
    let class_penalty = match pr % 10 {
        0 => -18.0,          // perfectly reusable residual (multiple of 10)
        5 => -10.0,          // half-class, still quite reusable
        2 | 4 | 6 | 8 => -4.0, // even residuals moderately reusable
        1 | 3 | 7 | 9 => 6.0,  // odd residuals tend to become dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: small post-residuals are dead space.
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 3.0;
    }

    // Next-item fit coupling: reward residuals that exactly or nearly fit the lookahead item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 22.0; // perfect lookahead fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // item won't fit after placement: penalize proportional to overshoot class
            let over = (next_item_size - pr) as f64;
            score += 5.0 + over * 0.15;
        }
    }

    // Capacity fraction coupling: bins whose residual is a "clean" fraction of capacity are favored.
    let frac = pr as f64 / cap;
    if (frac * 4.0).round() / 4.0 == frac {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score -= (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    // Late in the stream, consolidate: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that can never fit a future item are waste.
    // Threshold: smallest possible item is 1, but practically gaps < ~10 are near-dead.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: fully packed bin
    } else if post_residual <= 20 {
        score += 12.0; // risky small gap
    }

    // Reward gaps that can still fit the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // Penalize gaps that cannot fit the next item (likely dead until end).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += 0.35 * open_bins_count as f64;

    // Relative residual alignment: prefer bins tighter than the mean (good fits).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fits are poor (large post_residual everywhere).
    if bin_residual == bin_capacity {
        score += 55.0; // base cost of opening a new bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress; // late in stream, consolidation matters more
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Mild preference for filling larger items into fuller bins early.
    score += 0.05 * item_size as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is better.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if (post - next).abs() < 0.5 {
            // Perfect match: next item exactly fills the remaining space.
            score -= 25.0;
        } else if next <= post {
            // Next item fits here: reward proportional to how well it uses post_residual.
            score -= 12.0 * (next / post);
        } else {
            // Next item won't fit in post_residual: penalize dead space,
            // especially when post_residual is small and unusable.
            let waste = post / bin_capacity as f64;
            score += 8.0 * waste;
            if post < 10.0 {
                score += 5.0; // tiny dead space, nearly unusable
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" bins;
    // prefer filling them now (their leftover is least useful).
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 3.0 * (mean_residual - post_f) / bin_capacity as f64;
    } else {
        score += 2.0 * (post_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless item is huge / nothing fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if the item is large relative to capacity
        // or stream is early (plenty of future items to fill the fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 10.0 * item_frac - 8.0 * (1.0 - progress);
        // If next item also large, a fresh bin is more promising.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill:
    // dead space is bad if post_residual is smaller than the smallest item (1)
    // but awkward relative to the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead can fit here: bonus for chaining two items in one bin.
            score -= 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Lookahead cannot use the leftover: penalize proportional to waste.
            score += 0.35 * (post_residual as f64) - 0.15 * (next_item_size as f64);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // When many bins are open with slack, prefer consolidation into existing bins;
    // when few bins are open, allow new bins more freely.
    let open_pressure = (open_bins_count as f64) / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by how much
        // slack already exists across open bins.
        score += 25.0 + open_pressure * 3.0 + mean_residual * 0.25;
    } else {
        // Existing bin: reward grows with global slack pressure (consolidate).
        score -= open_pressure * 1.5;
    }

    // Dynamic time horizon: early in the stream, be more open to new bins
    // (structure the packing); late in the stream, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * tightness;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    // Mild penalty when post_residual lands in a "dead zone" (too small for
    // typical mid-size items but wasteful), i.e. 1..=10 leftover.
    if post_residual >= 1 && post_residual <= 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let small = 30u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
