        }
        // unusable sliver for the next item
        if post_residual > 0 && post_residual < next_item_size.min(21) {
            score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
        }
        // graded penalty when next item does not fit at all
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64;
            if next_item_size > post_residual + 4 {
                score += 0.42 * (next_item_size - post_residual) as f64;
            }
        }
        // two-step anticipation: reward residuals that can host next item plus a chunk
        if post_residual >= next_item_size && next_item_size > 0 {
            let room = post_residual - next_item_size;
            if room >= 10 {
                score -= 1.5;
            }
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: discourage, but cheaper when open bins are crowded
    if bin_residual == bin_capacity {
