    score -= progress * 2.0;

    // Mean residual coupling
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Current item tightness bonus
    if item_size >= bin_residual {
        score -= 5.0;
    }

    // Crowding-aware tie-break: prefer keeping few open bins tight
    if open_bins_count > 8 && post_residual > bin_capacity / 2 {
        score -= 1.0;
    }

    score
}

