pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Two-step lookahead with graded bands (borrowed strength from best-so-far).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Exact chain fit is gold.
            score -= 55.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 4 {
                score -= 7.0;
            } else if slack < 8 {
                score -= 2.0 + 0.15 * (8.0 - slack);
            } else if slack < 16 {
                score -= 0.06 * (16.0 - slack);
            } else {
                // Too much leftover for the next item: penalize the excess.
                score += 0.02 * (slack - 16.0);
            }
            // General tightness reward.
            score -= 11.0 + 0.22 * slack;
        } else {
            // Next item cannot follow: penalize stranded slack proportionally.
            let stranded = nxt - post_residual as f64;
            if post_residual > 0 && post_residual < 21 {
                score += 15.0 + 0.32 * (21.0 - post_residual as f64);
            }
            if next_item_size > post_residual + 4 {
                score += 0.42 * stranded;
            }
            score += 0.10 * stranded;
        }
    }

    // Perfect closure of the current bin is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Drain fat bins relative to the mean.
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: discourage proliferation unless crowded or
    // the fit is bad, but give a small graded nudge toward tiny residuals.
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * post_residual as f64;
        if post_residual < 10 {
            score += 6.0 - 0.5 * post_residual as f64;
        }
        let bad_fit = post_residual as f64 > 60.0;
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < 20.0;
        if bad_fit || crowded {
            score -= 30.0;
        } else {
            score += 25.0;
        }
        if fitting_bins_count <= 1 && post_residual > 40 {
            score -= 3.0;
        }
    }

    // Exact-fit bonus for the current placement.
    if item_size == bin_residual {
        score -= 5.0;
    }

    // Late-stream tightening: waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_residual as f64 * progress;

    score
}

