pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: wasted space, weighted more heavily late in the stream.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: reward tight fits via a smooth polynomial in fit_ratio.
    let tight = fit_ratio * fit_ratio * (3.0 - 2.0 * fit_ratio.min(1.0)); // smoothstep-like
    score -= 12.0 * tight * (0.5 + progress);

    // Penalize large dead space with a quadratic term scaled by mean residual.
    let dead = (pr / cap).powi(2);
    score += 20.0 * dead * (1.0 + (mean_residual / cap).powi(2));

    // Lookahead: bonus if next item fits the post residual (smooth polynomial in slack).
    if next_item_size > 0 {
        let slack = pr - next_item_size as f64;
        if slack >= 0.0 {
            let x = (next_item_size as f64 / cap).min(1.0);
            score -= 8.0 * (1.0 - (1.0 - x) * (1.0 - x)) * (slack / cap + 0.5);
        } else {
            score += 4.0 * (-slack / cap).powi(2);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty for proliferating open bins when residuals are already small.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) as i32 as f64;
        score = 30.0 - 25.0 * poor_fit - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "residue band" does it fall into?
    // Residuals that are multiples of small divisors are more reusable.
    let pr = post_residual;
    let reusable = ((pr % 10 == 0) as i32) * 2 + ((pr % 5 == 0) as i32) + ((pr % 20 == 0) as i32) + ((pr % 25 == 0) as i32);
    score -= 3.0 * reusable as f64;

    // Integer-division thresholds: penalize tiny dead space that nothing can use
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space zone
    } else if pr >= 10 && pr < 20 {
        score += 6.0;
    } else if pr == 0 {
        score -= 30.0; // perfect fill
    }

    // Coupling with next item: harmonic match between post_residual and next_item_size
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // exact chain
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.3; // next item still fits
            // modulo harmony: next item divides into residual cleanly
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.5; // next item won't fit here
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tight fits: ratio of item to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Progress-aware new-bin handling: opening a fresh bin (residual == capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // early stream: favor filling existing bins; late stream: new bins ok
        score += 10.0 * (1.0 - progress) + 4.0;
        if post_residual > 50 {
            score += 5.0; // wasteful fresh bin with big leftover
        }
    }

    // Spread from mean residual: bins far below mean are precious, keep them
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Congestion: many open bins -> consolidate
    if open_bins_count > 5 {
        score -= 1.0;
    }

    score
