pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead gap: penalize proportionally to how much of the gap is unusable.
        let unusable = (next_item_size - post_residual) as f64;
        score += 2.0 * unusable + 10.0;
    } else if next_item_size > 0 {
        // Gap that still fits the next item: reward proportionally to snugness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 0.5 * slack;
    }

    // Reward tight fits (small post_residual relative to capacity).
