    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it enables a good future pairing
    // with the next item, or when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin gives perfect 100 residual; reward if mean residual is low
            // (existing bins are nearly full) or next item is large.
            if mean_residual < item_size as f64 * 0.5 || next_item_size > 50 {
                score -= 5.0;
            } else {
                score += 25.0; // prefer filling existing bins
            }
        } else {
            score += 25.0;
        }
        let _ = fragmentation;
    }

    // Slight progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

