            score -= 60.0; // perfect chaining: next item closes this bin
        } else if post_residual >= next_item_size {
            // leftover after hypothetical next placement
            let two_step_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            if two_step_left < 10 {
