    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // neutral-ish baseline; early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 60.0 * progress;
        if open_bins_count == 0 {
            score = 0.0;
        }
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    // Slight preference to fill fuller bins (smaller residual) among open bins
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    // Discard spreading across many bins when residuals are large
    if open_bins_count > 4 && post_residual as f64 > mean_residual * 1.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
