    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near multiples of common
    // item sizes (10..80 grid) are more likely to be filled later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonically useful": divisible-ish by small sizes.
    let mut harmonic_bonus = 0.0;
    for s in [10u32, 20, 25, 40, 50].iter() {
        let m = post_residual % s;
        if m == 0 && post_residual > 0 {
            harmonic_bonus += 6.0;
        } else if (*m as f64) < 3.0 {
            harmonic_bonus += 2.0;
        }
    }
    score -= harmonic_bonus;

    // Penalize tiny dead space (unusable waste) more than proportional residual.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0; // near-perfect fit is excellent: but low score wanted -> actually reward
    }
    // Fix: perfect fit should be strongly favored.
    if post_residual < 10 && post_residual > 0 {
        score -= 60.0;
    } else if post_residual == 0 {
        score -= 200.0;
    }

    // Fraction-of-capacity classes: residual in [0,0.1C] great, in (0.4C,0.6C) awkward mid-zone.
    let frac = pr / cap;
    if frac > 0.4 && frac < 0.6 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / cap);
            // harmonic class of the slack after the lookahead item
            if slack % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty if this bin was the only option
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score += 25.0 - 60.0 * crowding;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= 0.3 * (cap - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize leaving gaps that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        score = 40.0 + avg_waste * 0.5 - poor_fit * 0.2;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with a super-linear penalty
    // so that small leftover slivers (dead space) are strongly discouraged.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powf(2.0) * bin_capacity as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == 0 {
            // Perfect fit now: strong reward.
            score -= 60.0;
        } else if (post_residual as u32) == next_item_size {
            // Next item exactly fills this bin: extremely strong reward.
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: reward proportional to how tightly
            // the pair packs (smaller leftover after the pair is better).
            let pair_left = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - pair_left / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize, scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.25 * miss;
        }
        // Bonus if the next item could fit nowhere else but here after placement
        // (last-chance protection for the lookahead item).
        if post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // --- Last-chance bin bonus: if this is the ONLY bin that fits the item,
    // strongly prefer using it over opening a new bin. ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when existing fits are terrible:
        // make it attractive only for very tight current fits.
        if post_residual > 0 {
            // Neutral baseline for a fresh bin.
            score = pr + 5.0;
            // If the next item also fits well in the fresh bin, slight edge.
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 6.0;
            }
        } else {
            // Exact fit into a "new" bin means item == capacity; fine.
            score -= 60.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual is below the
    // mean (i.e., relatively full bins), keeping emptier bins flexible. ---
    score += 0.6 * (mean_residual - pr);

    // --- Stream-phase adaptation: early on, be more conservative (keep bins
    // open and flexible); late in the stream, pack aggressively. ---
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= phase * 12.0 * (1.0 - pr / bin_capacity as f64);

    // --- Congestion: when many bins are open, prefer consolidation into
    // already-partially-filled bins rather than spreading out. ---
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio;

    // Penalize post-residual dead space that is too small to ever be useful
    // (smaller than the smallest plausible item) but not zero.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: strongly favor bins whose post-residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
            // Extra reward for exact-ish chaining fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack * 0.15);
        } else {
            // Next item won't fit here: penalize proportional to how badly.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.20 * gap;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins => we can afford to be choosy; amplify fit preference.
    if fitting_bins_count > 1 {
        score += 6.0 * fit_ratio;
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into bins below mean (fill laggards).
    if open_bins_count > 0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
        // Encourage closing out bins when bin count is high.
        if open_bins_count > 8 {
            score -= 0.10 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: early in stream, be conservative (favor tight fits);
    // late in stream, allow opening new bins more freely since waste matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: only open a new bin when the current item
    // is large relative to residuals or late in the stream with poor fits.
    if bin_residual == bin_capacity {
        // Base threshold: opening a new bin costs roughly one bin of waste.
        let mut open_cost = 55.0;
        // Open more eagerly early (build capacity for future items).
        open_cost -= 20.0 * (1.0 - progress);
        // Open eagerly if item is big.
        open_cost -= 0.15 * item_size as f64;
        // Discourage opening when many bins could fit (we're being picky).
        open_cost += 8.0 * (fitting_bins_count as f64).min(5.0);
        // If next item is huge and nothing fits it later, a fresh bin is good.
        if next_item_size > 60 {
            open_cost -= 15.0;
        }
        score = open_cost;
    } else {
        // Late stream: slightly relax fit pressure to avoid excess opens.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.4 * progress * (1.0 - progress));

    // Penalize large dead space non-linearly (quartic growth in normalized residual)
    score += 12.0 * norm_pr * norm_pr * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize if post_residual can't fit next item when one exists
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // reward leaving room for the next item, scaled by how well it fills leftover
            let fill = nxt / pr.max(1.0);
            score -= 5.0 * fill * (1.0 - progress);
        } else {
            score += 3.0 + 4.0 * progress;
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: keep it competitive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) - 2.0 * progress * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how "usable" is the leftover space?
    // Residuals divisible by common item-size classes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 {
        harmony_bonus -= 60.0; // perfect fit
    } else {
        if pr % 10 == 0 { harmony_bonus -= 12.0; }
        if pr % 20 == 0 { harmony_bonus -= 6.0; }
        if pr % 25 == 0 { harmony_bonus -= 5.0; }
        if pr % 50 == 0 { harmony_bonus -= 8.0; }
        // Dead space penalty: tiny residuals that nothing can use
        if pr < 10 {
            harmony_bonus += 25.0 * (10 - pr) as f64;
        }
        // Integer-division threshold: residual classes by fifths of capacity
        let fifth = bin_capacity / 5;
        let class = pr / fifth;
        harmony_bonus -= match class {
            0 => 4.0,  // nearly full bin, good
            1 => 2.0,
            2 => 0.0,
            3 => -2.0, // half-empty: less attractive than fuller bins
            _ => -4.0,
        };
    }

    // Next-item coupling: does the leftover harmonize with the lookahead item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            // Reward exact modular alignment with next item
            if (pr % next_item_size.max(1)) == 0 {
                harmony_bonus -= 10.0;
            }
            harmony_bonus -= 0.15 * slack;
        } else {
            // Leftover cannot host next item; penalize proportionally
            harmony_bonus += 0.1 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        harmony_bonus -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        // Base cost of opening a bin; softened when many bins are open and mean residual is high
        score += 55.0 - 0.3 * pressure.min(20.0) - 0.1 * mean_residual;
        let _ = poor_fit;
    }

    // Slight progression scaling: early on, prefer tighter packing discipline
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (1.0 - progress) * (post_residual as f64);

    score += harmony_bonus;
    score
}

