pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize leaving a gap that no future item (sizes >= 1) would fill efficiently:
    // gaps below the minimum item size are pure waste.
    if post_residual < 1 {
        score += 10.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's leftover; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean residual coupling: placing into a bin with residual far above the mean
    // (a loose bin) is preferred to consolidate tightness.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate handling: only attractive when current fit is poor
    // (large dead space) or no good options exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // More attractive when many items remain (amortize the bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // Less attractive if open bins are few (prefer filling existing ones).
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
