    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if gap <= 1.0 {
            score -= 40.0; // perfect 2-step chain
        } else if pr >= nxt {
            score -= 25.0 * (1.0 - gap / nxt.max(1.0));
        } else {
            // leftover space that next item cannot use: penalize proportionally
            score += 0.6 * (nxt - pr);
        }
    }

    // Tightness reward: prefer bins that will be nearly full after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize dead space relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no open bin is a good fit (post_residual would be large).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 100.0 + waste - 30.0 * fill_ratio;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also host next item
        }
    }

    // Mild late-stream conservatism: keep bins tight as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

