    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= open_bins_count as f64 * 0.5 * fill_frac;

    // Time-horizon modulation: early in the stream, be more open to new bins
    // (exploration); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as progress advances and when
        // decent fitting bins exist.
        score += 35.0 * (0.3 + 0.7 * progress);
        if fitting_bins_count > 0 {
