    score *= tightness;

    // Smooth interaction: post_residual vs mean residual deviation
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // Reward filling bins nearly full (small post_residual), smoothly
