        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            let over = (nxt - pr) / cap;
            score += 15.0 * over * over;
        }
    }

    // Mild penalty for spreading across many open bins when slack is large
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: prefer it only when it yields better long-term packing
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 10.0 * norm_pr * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions create "usable" classes.
    // Residuals that are multiples of common small sizes (or near capacity fractions)
    // are more likely to be filled by future items, so reward them.
    let cap = bin_capacity as f64;

    // Reward post_residuals that align with harmonic classes (multiples of 5, 10, 25, 50)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
    } else {
        // Perfect fit is ideal
        score -= 20.0;
    }

    // Penalize very small dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic class of the slack after the next item
            if slack % 10 == 0 { score -= 8.0; }
            else if slack % 5 == 0 { score -= 4.0; }
            score += slack * 0.15;
        } else {
            // next item won't fit here: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // attractive only when no open bin offers a good (low-waste) fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap - (cap - post_residual as f64) * 0.0 + 30.0 + 10.0 * progress;
        // If many bins are open already, discourage proliferation
        score += open_bins_count as f64 * 1.5;
        // If the next item is large, a fresh bin may be valuable
        if next_item_size >= 50 { score -= 12.0; }
    } else {
        // Tightness reward: bins that end up near-full are good
        let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
        score -= fill_ratio * 8.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Integer-division threshold on post_residual: quarter classes
    let quarter = post_residual / 25;
    match quarter {
        0 => score += 5.0,          // 0..24: mostly dead space unless 0
        1 => score += 1.0,          // 25..49
        2 => score -= 1.0,          // 50..74
        _ => score -= 2.0,          // 75..100: roomy bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Two-step lookahead with fine-grained chain-fit rewards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 11.0 + 0.22 * slack;
            if slack < 4.0 { score -= 7.0; }
            else if slack < 8.0 { score -= 2.0 + 0.15 * (8.0 - slack); }
            else if slack < 16.0 { score -= 0.06 * (16.0 - slack); }
            else { score += 0.02 * (slack - 16.0); }
        } else {
            let stranded = (next_item_size - post_residual) as f64;
            // Penalize stranding, but only mildly for tiny stranded slivers.
            if post_residual > 0 && post_residual < next_item_size.min(21) {
                score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
            }
            score += 0.10 * stranded;
            if stranded > 4.0 { score += 0.32 * stranded; }
        }
    }

    // Perfect closure is gold.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Drain fat bins: prefer consuming above-average residual.
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 60.0;
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < 20.0;
        if bad_fit || crowded {
            score -= 30.0;
        } else {
            score += 2.5 + 0.05 * post_residual as f64;
            if post_residual < 10 {
                score += 6.0 - 0.5 * post_residual as f64;
            }
        }
        if fitting_bins_count <= 1 && post_residual > 40 {
            score -= 3.0;
        }
    }

    // Exact-fit bonus for the current item.
    if item_size == bin_residual {
        score -= 25.0;
    } else if item_size >= bin_residual {
        score -= 5.0;
    }

    // Late-stream tightening: waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fits are extremely desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose leftover can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Open-bin pressure: with many bins open, prefer consolidation
    // (favor bins with low residual, i.e., tight packing).
    let obp = open_bins_count as f64;
    score += obp * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it's genuinely needed
    // (i.e., current bin would leave a tiny dead gap and many bins are open).
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual < 10 && open_bins_count > 2 {
            score -= 55.0;
        }
    }

    // Mild stream-position scaling of dead-space penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let small = 28u32;
    let mid = 50u32;
    let large = 72u32;

    // Dead space penalty: residual too small to hold any likely future item
    if post_residual < small {
