            score -= 2.5 + 0.18 * (8 - (post_residual - next_item_size)) as f64;
        }
        // unusable sliver for the next item
        if post_residual > 0 && post_residual < next_item_size.min(21) {
            score += 16.0 + 0.34 * (next_item_size.min(21) - post_residual) as f64;
        }
        // two-step lookahead: bin that fits current AND next tightly is gold
        if next_item_size == post_residual && item_size == bin_residual - post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: mostly discourage, but cheaper when open bins are crowded
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.5;
        }
        if post_residual < 12 {
            score += 6.0 - 0.5 * post_residual as f64;
        }
        if fitting_bins_count <= 1 && post_residual > 40 {
            score -= 3.5;
        }
    }

    // Stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.5;

