    score += (mean_residual - bin_residual as f64) * 0.12;

    // Current item tightness bonus
    if item_size >= bin_residual {
        score -= 5.5;
    }
    // exact-fill bonus
    if item_size == bin_residual {
        score -= 10.0;
    }

    score
