    // Reward tight fits relative to mean residual of open bins.
    let mr = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let tightness = (bin_residual as f64 - item_size as f64) / mr;
    score -= 15.0 * tightness.clamp(-2.0, 2.0);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when it beats a poor fit,
    // i.e., when current bin would leave large dead space or lookahead mismatch.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild penalty for very small unusable residuals (fragmentation).
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize large dead space (wasted capacity) after placement
    if post_residual < item_size.min(next_item_size.max(1)) {
        // residual too small for likely future items -> good tight fit
        score -= 15.0;
    }

    // Dead-space penalty: residual that nothing (min size 1..) can use is worst
    let tiny = post_residual < 10;
    if tiny {
        score -= 8.0; // near-perfect fill
    } else {
        // quadratic waste penalty grows with leftover
