    // Lookahead: reward bins whose post-residual still fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.05 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys the ability to serve the next item
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Discourage opening new bins when many bins are open and could absorb the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins and progress
        score += 25.0 + 3.0 * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // if the item fits well nowhere else, opening is less penalized
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild time-horizon shaping: early on, be conservative with tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
