    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize leftover space, with a non-linear (quadratic) dead-space cost
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: early on, waste is cheaper; later, waste is costly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
