        score += 12.0 * (0.5 + progress) * norm_next * cap / 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins vs consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual smooth interaction: prefer bins near the mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: neutral-ish baseline, penalized when a decent fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // item sizes are "usable" classes; large odd residues are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows super-linearly for unusable residuals.
    if post_residual > 0 {
        // smallest plausible item is 1; residual 0 is perfect, small residual is bad
        score += 40.0 / (pr + 1.0); // tight fit reward
    } else {
        score -= 30.0; // exact fill bonus
    }

    // Modulo-classes: residual divisible by common small sizes is reusable.
    let reusable = if post_residual == 0 {
        true
    } else {
        (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0)
    };
    if reusable {
        score -= 12.0;
    } else if post_residual < 10 && post_residual > 0 {
