    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack < 15 {
            score -= 18.0;
        } else {
            score -= 6.0 * (1.0 - slack as f64 / cap);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; penalize wasting a big residual
        score += 8.0 * (pr / cap);
    }

    // Integer-division thresholds on residual fraction of capacity.
    let frac = pr / cap;
    let class = (frac * 4.0).floor() as i32; // quarters of capacity
    score += match class {
        0 => -5.0,  // <25% residual: nearly full bin, good
        1 => 0.0,   // 25-50%
        2 => -2.0,  // 50-75%: roomy but usable
        _ => 3.0,   // >75%: mostly empty bin being used for small item
    };

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged early,
    // allowed late in stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_frag = mean_residual / cap;
        score = cap * 0.55 + 20.0 * (1.0 - progress) - 15.0 * avg_frag;
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 0.8;

    // Small deterministic tie-breaker from item class parity.
    score += ((item_size % 7) as f64) * 0.05;

    score
}

