    // Tight fit reward relative to residual before placement
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean residual are already roomy,
    // prefer filling them rather than bins with little space
    score -= 0.08 * (mean_residual - post_residual as f64);

    // New empty bin candidate: baseline that is only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing else fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // slight penalty if chain continues anyway
        }
    }

    score
}

