pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // next item cannot fit here; slight penalty for wasting a big residual now
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with how many bins are already open.
        score = bin_capacity as f64 + 10.0 + 0.5 * open_bins_count as f64;
        // If the item is large relative to capacity, opening fresh is more acceptable.
        score -= 0.15 * item_size as f64;
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If mean residual across open bins is large, opening new is wasteful.
        score += 0.3 * mean_residual;
    }

    // Mild preference for bins with below-average residual (concentrate fragmentation).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: quadratic penalty on wasted space, smoothed non-linearly.
    let mut score = post * post / cap;

    // Tight-fit reward: strongly reward very small post residuals.
    let tightness = (-post / (cap * 0.25)).exp();
    score -= 30.0 * tightness;

    // Non-linear coupling of waste with stream progress:
    // early on, waste is cheap (bins plentiful); late, waste is costly.
    let waste_weight = 1.0 + 3.0 * progress * progress;
    score += waste_weight * post / cap;

    // Interaction: post_residual vs next item size — reward residual that
    // still accommodates the lookahead item (smooth sigmoid-like gate).
    if nxt > 0.0 {
        let fits_next = 1.0 / (1.0 + (nxt - post).max(0.0) / cap * 4.0);
        score -= 8.0 * fits_next * (1.0 - progress * 0.5);
        // Penalize residual slightly smaller than next item (near-miss dead space).
        let near_miss = (-((post - nxt).abs() / 10.0).powi(2)).exp();
        score += 6.0 * near_miss;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize fragmentation relative to mean residual of open bins.
    score += 2.0 * (post - mean_residual).abs() / cap;

    // New-bin candidate: empty bin gets a baseline cost that grows with
    // progress (avoid spawning bins late) but shrinks if the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0 + 20.0 * progress - 0.2 * item;
        // Opening a bin is fine early when open bins are few.
        score -= 10.0 / (1.0 + open_bins_count as f64);
    } else {
        // Reward using existing bins more when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mild preference for larger items filling bins deeper.
    score -= item / cap * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // modulo classes (dead space) are penalized; classes matching the
    // lookahead item are rewarded.
    let pr = post_residual;
    let pr_class = pr % 10;
    let pr_quot = pr / 10;

    // Dead-space penalty: tiny leftovers (< next plausible small item) are waste.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Reward when post_residual exactly matches a harmonic fraction of capacity
    // (50, 25, 20, 10) — these are reusable "harmonic" slots.
    let harmonic: [u32; 5] = [50, 25, 20, 10, 5];
    for h in harmonic.iter() {
        if pr == *h {
            score -= 6.0;
        }
    }

    // Modulo coupling: if post_residual class aligns with next item's class,
    // the next item can likely fill this bin exactly later.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni == pr {
            score -= 20.0; // perfect future fill
        } else if pr >= ni && (pr - ni) % 10 == 0 {
            score -= 8.0; // next item leaves a harmonic remainder
        } else if pr >= ni && (pr - ni) < 10 {
            score += 4.0; // next item would create tiny dead space
        }
        // Integer-division threshold: bins whose quotient class matches the
        // next item's quotient class are compatible.
        if pr_quot == (ni / 10) && pr >= ni {
            score -= 3.0;
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 5.0;
    }

    // Penalize spreading when few bins fit (scarcity): keep this bin if it's
    // the last chance, otherwise push toward fuller bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: only open a new bin when current item is
    // large relative to residuals and mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / cap;
        if item_size as f64 > bin_residual as f64 * 0.8 && tight < 0.15 {
            score -= 9.0 + 4.0 * progress;
        } else {
            score += 10.0; // prefer existing bins by default
        }
    }

    // Mild preference for bins below mean residual (fill the emptier ones
    // less, keep balanced bins): use mean_residual as a soft anchor.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small tie-break on capacity fraction class of the item itself.
    score += (item_size % 10) as f64 * 0.01;

    score
}

