pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny residuals are pure waste; penalize super-linearly.
    if post_residual < 10 {
        score += (11 - post_residual as i32).pow(2) as f64 * 4.0;
    }

    // Awkward gap band.
    if post_residual >= 10 && post_residual <= 25 {
        score += 6.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit: dominant bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage spreading as more bins accumulate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Homogeneity: prefer residuals near the mean.
    score -= 1.5 * (bin_residual as f64 - mean_residual).abs().min(30.0);

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Near-exact lookahead fit: strong bonus.
            if gap < 4 {
                score -= 37.0;
            } else if gap < 8 {
                score -= 12.0 + 0.15 * (8 - gap) as f64;
            } else if gap < 16 {
                score -= 0.06 * (16 - gap) as f64;
            } else {
                score += 0.02 * (gap - 16) as f64;
            }
        } else {
            // Next item does NOT fit: dead space penalty grows with waste.
            let dead = next_item_size - post_residual;
            if post_residual < next_item_size.min(21) {
                score += 15.0 + 0.32 * (next_item_size.min(21) - post_residual) as f64;
            }
            if dead > 12 {
                score += 0.5 * (dead - 12) as f64;
            }
            let waste_ratio = dead as f64 / next_item_size as f64;
            score += 1.5 * waste_ratio + 1.2 * waste_ratio * waste_ratio;
        }
        // Large dead gap relative to mean residual.
        let dead_gap = if post_residual >= next_item_size {
            post_residual - next_item_size
        } else {
            next_item_size - post_residual
        };
        if dead_gap as f64 > mean_residual * 0.6 {
            score += 0.35 * (dead_gap as f64 - mean_residual * 0.6);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mut nb = 55.0 + open_bins_count as f64 * 1.5;
        if progress < 0.2 {
            nb -= 20.0;
        }
        if next_item_size >= 60 {
            nb -= 15.0;
        }
        if fitting_bins_count > 2 {
            nb += 30.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Borrowed from best: fresh bin is valuable when mean residual is low
        // (open bins are nearly full) and stream is not at the end.
        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 {
            nb -= 40.0;
        }
        // Fresh bin with a large post-residual pool for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 2.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            nb -= 10.0;
        }
        // Large items prefer fresh bins.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            nb -= 8.0;
        }
        // Many fitting bins: opening a new one is wasteful.
        if fitting_bins_count >= 3 {
            nb += 6.0;
        }
        score = score.max(nb);
    } else {
        // Nearly-full open bins: slight reward for squeezing them shut.
        if bin_residual < bin_capacity / 8 {
            score -= 3.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual;
            if dead > 12 {
                score += 0.5 * (dead - 12) as f64;
            }
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.10 * (next_item_size - post_residual) as f64 ;
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.2 * waste_ratio ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
        }
    }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        if fitting_bins_count <= 1 && post_residual > 40 { score -= 3.0 ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if next_item_size > 0 && post_residual >= next_item_size && progress > 0.85 { score -= 4.0 ; }
