    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Coupling with next item: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 4.0 * (post_residual as f64 / cap);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bin: avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: make it attractive only if no open bin fits well
    if bin_residual == bin_capacity {
        // prefer new bin when mean residual of open bins is small relative to item
        score = 60.0 + mean_residual * 0.5 - (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 50.0;
