pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 80.0;
    } else if post_residual <= 20 {
        // Medium-small gaps become dead space only if no future item can use them;
        // weight by how "odd" the gap is relative to typical item granularity.
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that cannot host the lookahead item: mild penalty scaled by gap size.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // over opening new ones; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * 8.0 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure.
        score += 30.0 + pressure;
        // A new bin is attractive if current bins have large scattered residuals
        // (fragmentation) — mean_residual high implies poor fits available.
        score += 0.15 * mean_residual;
    } else {
        // Existing bins get a mild discount that grows with pressure to consolidate.
        score -= pressure * 0.5;
        // Prefer bins whose residual is closest to the item (tight packing signal).
        score += 0.3 * (bin_residual - item_size) as f64;
    }

    // Slight bias toward filling bins with lower-than-mean residual (most-full bins).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
