        // next item won't fit here: penalize proportionally to wasted lookahead potential
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Compare post_residual against mean residual: penalize leaving more than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, especially early/mid stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress);
        // but if no open bin fits, new bin is necessary: soften
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight reward for consolidating when many bins are open
    score -= (open_bins_count as f64) * 0.2;

    score
}

