        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.35 * next_item_size as f64 * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large item, few fitting options) or the stream is early and future items
    // are likely to fill a fresh bin.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
