pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    // Residuals that are small (<10) are dead space; residuals in
    // "harmonic" classes (multiples of 10 or 5) are reusable.
    let cls = post_residual % 10;
    if post_residual > 0 {
        if cls == 0 {
            score -= 6.0; // perfectly harmonic residual
        } else if cls <= 2 || cls >= 8 {
            score += 4.0; // near-dead fringe classes
        } else {
            score += 1.5;
        }
    }

    // Dead space penalty: residual too small for minimum item size (1..100
    // unknown distribution, assume small items possible but penalize tiny gaps)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact-ish fit for next item is gold
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0;
            } else if slack < 10 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 5.0; // this bin becomes useless for the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 5.0 * (open_bins_count as f64).sqrt().min(4.0);

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but relax pressure as stream progresses (waste less late).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let bad_fit_penalty = (post_residual as f64).max(0.0) * 0.05;
        score = score.max(0.0) + 8.0 - 6.0 * progress + bad_fit_penalty;
    }

    // Tie-break with mean residual alignment
    score += 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
