pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead space" — penalize them quadratically.
    let min_item = 1u32;
    if post_residual < 10 {
        // Unusable sliver: heavy penalty growing as gap shrinks.
        score += 60.0 * (1.0 + (10.0 - post_residual as f64)) ;
    } else if post_residual < min_item as f64 as u32 + 5 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 40.0;
        } else {
            score -= 10.0 / (1.0 + gap);
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use this gap: mild penalty for stranding space.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // disfavor opening new bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).sqrt().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; reward if residual mean is high
        // (existing bins are fragmented).
        score = 30.0 + 10.0 * pressure.min(8.0);
        if mean_residual < 15.0 {
            score -= 20.0; // existing bins nearly full, new bin fine
        }
        if post_residual == bin_capacity {
            score += 0.0;
        }
    } else {
        score += pressure * 0.5;
        // Prefer bins below mean residual (less-full bins absorb the item,
        // preserving tighter bins for future small items).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

