        score += 0.5 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.25 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Encourage tight fits generally: reward small post_residual relative to capacity.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mildly discourage opening a new bin when the stream is early,
    // more so when few bins are open (amortize bins), unless it's a tight-fit situation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if next item exactly fills a fresh bin after this one, allow opening.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

