        }
    } else {
        // last item: purely minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strong reward to use it, avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // global residuals are fragmented or fit is perfect
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_is_huge = (item_size as f64) > 0.8 * bin_capacity as f64;
        let fragmentation = mean_residual / (open_bins_count.max(1) as f64);
        // Prefer new bin when item is huge, or open bins are too full to be useful,
        // or early in the stream with many bins already open
