    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: squared post-residual (waste grows quadratically), modulated by progress
    let mut score = pr * (1.0 + progress) + norm_pr * norm_pr * cap * (0.5 + progress);

    // Smooth coupling: prefer leaving residuals close to mean (harmonization)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.8;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (1.0 + progress);

    // Lookahead: if next item fits in post_residual, big reward (smooth decay)
    if next_item_size > 0 {
        let fits_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        let ratio = (next_item_size as f64 / (post_residual as f64 + 1.0)).min(1.0);
