        // Penalize residuals that are too small for the next item (dead space)
        score += (1.0 - fits_next) * norm_pr * cap * 0.3;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a bin, more when good alternatives exist
    if bin_residual == bin_capacity {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 20.0 * openness + 5.0 * alt.min(5.0);
        // Late in stream, opening fresh bins is less harmful (better long-term packing)
        score -= 12.0 * progress;
        // If the item is large, a fresh bin is actually attractive
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

