pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward residuals that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly unusable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual > 80 {
        score += 8.0; // large residual is fine, but mild penalty vs. perfect
