    // late in the stream, prioritize perfect packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio;

    // Many open bins with high mean residual: encourage filling existing bins.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // fit here is poor. Penalize the empty-bin candidate (residual == capacity)
    // unless the current fit is bad.
    if bin_residual == bin_capacity {
        if fit_ratio > 0.5 && fitting_bins_count > 0 {
            score += 40.0; // keep item in an existing reasonably-filled bin
        } else if fit_ratio < 0.3 {
            score -= 15.0; // poor fit everywhere: fresh bin is attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
