        if pr >= next_item_size {
            // this bin can chain to next item: reward, scaled by tightness
            let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
            score -= 10.0 * tight;
            // extra reward if next item exactly divides the leftover class
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += 4.0 + 0.1 * (next_item_size - pr) as f64;
        }
    } else {
        // last item: prefer fullest packing
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the item is large (harmonic class of item_size)
