    } else if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Progress-based mild adaptation: late in the stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

