pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post-residual amplifies dead-space penalty.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (post_residual as f64).powf(1.5) * 0.5;

    // Reward bins whose residual closely matches the item (best-fit sharpening).
    score -= 40.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty unless post_residual is tiny anyway.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer consuming as much residual as possible.
        score -= 50.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Time horizon: early in the stream, be more conservative (penalize leaving
    // medium residuals); late in the stream, pack greedily anywhere it fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor filling them.
    if open_bins_count > 0 {
        let residual_pressure = mean_residual / bin_capacity as f64;
        score -= 10.0 * residual_pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how bad existing fits would be.
        let waste_if_new = (bin_capacity - item_size) as f64;
        score += 30.0 + waste_if_new * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Penalize creating residuals that are awkwardly small but non-zero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

