    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more,
    // large dead space penalized more.
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += norm_pr * norm_pr * (1.0 - progress) * cap * 0.3;
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * prog_term * 8.0;

