                score -= 5.0 + 0.25 * (dead - 16) as f64 ;
            }
        }
        if next_item_size > 0 && post_residual == next_item_size { score -= 10.0 ; }
        if progress > 0.8 && post_residual < item_size { score += 2.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
        // NEW: penalize near-full open bins slightly harder when item is small (save them for big items)
        if item_size < bin_capacity / 4 && bin_residual < bin_capacity / 10 {
            score += 4.0 ;
        }
    }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: penalize large post_residual more as stream progresses
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits, amplified late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize wasting residual that could fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 4.0 * (ni / bin_capacity as f64);
        } else {
            score += 3.0 * ((ni - pr) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild preference for filling existing bins over opening new ones when residuals are similar
    if bin_residual < bin_capacity {
        score -= 1.5 * (mean_residual / bin_capacity as f64 - norm_pr).abs();
    } else {
        // New-bin candidate: slight penalty, reduced late in the stream
        score += 2.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // harmonics (e.g. 10, 20, 25, 50) are more reusable by typical items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fill
    } else if pr % 50 == 0 {
        25.0
    } else if pr % 25 == 0 || pr % 20 == 0 {
        18.0
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: small unusable post-residuals (below typical
    // minimum item size) waste capacity unless the bin is exactly filled.
    let min_item = 1u32;
    if pr > 0 && pr < min_item.max(1).max(0) + 0 {
        // placeholder, replaced below
    }
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the chained residual
            let chained_bonus = if slack % 50 == 0 { 20.0 }
                else if slack % 25 == 0 || slack % 20 == 0 { 14.0 }
                else if slack % 10 == 0 { 9.0 }
                else { 0.0 };
            score -= chained_bonus;
        } else {
            // next item cannot use this bin's remainder; slight penalty
            // proportional to how much dead space remains for it
            score += 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Penalize the fresh bin mildly so
    // existing bins with decent post-residuals win, but keep it competitive
    // against bad fits (small post_residual with poor harmonic class).
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        // many open bins => discourage proliferation
        score += open_bins_count as f64 * 1.2;
    }

    // Prefer bins whose residual deviates from the mean in a "tighter"
    // direction (keeps loose bins available for large items).
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    // Integer-division threshold on item size: large items should go into
    // the tightest possible bin.
    if item_size > bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.13;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual that is too small for the smallest plausible item (<=10)
    // is pure dead space; strongly penalize.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Very tight gap: risky, only useful if next item is small enough.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 8.0; // lookahead fits exactly here: good
        } else {
            score += 15.0;
        }
    }

    // Reward near-perfect fits (post_residual small but not dead).
    if post_residual > 0 && post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post_residual,
    // this bin chains nicely; reward proportional to fit tightness.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that fits,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing bins; penalize candidates that leave large residuals
    // (fragmentation) when the fleet is large.
    let fleet_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * fleet_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual low) or this bin cannot chain with the next item.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64;
        if crowded || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 30.0; // discourage opening new bins when good fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: huge bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits after placement: partial bonus scaled by closeness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted residual unless small
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize large dead space relative to mean residual (fragmentation).
    if post_residual as f64 > mean_residual + 10.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild tie-break: prefer tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits in post_residual, bonus; else penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: when many bins are open relative to progress, discourage new bins implicitly
    // by rewarding reuse of existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 3.0 * pressure * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // New-bin candidate: make it attractive only when the item is large or fit is poor elsewhere.
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size > 60 { 10.0 } else { 0.0 };
        let poor_fit_elsewhere = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        let tight_next = if next_item_size > 0 && next_item_size >= 50 { 5.0 } else { 0.0 };
        score = score - big_item_bonus - poor_fit_elsewhere - tight_next + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more strongly as the stream advances
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: post_residual near zero
    score -= 15.0 * (1.0 - pr_norm).powi(6);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Slight preference for consolidating into fewer bins
    score += 0.4 * open_bins_count as f64;

    // Mean residual alignment: prefer bins whose residual is close to mean
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits strongly (harmonic in post_residual).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: dead space in low residue classes
    // (residual % 10 == 1..3) is nearly unusable for typical items -> penalize.
    let pr_class = post_residual % 10;
    let class_penalty: f64 = match pr_class {
        0 => -8.0,
        1 | 2 | 3 => 6.0 + (3 - pr_class) as f64 * 2.0,
        4 | 5 | 6 => 1.0,
        7 | 8 | 9 => 3.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual / item_size ratio — a bin that
    // could hold the next item too is more valuable to keep roomy.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the lookahead item -> reward.
            score -= 12.0;
            // Extra harmony: if post_residual is an exact multiple class match
            // with next item (post_residual - next small), reward more.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            }
        } else {
            // Placement kills lookahead compatibility -> mild penalty.
            score += 5.0;
            // But if post_residual lands in a "harmonic" residue (multiple of 10),
            // the dead space may still be reusable later.
            if post_residual % 25 == 0 || post_residual % 10 == 0 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is penalized when decent
    // fits exist, but attractive when this bin would leave bad residue.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score = bin_capacity as f64 * 1.2;
        // Attractive if best alternative would leave tiny unusable residue:
        // approximate via mean residual pressure.
        if mean_residual < (bin_capacity as f64) * 0.15 {
            score -= 25.0;
        }
        // Early in stream, keep fewer bins open (bins are cheap to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
        // If many bins open, prefer packing into existing ones.
        score += open_bins_count as f64 * 1.5;
    }

    // Coupling: bins whose residual is far from mean residual get a nudge —
    // prefer placing into bins that reduce residual dispersion.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Harmonic modulo coupling between item_size and capacity thirds.
    let third = bin_capacity / 3;
    if item_size % third == 0 && post_residual % third == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            score += 0.10 * dead as f64 ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.5 * waste_ratio ;
            score += 1.2 * waste_ratio * waste_ratio ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score += 0.08 * dev ;
        }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0 ; }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 2.0 ; }
        if next_item_size > 0 && post_residual == 0 { score -= 20.0 ; }
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        if fitting_bins_count <= 1 && post_residual > 40 { score -= 3.0 ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 { score -= 40.0 ; }
        if next_item_size > 0 && post_residual == next_item_size { score -= 10.0 ; }
        if progress > 0.8 && post_residual < item_size { score += 2.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
    }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot accommodate even the smallest plausible item is dead space.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 50.0;
    }

    // Penalize residuals that only fit a narrow item range (fragile gaps),
    // scaled by how close the gap is to being useless.
    let fragility = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score += 8.0 * fragility;

    // Reward filling bins tightly: favor larger item relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open bins pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild penalty for stranding space.
        score += 6.0;
    }

    // Prefer bins with residual below the mean (consolidating space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so as stream progresses,
    // unless the item is large and would leave a very fragmented residual.
    if bin_residual == bin_capacity {
        let fragmentation = post_residual as f64 / bin_capacity as f64;
        let bad_open = item_size as f64 <= 0.55 * bin_capacity as f64 && fragmentation < 0.5;
        score += 30.0 + 20.0 * progress;
        if bad_open {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

