pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step fit: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Post-residual close to next item size (tight 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + gap);
    }

    // Penalize post-residual too small for next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward residual below mean residual (tightening bins).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good fits exist, unless it's a perfect fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Early stream: be more exploratory with new bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize wasted dead space quadratically when residual becomes unusable.
    let smallest = 10.0_f64;
    if (post_residual as f64) < smallest {
        score += 40.0;
    } else if (post_residual as f64) < 2.0 * smallest {
        score += 0.5 * (2.0 * smallest - post_residual as f64);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.2 * (post_residual as f64 - next_item_size as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current open bins
    // are all quite full (low mean residual) late in the stream.
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 25.0 {
            score -= 20.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (fuller bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Time horizon: early on, keep bins flexible (favor moderate residuals);
    // late, squeeze maximally.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // base: post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // non-linear coupling of post-residual with stream progress
    let p2 = progress * progress;
    score += 20.0 * x * progress * (1.0 - progress);
    score -= 10.0 * x * p2;

    // reward tight fits (small post residual) more strongly as stream advances
    score -= (cap - pr) / cap * 15.0 * (0.3 + 0.7 * progress);

    // dead-space penalty: post residual too small to matter is fine, mid residuals bad
    let dead = (x - 0.2) * (x - 0.2);
    score += 12.0 * dead * (1.0 - progress);

    // lookahead coupling: penalize if next item fits well in the residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = (x - nx).abs();
        score += 8.0 * fit * (1.0 - progress);
        score -= 6.0 * (1.0 - fit) * progress;
    }

    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // many open bins: prefer filling existing ones over opening new
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64 * (0.2 + 0.8 * progress);
    } else {
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // mean residual coupling: prefer bins near the mean (balanced packing)
    score += 4.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: mod-10 buckets.
    let cls = post_residual % 10;
    match cls {
        0 => score -= 25.0,               // round residual, very reusable
        5 => score -= 10.0,               // half-class also reusable
        1 | 9 => score += 15.0,           // near-round dead slivers
        _ => {}
    }

    // Integer-division threshold: residual usable by common small items (<=30).
    if post_residual >= 30 {
        score -= 20.0;
    } else if post_residual < 10 {
        // dead space penalty scaled by how much of bin wasted
        score += 30.0 * (1.0 - (item_size as f64) / (bin_residual as f64).max(1.0) as f64);
    }

    // Lookahead coupling: does next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
            // exact chain fit bonus
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            if overshoot < 10.0 {
                score += 10.0; // near miss: residual likely stranded
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad,
    // but reward it when open bins are crowded (many bins, high mean residual).
    if bin_residual == bin_capacity {
        score += 55.0
            - 0.6 * open_bins_count as f64
            - 0.4 * (mean_residual - post_residual as f64).max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if item_size as f64 / bin_residual as f64 > 0.85 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage closing gaps.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space for the known next item
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing),
    // penalize outliers when mean residual is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3 * (1.0 - mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when few open bins or current fit is terrible.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 10;
        if fitting_bins_count > 0 && !poor_fit {
            score += 50.0 + open_bins_count as f64 * 2.0;
        } else {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
