    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: post_residual equals next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0; // near-match: leaves a small gap the next item almost fills
        } else if post_residual < next_item_size && next_item_size - post_residual <= 10 {
            score += 8.0; // next item just misses: dead space risk
        }

        // Penalize residual that neither fits next item nor is near-zero
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Strongly prefer tight fits (small post_residual relative to capacity)
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more when item nearly fills bin
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // Lookahead: if next item fits in post_residual, strongly reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item is large relative to post_residual
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= next_fit * 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize leaving awkward residuals
        score += 8.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted
    if post_residual < 10 {
        score -= 5.0; // near-perfect fill is excellent
    } else if post_residual < 20 {
        score += 3.0; // small awkward residual
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with below-mean residual (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in stream, be more conservative about filling bins tightly;
    // late in stream, squeeze everything to minimize final bin count
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * tightness;

    // Many open bins: encourage consolidation into existing bins rather than opening new ones
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: opening a new bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // more acceptable late in stream or when many bins open (fragmented state)
        score -= progress * 20.0;
        score -= (open_bins_count as f64) * 0.3;
        // if next item is large, a fresh bin gives room
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly
    let mut score = norm_pr.powf(1.7) * 100.0;

    // Smooth coupling: residual value decays with stream progress (dead space matters more later)
    score += norm_pr * (1.0 - progress) * 20.0 - norm_pr * progress * 30.0;

    // Polynomial interaction of post_residual with progress
    score += (norm_pr * norm_pr) * (0.5 + progress) * 40.0;

    // Perfect-fit reward (smooth via gaussian-like term)
    let fit_quality = 1.0 - (pr / cap - 0.05).powf(2.0) * 4.0;
    score -= fit_quality.max(0.0) * 15.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // Lookahead: penalize leaving residual that barely misses next item; reward residual that fits it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * (1.0 - pr / ni);
        }
    }

    // Encourage filling bins when many are open
    score += mean_residual / cap * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: penalize opening a new bin mildly, more so early on
    if bin_residual == bin_capacity {
        score += 35.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 bands create discrete
    // "waste classes". Residuals that are small AND near-multiples of 10 are
    // easier to fill with future items, so reward them (subtract).
    let class = post_residual % 10;
    if post_residual > 0 {
        match class {
            0 => score -= 12.0,             // perfectly harmonious residual
            1 | 9 => score -= 6.0,
            2 | 8 => score -= 3.0,
            5 => score -= 4.0,              // half-class: fillable with size-5 items
            _ => score += (class as f64) * 0.4, // odd/awkward waste penalized
        }
    }

    // Integer-division thresholds on post_residual: dead-space tiers.
    let pr = post_residual;
    if pr == 0 {
        score -= 20.0; // perfect fit
    } else if pr < 10 {
        score += 15.0; // unusable sliver: dead space below min item size
    } else if pr <= 20 {
        score -= 5.0; // sweet spot: likely fillable by small items
    } else if pr > 60 {
        score -= 3.0; // roomy bin still flexible
    }

    // Capacity-fraction coupling: how much of the bin the item consumes.
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 {
        score -= 10.0; // big item into this bin is very desirable
    } else if fill_frac < 0.25 && pr > 50 {
        score += 6.0; // tiny item wasting a large residual
    }

    // Lookahead harmony: does next_item_size land in the same harmonic class
    // as the post_residual (i.e., next item fits the leftover exactly/nicely)?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chain fit
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            let gap_class = gap % 10;
            if gap_class == 0 {
                score -= 10.0;
            } else if gap < 10 {
                score += 8.0; // leaves another sliver
            } else {
                score -= (gap as f64).ln() * 1.5;
            }
        } else {
            // next item cannot fit here; slight penalty for blocking the chain
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual is a hopeless sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if pr < 10 && pr > 0 {
            score += 10.0; // but avoid creating dead space anyway
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer a new bin when the item is large and stream is early, or when all
    // existing fits are poor (large awkward post_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bias = 8.0 + 25.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        score += new_bin_bias; // default: make fresh bin less attractive...
        if item_size >= 60 || (next_item_size > 0 && next_item_size >= item_size && mean_residual < 15.0) {
            score -= 30.0; // ...unless opening fresh is clearly better
        }
    }

    // Mild tie-break: prefer bins whose residual deviates favorably from mean.
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
