    // bins that still hold usable space; if large, tolerate loose placements.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // creates severe dead space or the lookahead item fits better here.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the next item could pair with the residual, opening may be good.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 35.0;
        }
    } else {
