        if post_residual == next_item_size {
            score -= 50.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item fits here after current placement: mild reward scaled by closeness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: penalize dead space
            score += 10.0 + 0.3 * diff;
        }
