    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin unless the current bin would leave large waste
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good fit exists
        let waste = post_residual as f64;
        score += 40.0 - 0.2 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Small waste is best: quadratic penalty on small leftover
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

