    // Pressure from number of open bins: consolidate when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual below the mean (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Late in the stream, be slightly more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 30.0 * (1.0 - progress); // new bins are cheaper early, expensive late
        }
    }

    // New-bin candidate baseline: only attractive if it enables a large future packing.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

