    // 2-step lookahead: reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * diff; // penalize mismatch
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 6.0; // next item still fits here
        } else {
            score += 8.0; // next item would need another bin
        }
        // second-order: next item should leave a small usable remainder too
        if post_residual >= next_item_size {
            let second_residual = post_residual - next_item_size;
            if second_residual > 0 && second_residual < 10 {
                score += 4.0; // tiny dead space after two placements
