    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating large unusable gaps relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Late in stream: prefer tight packing of open bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Discourage opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
