pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 3.0;
        }
    } else {
        // Last item in stream: just minimize residual.
        score += 0.0;
    }

    // Compare against mean residual: prefer bins that reduce dispersion of residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be more willing to open new bins (keep flexibility);
    // later, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate score: attractive early, penalized later and when many bins fit.
        score = post_residual as f64
            - 15.0 * (1.0 - progress)
            + 10.0 * progress
            + 8.0 * (fitting_bins_count as f64)
            + 0.5 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host next item too
        }
    } else {
        // Existing bins: slight preference late in stream.
        score -= 4.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize dead space quadratically, stronger late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with cubic term
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr).abs() / cap;
