    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins; smooth in open_bins_count
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Encourage bins below mean residual (consolidation), smooth coupling
    score += 0.2 * (pr - mean_residual);

    // New-bin candidate: penalize slightly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        let badness = (pr / cap).powi(2);
        score += 5.0 - 20.0 * badness;
    }

    score
}

