pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Harmonic-class penalty: quantize post_residual into capacity-fraction classes.
        // Residuals that cannot fit the smallest plausible item (<= ~10) are dead space.
        let cap_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * cap_frac * cap_frac; // quadratic dead-space penalty

        // Dead-space class: residual too small for typical items (harmonic class 0)
        if post_residual < 10 {
            score += 60.0;
        }

        // Modulo arithmetic on post_residual: residuals that are "harmonically compatible"
        // with common item sizes (multiples of 10, 20, 25, 50) are more reusable.
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 15.0;
        }
        if pr % 25 == 0 || pr % 50 == 0 {
            score -= 10.0;
        }
        // Prime-ish / awkward residuals are less reusable
        if pr % 10 != 0 && pr % 5 != 0 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or well,
    // this bin is a great choice (chains items together).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chain
        } else if next_item_size <= post_residual {
            let nxt_gap = post_residual - next_item_size;
            score -= 40.0 * (1.0 - nxt_gap as f64 / bin_capacity as f64);
            if nxt_gap < 10 {
                score -= 20.0; // near-perfect chain
            }
        } else {
            // next item won't fit here: mild penalty proportional to wasted lookahead
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual <= 10 {
            score -= 25.0; // perfect-ish fit AND last chance
        }
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize the empty bin by its wasted capacity unless
    // the current item is large relative to capacity.
    if bin_residual == bin_capacity {
        // waste = capacity - item_size
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 30.0;
        // Large items (harmonic class: > 50% of capacity) justify a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
        // Many open bins: opening another is costly
        score += 3.0 * open_bins_count as f64;
    }

    // Mild global pressure: when mean residual across open bins is high,
    // encourage filling bins rather than spreading.
    if bin_residual != bin_capacity {
        score -= 0.1 * mean_residual;
    }

    // Slight preference for bins whose residual is close to the item (best-fit core)
    score += 0.2 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
