}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..100 unknown distribution; use
    // conservative threshold ~10) are pure waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 50.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Penalize small post_residual in (0, item-size range) that can't
    // plausibly fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // bin remains useful for lookahead item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize opening new ones).
    let new_bin_call = bin_residual == bin_capacity;
    if new_bin_call {
        score += 12.0 + open_bins_count as f64 * 3.0;
        // If no other bin fits well, allow new bin: soften when this is
        // the only candidate context is handled by fitting count.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Favor bins with lower residual generally (best-fit bias),
        // scaled by how many bins compete.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Stream progression: early on, be more willing to open bins; later,
    // tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if new_bin_call {
        score += progress * 20.0;
    }

    // Mean residual coupling: if mean residual is high, prefer filling
    // existing bins harder.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if the next item can fill the post residual
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            // Perfect chain: next item exactly fills this bin
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let fill_ratio = nx / pr;
            score -= 30.0 * fill_ratio;
            // penalize leaving awkward remainder after the chain
            let after = pr - nx;
            score += 0.25 * after;
        } else {
            // next item can't use this bin's remainder; penalize proportionally
            score += 0.35 * (nx - pr).min(nx);
        }
    } else {
        // Last item: prefer minimizing final residual
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative residual context: prefer bins whose residual deviates favorably from mean
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it enables a tight chain with next item
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && (next_item_size as f64 / bin_capacity as f64) > 0.55 {
            -15.0
        } else {
            0.0
        };
        score += 18.0 + chain_bonus + 2.0 * open_bins_count as f64;
    }

    // Mild time pressure: later in stream, prefer consolidating into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

