    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / bin_capacity as f64;
        let open_f = open_bins_count as f64;
        let time_h = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening new bins is cheaper early and when many bins are open (spread load).
        score += 25.0 + 10.0 * (1.0 - time_h) - 0.5 * open_f.min(20.0) - 8.0 * pressure;
        // If mean residual across open bins can't fit item, opening is more attractive.
        if mean_residual < item_size as f64 {
