    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap).exp();
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // but relax the penalty late in the stream (progress-coupled).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress);
        if fitting_bins_count == 1 {
            score += 10.0; // never prefer a new bin over the only fitting bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.1 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste buckets via integer division
    let class = post_residual / 10; // 0..10 harmonic waste class
    score += (class as f64) * (class as f64) * 1.7; // superlinear penalty on large dead space

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Small unusable residues (dead space nobody can use)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo coupling: does post_residual match the next item's size class?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8; // next item still fits here
        } else {
            score += 40.0; // next item cannot use this bin
        }
        // modulo affinity: same decade class chain
        if (post_residual / 10) == (next_item_size / 10) && post_residual >= next_item_size {
            score -= 35.0;
        }
    } else {
        // last item: only exact or near-exact fills matter
        if post_residual > 0 { score += 25.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 { score -= 500.0; }
        if post_residual < 20 { score -= 80.0; } // big item into fresh bin is fine
    }

    // Prefer tight fits: relative waste fraction
    score += (post_residual as f64 / bin_capacity as f64) * 90.0;

    // Reward bins tighter than the mean residual (good packing pressure)
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Early stream: keep bins balanced; late stream: squeeze hard
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold typical
    // future items are "dead". Penalize them quadratically.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 18.0;

    // Penalize awkward mid-size gaps that likely waste space.
    let pr = post_residual as f64;
    if pr > 30.0 && pr < 60.0 {
        score += (60.0 - pr) * 0.35;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity (poor fit elsewhere) or mean residual is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0; // default penalty: prefer reusing open bins
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= (fill_ratio - 0.6) * 120.0; // big items deserve fresh bins
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // existing bins are cramped anyway
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post-residual is just barely too small for the next item.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 12.0;
    }

    score
}

