    }

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual portfolio; late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

