pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted opportunity
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is poor or few open bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1 - item/C for empty bin
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized by default, less so when fit elsewhere is bad.
        score += 25.0 - 20.0 * poor_fit - 2.0 * pressure - 5.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild preference for bins below mean residual (balance load) late in stream.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * ((bin_residual as f64 - mean_residual) * 0.05);

    // Slight bonus for using open bins when many are open (consolidation).
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + progress * norm_pr * norm_pr);

    // Reward tight fits via smooth cubic decay of normalized post-residual
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Penalize residuals that can't host the lookahead item (smooth quadratic gate)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        let gate = 1.0 / (1.0 + (-8.0 * gap).exp());
        score += 12.0 * gate * gap.abs().powi(2);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual across open bins
    score += 0.05 * (pr - mean_residual).abs();

    // Prefer consolidating into fewer bins as stream progresses
    score += 0.5 * (open_bins_count as f64).ln() * (0.5 + progress);

