pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small residuals via integer division bands
    let band = post_residual / 10; // 0..=9 harmonic classes
    score -= (9 - band as i32) as f64 * 2.0;

    // Perfect-fit couplings
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Dead-space penalty: residual too small for typical next item
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let small_threshold = 10 + (progress * 10.0) as u32;
    if post_residual > 0 && post_residual < small_threshold {
        score += 150.0;
    }

