    let fill = item_size as f64 / cap;
    if fill > 0.8 {
        score -= 100.0 * (fill - 0.8);
    }

    // Modulo arithmetic on post_residual: reward residuals in friendly classes
    let pr = post_residual as i32;
    if pr % 10 == 0 && pr > 0 {
        score -= 20.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Crowding penalty: many open bins favor consolidation
    score += open_bins_count as f64 * 0.5;

    // Mean-residual alignment: prefer bins near the mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // NEW-BIN CANDIDATE logic: empty bin gets a penalty unless no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = 40.0 + post_residual as f64 * 0.3;
        // If few fitting bins or current fits are bad, opening is attractive
        if fitting_bins_count == 0 {
            new_bin_score -= 300.0;
        } else if fitting_bins_count == 1 {
            new_bin_score -= 60.0;
        }
        // Early stream: opening bins is cheap; late stream: consolidate
        new_bin_score -= (1.0 - progress) * 30.0;
        new_bin_score += open_bins_count as f64 * 2.0;
        // Harmonic class of the fresh residual
        let nb_band = post_residual / 10;
        new_bin_score -= (9 - nb_band as i32) as f64 * 1.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_score -= 25.0;
        }
        return new_bin_score;
    }

    score
}

