    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 45.0 * (1.0 - tightness).powi(6);

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.9;
        } else {
            // Reward bins that can also host the next item.
            score -= 6.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one that wastes least relative to mean residual.
        score += 2.5 * (fitting_bins_count as f64).ln();
    }

    // Global state: many open bins with large mean residual -> prefer reusing fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.35 * residual_gap;

    // Penalize opening new bins when many bins are already open and mean residual is large.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / 8.0 + mean_residual / bin_capacity as f64;
        score += 14.0 + 10.0 * pressure + 8.0 * (1.0 - progress);
        // But if nothing else fits, opening is inevitable (fitting_bins_count==1 handled above).
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    // Mild time-horizon term: early in stream, keep residuals flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * tightness * 5.0;

    // Prefer bins whose post-residual matches common small-item sizes.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
