pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling: post_residual penalized more later in the stream
    let progress_sq = progress * progress;
    score += 12.0 * progress_sq * norm_post * norm_post;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 20.0 * progress * tightness * tightness * norm_item;

    // Lookahead coupling: favor residuals that still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_fit = norm_post - norm_next;
        score -= 8.0 * (1.0 - progress) * slack_fit * slack_fit;
    } else if next_item_size > 0 {
        // dead space that cannot host the next item
        score += 6.0 * (0.5 + 0.5 * progress) * norm_post;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_post);
    }

    // Penalize opening new bins when many bins already open and mean residual is high
    let mean_norm = mean_residual / cap;
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * mean_norm + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * mean_norm;
    }

    // Mild non-linear preference for bins whose residual is close to item size
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    // Bands: [0], (0,10), (10,25), (25,50), (50, cap/2..cap)
    let pr = post_residual;
    let band: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr <= 10 {
        -8.0 // near-perfect: leftover likely unusable anyway, fine
    } else if pr <= 25 {
        2.0
    } else if pr <= 50 {
        6.0
    } else {
        10.0
    };
    score += band;

    // Integer-division harmonic: post_residual / 10 classes create a staircase penalty
    // that prefers leftovers in small classes (10,20) which match common item sizes.
    let cls = (pr / 10) as f64;
    score += 1.5 * cls * (cls - 1.0) * 0.5;

    // Reward when post_residual is congruent to a plausible next-item complement.
    if next_item_size > 0 && next_item_size <= pr {
        // next item fits exactly into this leftover: harmonic match bonus
        let match_bonus = if pr % 10 == 0 { 12.0 } else { 6.0 };
        score -= match_bonus * (next_item_size as f64 / cap);
        if next_item_size == pr {
            score -= 20.0; // exact chained fit
        }
    } else if next_item_size > pr {
        // next item cannot use this bin's leftover; penalize dead space proportionally
        score += 0.05 * (next_item_size - pr) as f64;
    }

    // Tightness reward: filling a large fraction of the bin
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: reserve it for cases where no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0
            - 20.0 * progress
            - 0.5 * (open_bins_count as f64).ln().max(0.0);
        // If the current item is huge, a fresh bin is naturally attractive.
        new_bin_score -= 10.0 * fill;
        // If mean residual across open bins is small, open bins are crowded -> new bin ok.
        new_bin_score -= 0.3 * (cap - mean_residual).max(0.0);
        // If next item is large, a fresh bin preserves room for it.
        if next_item_size >= 50 {
            new_bin_score -= 8.0;
        }
        score += new_bin_score;
    } else {
        // Mild preference to keep bins balanced with mean residual (harmonic averaging).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Small progress-coupled tiebreaker to break exact ties deterministically.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

