pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items are heavily penalized (wasted capacity).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // post_residual in 0..10 is nearly unusable -> large penalty
        score += (dead_threshold - post_residual as f64) * 12.0;
    } else {
        // Smoothly increasing penalty as residual shrinks toward dead zone
        let closeness = (dead_threshold / post_residual as f64).powf(2.0);
        score += closeness * 8.0;
    }

    // Reward tight fits: small post_residual relative to item size
    if item_size > 0 {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 6.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly-ish,
    // strongly reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + gap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mild penalty for stranding space
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins when the
    // stream is early; encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.5;

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual and no good open bin exists. Make it moderately
    // costly so it's chosen only for poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5;
        // But if this item is huge and would leave little dead space anyway,
        // a fresh bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact chaining with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64); // good chain, less reward with slack
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / bin_capacity as f64); // next item won't fit here
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score += 50.0;
    }

    // Prefer tight fits relative to mean residual across open bins.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual).abs();
        if pr < mean_residual {
            score -= 10.0; // tighter than average is good
        }
    }

    // Penalize dead space that nothing in [1,100] usefully fills.
    if pr > 0 && pr < 5 {
        score -= 25.0; // near-perfect fill
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when existing fits are bad,
    // but with lookahead-aware escape (bad chain in current bins favors new bin).
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0; // fresh bin chains perfectly with next item
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (pr / cap);

    score
}

