    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward filling the bin nearly exactly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize large dead space, more so late in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly unusable
    }
    score += 0.15 * (post_residual as f64).sqrt() * (1.0 + progress);

    // Lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // no open bin fits well or the item is large.
    if bin_residual == bin_capacity {
        let escape_cost = 60.0
            - 0.35 * item_size as f64
            + 0.5 * open_bins_count as f64 * (1.0 - progress);
        score += escape_cost.max(5.0);
