        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 { score -= 40.0 ; }
        if progress > 0.8 && post_residual < item_size { score += 2.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
    }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit class: post_residual exactly in {0, half, quarter classes}
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // harmonic residue class: post_residual in low classes are "dead space"
        let quarter = bin_capacity / 4;
        if post_residual < quarter {
            score += 25.0; // tiny dead space, unusable for most items
        } else if post_residual < bin_capacity / 2 {
            score += 5.0;
        } else if post_residual < (3 * bin_capacity) / 4 {
            score -= 8.0;
        } else {
            score -= 12.0;
        }
        // integer-division threshold: can next item fit exactly into post_residual?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 45.0; // perfect harmonic pairing with lookahead
            } else if next_item_size < post_residual {
                let slack = post_residual - next_item_size;
                // reward only if slack falls in a "usable" harmonic class
                if slack <= quarter {
                    score -= 18.0;
                } else if slack > bin_capacity / 2 {
                    score += 10.0;
                }
                // modulo coupling: post_residual % next_item_size small => repeatable fill
                if next_item_size > 0 && post_residual % next_item_size.max(1) <= 2 {
                    score -= 10.0;
                }
            } else {
                score += 15.0; // lookahead can't follow into this bin
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into tightest
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // base new-bin score: mid-range, tuned by stream progress and open bins
        score = c * 0.5 + (open_bins_count as f64) * 3.0
            - desperation * (c * 0.75)
            - (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin reserves full capacity; good if item is large
            score -= (next_item_size as f64) * 0.3;
        }
    }

    // Mean-residual coupling: penalize deviating far from fleet mean residual
    score += (pr - mean_residual).abs() * 0.15;

    // Tight-fit bonus: small absolute waste relative to item size
    if item_size > 0 {
        score -= (item_size as f64 / c) * 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            score += 0.10 * dead as f64 ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.5 * waste_ratio ;
            score += 1.2 * waste_ratio * waste_ratio ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score += 0.08 * dev ;
        }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0 ; }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 2.0 ; }
        if next_item_size > 0 && post_residual == 0 { score -= 20.0 ; }
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        if fitting_bins_count <= 1 && post_residual > 40 { score -= 3.0 ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 { score -= 40.0 ; }
        if next_item_size > 0 && post_residual == next_item_size { score -= 10.0 ; }
        if progress > 0.8 && post_residual < item_size { score += 2.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
    }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let pre = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let horizon = (1.0 - progress).clamp(0.0, 1.0);
    let sqrt_open = open.max(0.0).sqrt();
    let open_log = (1.0 + open).ln();

    let has_next = next_item_size > 0;
    let is_new_bin = bin_residual == bin_capacity;

    let mean_res = mean_residual.clamp(0.0, cap);
    let mean_ratio = (mean_res / cap).clamp(0.0, 1.0);
    let fill_ratio = (item / cap).clamp(0.0, 1.0);

    // Prefer bins whose remaining space is below the current open-bin mean.
    let mean_gap = post - mean_res;
    if mean_gap > 0.0 {
        score += 0.10 * mean_gap;
    } else {
        score -= 0.06 * (-mean_gap);
    }

    // Open-bin pressure: with more open bins, reward tighter placements more strongly.
    let mut open_pressure = (0.08 + 0.15 * open_log) * post;
    if is_new_bin {
        if fitting_bins_count == 0 {
            open_pressure *= 0.10;
        } else {
            open_pressure *= 0.55;
        }
    }
    score += open_pressure;

    // Perfect fits are strongly favored.
    if post_residual == 0 {
        score -= cap * (2.0 + 2.5 * fill_ratio + 0.05 * sqrt_open);
    }

    // Strict dead-space avoidance for small unusable gaps.
    if has_next && post_residual > 0 {
        let destroys_next = pre >= next && post < next;
        let dead_scale = ((next * 0.45).max(cap * 0.06)).min(cap * 0.35);

        let mut dead_penalty = cap * 0.80 * (-post / dead_scale).exp();

        if post_residual >= next_item_size {
            // The gap is small but still usable by the lookahead item.
            dead_penalty *= 0.18;
        } else if destroys_next {
            // This placement turns a next-item-usable bin into a dead gap.
            let lost = ((next - post) / cap).clamp(0.0, 1.0).powf(1.20);
            dead_penalty += cap * (0.35 + 0.45 * horizon) * lost;
            dead_penalty *= 1.0 + 0.03 * sqrt_open;
            if fitting > 1.0 {
                dead_penalty *= 1.10;
            }
        } else {
            // The gap is unusable for the next item, but this bin could not fit it anyway.
            dead_penalty *= 0.55;
        }

        let slack_pressure = (1.0 - mean_ratio).clamp(0.0, 1.0);
        dead_penalty *= (0.80 + 0.35 * slack_pressure) * (0.75 + 0.45 * horizon);

        score += dead_penalty;
    }

    // Last-chance reward: using the only fitting open bin avoids a new bin,
    // unless the placement would destroy a useful lookahead slot.
    if !is_new_bin && fitting_bins_count == 1 {
        let destroys_next = has_next && pre >= next && post_residual < next_item_size;
        let mut last_chance_reward = cap * 0.12 * (1.0 + 0.05 * sqrt_open);

        if !has_next {
            last_chance_reward *= 1.60;
        } else if destroys_next {
            last_chance_reward *= 0.35;
        } else if post_residual < next_item_size {
            last_chance_reward *= 0.70;
        }

        score -= last_chance_reward;
    }

    // New-bin penalty: opening a bin is costly, especially late or when open bins still have slack.
    if is_new_bin {
        let mut new_penalty = cap * (0.20 + 0.07 * sqrt_open + 0.25 * mean_ratio);

        if fitting_bins_count == 0 {
            new_penalty *= 0.15;
        } else {
            if fitting_bins_count == 1 {
                new_penalty += cap * (0.08 + 0.02 * sqrt_open);
            }
            if !has_next {
                new_penalty += cap * 1.40;
            }
            new_penalty *= 0.85 + 0.45 * progress;
        }

        score += new_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Partial lookahead coupling: next item fits tightly (small leftover).
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 15.0;
    }
    // Penalize dead space next item cannot use.
    else if next_item_size > 0 && post_residual > next_item_size {
        score += 0.5 * ((post_residual - next_item_size) as f64);
    }

    // Reward bins tighter than the mean residual (good fits).
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        // Default penalty so open bins are preferred; rebate if fits are bad.
        score += 35.0;
        score -= 0.4 * poor_fit;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 25.0;
        }
        // Late in the stream, avoid fragmentation: discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra reward for chain fit (item + next both snug).
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Post-residual unusable by the known next item: penalize proportionally.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global residual pressure: if open bins are generally full, prefer
    // consolidating into this bin; if many bins are slack, penalize spreading.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.2 * residual_gap;

    // Time horizon: early in the stream, be conservative (favor new bins less
    // penalized later); late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // Many open bins: discourage opening yet another bin; the new-bin candidate
    // (bin_residual == bin_capacity) gets a rising penalty with open_bins_count.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if this bin is the only fitting option and the stream is early,
        // opening is acceptable — soften the penalty.
        if fitting_bins_count == 1 && progress < 0.5 {
            score -= 25.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.00;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling: reward tight fits with a non-linear term.
    let mut score = pr * (1.0 + 0.35 * progress);

    // Non-linear tightness reward (cubic in fill).
    score -= 12.0 * fill * fill * fill;

    // Penalize residuals too small for likely future items: smooth interaction
    // between post_residual and next_item_size.
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = (n - pr).max(0.0) / cap;
        score += 8.0 * gap * gap;
        // Reward exact-ish smooth match with lookahead.
        let match_term = 1.0 - (n - pr).abs() / cap;
        score -= 6.0 * match_term.max(0.0) * match_term.max(0.0);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (more crowded) with smooth coupling.
    score += 0.25 * (pr - mean_residual);

    // Early stream: slight preference to open/keep bins flexible.
    score += 5.0 * (1.0 - progress) * fit_ratio * fit_ratio;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress;
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: value residual classes (mod 10) — low-class residuals are more reusable.
    let class = post_residual % 10;
    score -= match class {
        0 => 40.0,
        1..=5 => 25.0,
        6..=9 => 0.0,
        _ => 0.0,
    };

    // Dead space: residuals that nothing typical can use are penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // next item won't fit here; slight penalty unless residual is tiny anyway
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (post_residual as f64) > mean_residual * 0.5;
        if bad_fit || fitting_bins_count == 0 {
            score -= 70.0 + 30.0 * progress;
        } else {
            score += 50.0;
        }
    }

    // Prefer filling bins that are already mostly full (tight packing).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Penalize opening many bins when mean residual is high (bins are underused).
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small to hold any plausible
    // future item are dead space. Penalize heavily with a non-linear curve.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Open-bin pressure: penalize bins when many bins are open to encourage
    // consolidation; relax pressure near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all existing bins
    // would create severe dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish baseline for a new bin, modulated by mean residual of
        // open bins: if open bins are already fragmented, a new bin is fine.
        score = 55.0 + (mean_residual / bin_capacity as f64) * 20.0 - pressure * 0.3;
        if next_item_size > 0 && next_item_size as f64 >= bin_residual as f64 * 0.95 {
            // Next item nearly fills a fresh bin: encourage opening it.
            score -= 30.0;
        }
    } else {
        // Lookahead: if the next item fits the post_residual, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Dead space for the known next item: mild penalty.
            score += 5.0;
        }
    }

    // Discourage wasting a large residual bin on a tiny item when alternatives exist.
    if bin_residual > 60 && item_size < 20 && fitting_bins_count > 1 {
        score += 15.0;
    }

    score
}

