pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> chain fill
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact lookahead match: strongly favor
        } else {
            // penalize mismatch relative to magnitude of gap
            score += diff * 0.35;
        }

        // also reward post_residual that still leaves a "usable" chunk (>= next item)
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // dead space below lookahead need
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // relative to mean residual: prefer bins below-average residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.25;

    // last-chance bin: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity as f64 - item_size as f64) - post_residual as f64;
        score += 15.0 + mean_residual * 0.15;
        // if next item can pair in the new bin, mild discount
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score -= 20.0;
        }
        let _ = tightness;
    }

    // early in stream: slightly discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
