pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't hold even the smallest plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    }

    // Lookahead: strongly favor bins where the next item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 8.0 + 0.15 * slack_after_next as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; penalize proportionally.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Perfect-fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item fits poorly everywhere else or mean residual is very low.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by global state.
        score = 55.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // Compete with the lone fitting bin only if that fit is bad.
            score -= 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins with high residual => keep using them.
        score += 0.05 * open_bins_count as f64 + 0.2 * mean_residual;
    }

    // Prefer filling bins whose residual is already small (concentration strategy).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild penalty for spreading across many bins early.
    score += 0.01 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = pr / cap;

    // Base: penalize post residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth quadratic waste term: strongly penalize mid-range unusable space.
    score += 20.0 * fit * (1.0 - fit) * (1.0 - fit);

    // Reward tight fits (low post residual) with smooth exponential bonus.
    score -= 15.0 * (-(pr / 25.0)).exp();

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap) * progress;
    }

    // Mean residual coupling: prefer bins deviating from mean early, near mean late.
    let dev = (pr - mean_residual).abs();
    score += dev * (0.3 * (1.0 - progress));

    // Slight penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            score += 0.10 * dead as f64 ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.5 * waste_ratio ;
            score += 1.2 * waste_ratio * waste_ratio ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score += 0.08 * dev ;
        }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0 ; }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 2.0 ; }
        if next_item_size > 0 && post_residual == 0 { score -= 20.0 ; }
        if next_item_size > 0 && post_residual == next_item_size { score -= 10.0 ; }
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        if fitting_bins_count <= 1 && post_residual > 40 { score -= 3.0 ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 { score -= 40.0 ; }
        if progress > 0.8 && post_residual < item_size { score += 2.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
    }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    if item_size >= bin_residual { score -= 5.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "usable" modulo classes (multiples of small denominators) are favored,
    // since future items of size 10..80 (or 1..100) can pack into them.
    let pr = post_residual as u32;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit: best possible outcome
    } else if pr % 10 == 0 {
        -12.0 // round-class leftover: highly reusable
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        4.0 // odd leftover: likely dead space
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: tiny leftovers are wasted space.
    if pr > 0 && pr < 10 {
        score += 15.0;
    } else if pr < 20 {
        score += 6.0;
    } else if pr > 50 {
        score -= 4.0; // large residual keeps bin flexible
    }

    // Coupling with lookahead: reward a residual that exactly hosts the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr >= next_item_size {
            score -= 3.0;
        } else {
            // leftover too small for the next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a genuinely bad fit (large, awkward leftover).
    if bin_residual == bin_capacity {
        // fresh bin baseline: moderate score, beaten by good fits
        score = 0.35 * cap + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin suits a growing stream
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Tightness reward: the fuller the bin relative to capacity, the better.
    score -= (item_size as f64 / cap) * 8.0;

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    // Stream progression: early on, keep bins flexible; later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but realistically small gaps < ~10) are
    // dead space. Penalize hard when post_residual is small and nonzero.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * pr; // small gaps: severe penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is always best
    }

    // Reward leaving a gap that exactly (or nearly) fits the lookahead item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0;
        } else if gap > 0 && gap < 10 {
            score += 25.0; // would leave another dead gap
        } else if gap >= 10 {
            score -= (gap.min(50) as f64) * 0.3;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // when few bins are open, tolerate opening new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a mild default preference
    // only when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 2.0;
        if post_residual < 10 {
            score -= 45.0; // fresh bin avoids the dead gap entirely
        }
    }

    // Mild tightness reward: bins whose residual was already tight pack well.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Stream progression: later in the stream, be more conservative about
    // opening bins (residuals matter more).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 3.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Mean residual coupling: if open bins are on average loose, prefer
    // filling them rather than this bin creating fragmentation.
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: exact match between post_residual and next item is ideal
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain: fill bin exactly next round
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // penalize near-misses less than far misses; dead space below next item is wasted
            score += gap * 0.6;
            if post_residual < next_item_size && post_residual > 0 {
                // residual too small for the next item: it becomes dead space
                score += post_residual as f64 * 0.5;
            }
        }
    } else {
        // Last item: just prefer tightest fit
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual of open bins:
    // leaving residual well below mean means this bin becomes an outlier of waste
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large dead space everywhere) or few bins open
    if bin_residual == bin_capacity {
        let poor_alternatives = mean_residual < item_size as f64 * 0.5;
        if poor_alternatives || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 20.0 + 5.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Mild penalty for wasting large residuals early in the stream
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    // Prefer filling bins that are already mostly full (tight packing)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 8.0;

    score
}

