        score = 30.0 + waste * 0.4 - t * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: opening is necessary
        }
        if next_item_size > 0 && waste >= next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Late-stream: tighten packing, avoid leaving many small bins.
    if t > 0.7 && bin_residual < bin_capacity {
        score -= 10.0 * t;
    }

    score
