pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual (0..1)
    let x = progress;
    // smooth polynomial interaction: penalize large residuals more as stream advances
    score += (prn * prn) * (0.5 + 2.0 * x * x) * 20.0;
    // cubic term: mid-stream, mildly discourage near-full bins (waste) but reward tight fits
    score -= prn * prn * prn * 15.0 * (1.0 - x);

    // Lookahead: reward residual that can fit next item, scaled by progress
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 + 20.0 * (1.0 - x);
        } else {
            score += (nxt - pr) * (0.3 + 0.7 * x);
        }
    }

    // Last chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far from mean residual (fragmentation pressure), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Mild reward for using existing bins vs opening new ones
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Residuals that are "compatible" with common item sizes (multiples of 10)
    // are more likely to be filled by future items -> reward them.
    let pr = post_residual as i64;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,                       // perfectly aligned residual
        1 | 9 => score -= 2.0,                    // near-aligned
        5 => score -= 4.0,                        // half-class, pairs with ~50 items
        _ => score += 6.0,                        // awkward classes create dead space
    }

    // Integer-division thresholds: residual in [10, 30] can still accept a
    // typical small item; residual in (30, 100) is wasteful slack.
    let half_class = pr / 10;
    if half_class >= 1 && half_class <= 3 {
        score -= 5.0;
    } else if half_class > 5 {
        score += 8.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual exactly
    // or nearly (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 30.0;
        } else if gap <= 5 {
            score -= 15.0;
        } else if next_item_size as i64 > pr {
            // next item won't fit here at all; residual is stranded relative to lookahead
            score += 3.0;
        }
    } else {
        // Last item: only the exact fill matters.
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity unless
    // few bins fit the item (last-chance) or the stream is young.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 45.0;
        if fitting_bins_count <= 1 {
            penalty -= 55.0; // forced new bin, accept it
        }
        if fitting_bins_count == 2 {
            penalty -= 20.0;
        }
        // Early in the stream, keeping bins homogeneous can pay off.
        penalty -= progress * 10.0;
        // If mean residual of open bins is low, open bins are nearly full anyway.
        penalty += mean_residual / cap * 15.0;
        // Many open bins: avoid sprawl.
        penalty += open_bins_count as f64 * 0.5;
        score += penalty;
    } else {
        // Reusing an open bin is generally good; slight bonus scaled by fill ratio.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= fill * 10.0;
        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

