    // ---- Harmonic class of post_residual (mod 10 buckets) ----
    // Classes near 0 are either perfect fits (great) or tiny dead space (bad).
    let class = post_residual % 10;
    if post_residual == 0 {
        // Perfect fit: huge reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Tiny dead space: nearly wasted residue, penalize hard unless
        // the lookahead item can still use it.
        score += 60.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0;
        }
    } else {
        // Harmonic preference: residues divisible by 5 or 10 remain
        // "usable" for typical item granularities.
        if class == 0 {
            score -= 15.0;
        } else if class == 5 {
            score -= 8.0;
        } else if class <= 3 {
            score += 10.0;
        }
    }

    // ---- Capacity-fraction classes of post_residual ----
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
