        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item would need a fresh bin if we place here: mild penalty.
            score += 8.0;
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening new ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: moderate so it wins only when
        // all open bins offer bad fits (large scores).
        score = cap_f * 0.55;
        // Prefer deferring new bins early in the stream when many bins are open
        // and mean residual is high (items could still be consolidated).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 0 && mean_residual > 0.35 * cap_f {
            score += 20.0 * (1.0 - progress);
        }
        // If the item is large relative to capacity, a fresh bin is attractive.
        if item_size as f64 > 0.6 * cap_f {
            score -= 12.0;
        }
    }

    // ---- Slight preference for filling bins tighter as stream progresses ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

