        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Penalize very small unusable residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer filling bins whose residual deviates below the mean (tight packing)
