    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // If open bins have plenty of room, discourage new bin; if residuals are small, allow it
        score += 50.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin useful for upcoming larger items
        }
    }

    // Late in the stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

