    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - post / cap;
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size as f64 == post {
            score -= 30.0;
        } else if (next_item_size as f64) < post {
            score -= 10.0 * (post - next_item_size as f64) / cap;
        } else {
            // next item would not fit here; slight penalty for blocking
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding: many open bins -> prefer filling existing ones
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * crowding * (1.0 - post / cap);

    // Time horizon: later in the stream, consolidation matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post / cap);

    // Mean residual deviation: prefer bins whose residual is near the mean
    // (keeps bin population homogeneous, easier future packing)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev;

    // New-bin candidate: only attractive when current bin fit is terrible
