pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: gaps divisible by small units are reusable.
    let gap = post_residual;
    let mut gap_bonus = 0.0;
    if gap == 0 {
        gap_bonus += 60.0; // perfect fit
    } else if gap % 10 == 0 {
        gap_bonus += 25.0;
    } else if gap % 5 == 0 {
        gap_bonus += 15.0;
    } else if gap % 2 == 0 {
        gap_bonus += 6.0;
    } else {
        gap_bonus -= 8.0; // odd gap, less reusable
    }
    score -= gap_bonus;

    // Dead-space penalty: tiny gaps below the minimum item size are wasted.
    if gap > 0 && gap < 10 {
        score += 40.0;
    }

    // Can next item fit into the post residual? Strong reward (chained fit).
    if next_item_size > 0 {
        if next_item_size <= gap {
            score -= 30.0;
            // harmonic match: gap exactly divisible by next item size
            if gap % next_item_size == 0 {
                score -= 20.0;
            }
        } else {
            score += (next_item_size - gap) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current bin would leave a bad class of gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If the item is large, opening a fresh bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If the current stream is early, fresh bins are fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer tight bins (small residual before placement).
    score += (bin_residual as f64) * 0.15;

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 5 {
        score -= 5.0;
    }

    // Integer-division threshold on post residual: quarter classes.
    let quarter = gap / (bin_capacity / 4).max(1);
    score -= match quarter {
        0 => 10.0,
        1 => 5.0,
        2 => 0.0,
        _ => -5.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: small nonzero residuals are nearly unusable
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }

    // Penalize residuals that cannot fit even the smallest plausible future item,
    // scaled by how close we are to a "wasted" zone
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: reward if next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize blocking the lookahead item
        score += 15.0;
    }

    // Tight fit reward: prefer bins where item fills most of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: when many bins are open, discourage opening new bins
    // (handled implicitly: new empty bin gets high base score via residual = capacity)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when few bins are open or early in stream,
        // but becomes acceptable when fitting bins are scarce
        let pressure = open_bins_count as f64 * 2.0 + progress * 20.0;
        score += pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0; // last chance: allow new bin
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (smaller residual than mean => tighter bin, prefer it)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild pressure to keep open bin count low by filling existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
