pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match (small slack after next item would fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-slack / 12.0).exp();
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use the leftover.
        score += 15.0 + 0.25 * post_residual as f64;
    }

    // Reward bins whose residual is already below average (tight bins close out).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer spreading load when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin: penalize unless nothing else fits reasonably.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
