pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins whose post residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Exact or near-exact fill gets a strong discount.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins where the next item also fits in the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Penalize leaving a residual that is too small for the known next item (dead space risk),
            // but only mildly when the next item is tiny anyway.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive for large items
    // or when all open bins would leave very poor fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalty for spawning bins, softened for large items and late in the stream.
        score += 18.0 - 14.0 * fill_ratio - 6.0 * progress;
        // If many open bins exist with lots of slack, opening yet another is worse.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);
        // But if no open bin fits well (large post residuals elsewhere), allow it.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer placing into bins that are already relatively full compared to the fleet average.
    let bin_fullness = (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 4.0 * (bin_fullness - mean_residual / bin_capacity as f64).max(0.0);

    // Mild stream-horizon shaping: early on, be slightly conservative about fragmentation.
    let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (1.0 - horizon) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
