    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 40.0 * poly * (0.5 + progress);
    score += 10.0 * progress * x;
    // penalize near-full bins that leave unusable slivers late in the stream
    score += (x * x) * (1.0 - progress) * 5.0;
    // last-chance bonus
    if fitting_bins_count == 1 {
