        let bonus = 1.0 / (1.0 + fits_next * fits_next);
        score -= 8.0 * bonus * (1.0 + progress);
        // Penalize if post-residual is just slightly below next item (near-miss waste).
        let gap = (nxt - norm_pr).max(0.0);
        score += 6.0 * gap * gap * cap / cap;
    }

    // Last-chance bin: strong reward to use it (avoid opening new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + 0.8 * progress);
    }

    // Many fitting bins: mild penalty to prefer tighter (fewer) alternatives.
    score += 0.6 * fitting_bins_count as f64;

    // Prefer bins whose residual deviates favorably from mean residual (smooth term).
    score += 0.8 * (mean_residual - bin_residual as f64).abs() * (norm_pr - fit).abs();

    // New-bin candidate: neutral-ish baseline, but discourage early opening,
    // encourage late opening when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score = 18.0 - 6.0 * progress + 2.0 * fit;
        // If placing in an open bin leaves tiny unusable residual, favor new bin.
        if post_residual > 0 && post_residual < item_size.min(20) {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer division.
    let cls = post_residual / 10; // 0..=10 harmonic class
    // Dead space penalty: residuals that few item sizes can use are worse.
    // Small residuals (<10) are pure dead space; mid residuals (10..30) partially usable.
    match cls {
        0 => score += 60.0,                 // unusable sliver
        1 => score += 34.0,
        2 => score += 18.0,
        3 => score += 8.0,
        4 => score += 3.0,
        _ => {}                              // large leftovers are flexible
    }

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover at all: penalize proportionally.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): penalize unless current leftovers are bad
    // or the item fits nothing else. Empty bin residual == capacity => class 10.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If the next item is large and current bin's post-fit leftover is tiny,
        // opening fresh may still be reasonable: soften slightly.
        if next_item_size >= 70 && post_residual < 15 && bin_residual >= item_size {
            score -= 20.0;
        }
    }

    // Capacity fraction: reward placements using >= 70% of capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac >= 0.7 {
        score -= 12.0;
    }

    // Late in stream: prefer closing bins tightly, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.7 * progress);

    // Many open bins: discourage spreading; tighten selection.
    if open_bins_count > 6 {
        score += (open_bins_count as f64 - 6.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
