pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min size 1, but practically tiny gaps) are waste.
    // Penalize unusable gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // a gap smaller than the smallest realistic item is pure dead space
        if gap < 10.0 {
            score += 200.0 * (10.0 - gap);
        } else {
            // mild penalty growing as gap shrinks toward unusability
            score += 0.5 * (10.0 / gap);
        }
    } else {
        // perfect fit: reward strongly
        score -= 150.0;
    }

