    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item can still fit here afterwards: mild reward
        score -= 15.0;
    } else if next_item_size > 0 {
        // next item won't fit in the resulting gap: penalize small gaps more
        let gap = post_residual as f64;
        if gap > 0.0 && gap < next_item_size as f64 {
            score += 0.4 * (next_item_size as f64 - gap);
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Make the empty bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if current item is large, opening fresh is fine
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference for filling bins that are already relatively full
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fullness;

    // Mean-residual coupling: if this bin's residual is far below mean (it is
    // tighter than average), prefer it to consolidate fullness.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.2 * (mean_residual - resid);
    } else {
        score += 0.1 * (resid - mean_residual);
    }

    score
}

