    // leaving this bin far above the mean (fragmentation) or far below.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
