        let fill_ratio = (item_size as f64) / (bin_capacity as f64);
        if fill_ratio < 0.5 {
            score += 120.0; // discourage wasting a fresh bin on small items
        } else {
            score -= 20.0 * fill_ratio; // large items: fresh bin is attractive
        }
    }

    // Late in the stream, be more conservative: keep bins tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
