    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but non-trivial.
    if post_residual > 0 {
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: small unusable leftover (below min item size 1..100 range, treat <10 as dead).
