    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead: if next item could fit into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.15;
    }
