    else if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(10) {
        score -= 3.0;
    }

    // New-bin candidate logic: only attractive when open bins are fragmented or this is a big item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins early, more when few bins open and mean residual is high (existing space usable).
        let mut new_bin_score = 30.0
            + (bin_capacity as f64 - item_size as f64) * 0.4
            - progress * 10.0
