            score -= 22.0;
        }
        // Lookahead: if next item is large too, a fresh bin preserves flexibility.
        if next_item_size > 40 {
            score -= 8.0;
        }
    } else {
        // Penalize placing into a bin whose residual barely exceeds the item (awkward fit).
        if bin_residual < item_size + 12 {
            score += 6.0;
        }
        // Lookahead synergy: reward leaving residual close to next item size.
