pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post-residual is good.
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(2);

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 55.0 * (-gap / 25.0).exp();
    }
    // Penalize post_residual that is too small to ever fit the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins).
    score -= 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += 0.05 * (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);

