pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward when next item fills the remainder nicely.
        let nxt_slack = (post_residual - next_item_size) as f64;
        if nxt_slack < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        let waste = post_residual as f64 - if post_residual >= next_item_size { next_item_size as f64 } else { 0.0 };
        score += waste * 0.3;
