    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new empty bin unless item is large and few alternatives exist.
    if bin_residual == bin_capacity {
        // Base penalty for bin proliferation.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Large items are fine to start a fresh bin.
        if item_size >= 50 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If many fitting bins exist, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate space).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.2;
    }

    // Mild penalty for leaving residuals that no item (min size ~1) can ever use.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic/cubic shaping of normalized residual
    let q = norm_pr * norm_pr;
    let c = q * norm_pr;
    score += 18.0 * q * (1.0 - progress);
    score -= 12.0 * c * progress;

    // Interaction of post residual with stream progress (polynomial in progress)
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * (8.0 * p2 - 14.0 * p3) * cap * 0.05;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize opening a new bin early, more later
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && pr > 0.0 {
        score += 6.0 * (1.0 - pr / (next_item_size as f64 + 1.0));
    }

