    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin anyway; penalize wasting residual space.
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // current item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Large items (integer-division threshold at half capacity) are fine
        // in a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If mean residual across open bins is small, opening a new bin is
        // relatively more attractive.
        if mean_residual < 0.35 * cap_f {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already fit the item, discourage opening yet another.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild consolidation pressure: prefer bins with below-average residual
    // (they are "fuller"), keeping big holes available for big items.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 3.0 * diff;
    }

    // Penalize leaving residual just below the smallest item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the next item are poison.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 1.5;
    }

    // Extra-harsh penalty for tiny unusable slivers (<= 5).
    if post_residual <= 5 {
        score += 25.0;
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward a good fit relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is already small (consolidating fullness).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    // Mild lookahead synergy: if post_residual exactly fits the next item, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // New-bin candidate: keep it competitive only when open bins have tiny residuals.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 950.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            score += 0.10 * dead as f64 ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.5 * waste_ratio + 1.0 * waste_ratio * waste_ratio ;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
        }
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score += 0.08 * dev ;
        }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0 ; }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if next_item_size > 0 && post_residual >= next_item_size && progress > 0.85 { score -= 4.0 ; }
        if next_item_size > 0 && post_residual == 0 { score -= 20.0 ; }
        if next_item_size > 0 && post_residual == next_item_size { score -= 10.0 ; }
        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 { score -= 40.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
    }
    if item_size >= bin_residual { score -= 5.0 ; }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Aggressive 2-step lookahead: reward if the next item exactly or nearly
    // fills the post_residual (perfect chaining).
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (post_residual as f64) >= next_f {
            let gap = post_residual as f64 - next_f;
            // Perfect match: next item consumes all remaining space.
            if gap < 1.0 {
                score -= 60.0;
            } else {
                // Reward proportional closeness of next item to post_residual.
                let match_frac = next_f / post_residual as f64;
                score -= 45.0 * match_frac;
                score += gap * 0.4;
            }
        } else {
            // Next item cannot fit here: penalize small dead space that is
            // likely unusable, scaled by how far the next item overshoots.
            let overshoot = next_f - post_residual as f64;
            score += overshoot * 0.5;
            // Tiny unusable残 residual is dead space.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: strongly prefer zero residual.
        if post_residual == 0 {
            score -= 80.0;
        }
    }

    // Compare against mean residual: placing into a bin with residual far
    // above the mean wastes the "rich" bins; prefer consuming below-mean
    // residual (tighter bins).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: it is an empty bin (residual == capacity).
    // Opening a new bin is only attractive when the current fit is terrible
    // (large post_residual dead space) and there are already several bins
    // competing for future items.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin.
        score = bin_capacity as f64 * 0.9;
        // Attractive if the item is large relative to capacity (good long-run
        // use of fresh space) or if existing fits are all poor.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= item_frac * 30.0;
        // If many bins are open, prefer consolidating rather than opening more.
        score += (open_bins_count as f64) * 2.0;
        // If no other bin fits at all, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, tighten up and
    // avoid sloppy placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize leaving dead space that no typical item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for creating stranded residual.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with residual below the mean (compact the low-residual bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Global state: when many bins are open, discourage opening new bins
    // (make the empty-bin candidate less attractive by penalizing high residual fits less).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and stream progress.
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 40.0;
        // But if item is large relative to capacity, opening fresh space is more forgivable.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Slight time-dependent tightening: later in the stream, waste matters more.
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: residual value decays quadratically with progress
    let decay = 1.0 + prog * prog;
    score *= decay;

    // Penalize large dead space more than linearly (quartic-ish smooth term)
    let dead_frac = pr / cap;
    score += dead_frac * dead_frac * cap * (0.5 + prog);

    // Reward tight fits, smoothly scaled by item size
    let fill = it / cap;
    score -= fill * fill * 20.0;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + prog);
