    // Mild penalty when bin residual deviates from mean residual (diversity control)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += dev * dev * 10.0;

    // Discard opening new bins late in the stream unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - prog);
    }

    score
}

