pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: capacity divided into 10 classes ---
    let class_width = bin_capacity as f64 / 10.0;
    let post_class = (post_residual as f64 / class_width).floor() as u32; // 0..=9
    let next_class = (next_item_size as f64 / class_width).floor() as u32; // 0..=9

    // Reward when next item's class fits exactly into the post-residual class band
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Perfect harmonic match: next item exactly fills a class multiple
        if post_residual % 10 == 0 && next_item_size % 10 == 0 && gap == 0 {
            score -= 25.0;
        }
        // Reward small gaps (tight packing), scaled by class alignment
        score -= (10 - gap.min(10)) as f64 * 0.8;
        // Extra reward if next item's integer-division class equals post class
        if next_class == post_class && post_residual >= next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // Dead space for the lookahead: penalize unusable residual
        score += (post_residual as f64) * 0.35;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 are "harmonic"
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 4.0;
    } else {
        // Odd residues create dead space; penalize proportionally to distance from multiple of 10
        let dist = (10 - (post_residual % 10)) as f64;
        score += dist * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin early (many items to come, keep flexibility), penalize late
        score += 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big next item: fresh bin useful
        }
    }

    // Prefer bins below mean residual (keep tight bins tight, spread load)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Late stream: consolidate, penalize opening new capacity
    if step_index + 1 >= total_items.saturating_sub(2) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
