pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - slack * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += (open_bins_count as f64) * 1.5;

    // Deviation from mean residual: prefer bins with residual close to item usage.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Progression factor: as stream advances, tolerate slightly worse fits less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // New-bin candidate: prefer opening a new bin only when this bin's fit is bad.
    if bin_residual == bin_capacity {
