            score -= 25.0 * fit_frac;
            // harmonic coupling: if next item leaves a clean residue too
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 || next_post == 0 {
                score -= 12.0;
            }
        } else {
            score += 8.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if the current stream is early or all open bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
        // penalize new bin more when open bins are already tight or many exist
        score += 45.0 + 20.0 * mean_tightness + 3.0 * open_bins_count as f64 - 40.0 * (1.0 - progress);
        // item larger than half a bin wastes a fresh bin
        if item_size > bin_capacity / 2 {
            score += 25.0;
        }
    }

    // Mild penalty for fragmenting many open bins when mean residual is small
    if mean_residual < 20.0 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
