        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.5 * shortfall;
    }

    // Exact-match bonus: post_residual equals next item size perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Penalize dead space: post_residual too small to ever fit typical items.
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter packing).
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum() * (bin_residual as f64 - mean_residual);

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 5.0;
        }
    }

    // Stream progression: early on, be slightly more exploratory with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.05 * (1.0 - progress) * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (favor new bins
    // for bad fits); later, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
