pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect 2-step match: strong reward
        if diff < 0.5 {
            score -= 40.0;
        } else if post_residual as f64 > next {
            // next item still fits after this: proportional reward, tighter if closer
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted-looking residuals, worse if close but not fitting
            score += 10.0 + 0.5 * diff;
        }
        // exact two-item fill (post_residual == next_item_size == 0 handled by diff above)
        if post_residual == 0 {
            score -= 25.0; // perfect single-item fill is always great
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tight bins) to consolidate
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early stream: be more selective (penalize loose fits), late stream: just fill
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin late in stream if lookahead suggests a fresh bin helps big next items
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), superlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize residuals that are too small to be useful (dead space).
    // A residual smaller than the minimum plausible item wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }
    // Dead space that cannot fit the lookahead item is less valuable.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still host the next item.
        score -= 8.0;
    }

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if it keeps large future flexibility.
        // Penalize new bins more when many bins already exist or mean residual is high.
        score += 10.0 + 0.35 * open_bins_count as f64 + 0.25 * mean_residual;
        // Slight discount late in the stream (less future to plan for).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * progress;
        // If lookahead is large and this fresh bin fits it perfectly, mild bonus.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 10.0;
        }
    } else {
        // Mild preference for bins with more residual used relative to average.
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Early stream: be slightly conservative, keep bins balanced.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = post / cap;

    // Base: penalize wasted space, with superlinear (cubic) coupling
    let mut score = post * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth non-linear interaction: wasted space matters more as stream progresses
    score += 30.0 * progress * pr_norm * pr_norm * pr_norm;

    // Tight fit reward (smooth, no piecewise): reward small post_residual
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Dead-space penalty: residuals too small for typical future items
    let dead = ((35.0 - post).max(0.0)) / 35.0;
    score += 25.0 * dead * dead;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * (1.0 - pr_norm);
    }

    // Next-item lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0) / cap;
        let miss = (nxt - post).max(0.0) / cap;
        score += 12.0 * fits_next;               // room for next item is good
        score -= 18.0 * (1.0 - miss * cap / nxt.max(1.0)).max(0.0) * miss; // penalty for blocking next
    }

    // Prefer filling bins when many are open (mild, smooth)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Alignment with mean residual: prefer bins near the mean (keeps options open)
    score += 3.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into usable residue classes.
    // Residuals that can still host common small items are valuable.
    let small_threshold = 20u32;
    if post_residual > 0 && post_residual < small_threshold {
        // Dead space penalty: tiny residuals are hard to fill
        score += 25.0 * (small_threshold - post_residual) as f64;
    }

    // Modulo arithmetic on post_residual vs capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual % quarter == 0 && post_residual > 0 {
        // Residual aligns with quarter-capacity classes (25/50/75) -> reusable
        score -= 10.0;
    }

    // Lookahead coupling: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally
            score -= 15.0 + 0.25 * next_item_size as f64;
            // Bonus if next item fits EXACTLY (chained perfect fit)
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; penalize if we leave awkward gap
            let gap = post_residual;
            if gap > 0 {
                score += 0.5 * gap as f64;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless they are bad fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if many items remain and open bins are nearly full, allow new bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
        if progress > 0.5 && open_bins_count > 0 && mean_residual < 0.3 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to mean (balance load)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer tighter fits overall: reward small post_residual relative to item
    if item_size > 0 {
        score -= 0.3 * item_size as f64 / (post_residual + item_size) as f64 * 10.0;
    }

    // Integer division threshold: penalize residuals in (0,10) hard
    if post_residual > 0 && post_residual / 10 == 0 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item (<= 10) are essentially unusable — heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps may fit only tiny items; graded penalty.
        score += 25.0 + (20 - post_residual) as f64 * 1.5;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // If the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit post-placement, mild penalty (chain broken).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: penalize bins with large residuals when many bins
    // are open, pushing toward consolidating into tight bins.
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64)).sqrt();
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: only attractive late in the stream or when
    // the current bin leaves a terrible gap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Slight bias toward using existing bins early.
        score += 15.0 * (1.0 - progress);
        if post_residual < 20 {
            score += 30.0; // opening a fresh bin with a bad first gap is bad
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward when post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Penalize post_residual that is unusable for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit possible.
        score += 0.5 * post_residual as f64;
    }

    // Relative residual pressure vs mean residual across open bins.
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if open bins are crowded.
        let crowding = mean_residual / bin_capacity as f64;
        score += 25.0 * (1.0 - crowding);
        // A new bin is good if it can host the next item too.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: scale relative fill
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Lookahead: if next item fits in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        } else {
            // penalize leaving residual that nothing reasonable can use
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * waste * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Penalize opening new bins when decent open bins exist, more early on
    if is_new_bin {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 20.0 * (1.0 - progress) * (1.0 - pressure);
        // if mean residual is large, opening a new bin is wasteful
        score += 0.3 * mean_residual;
        // new bin is fine if this item is big and residual would be small anyway
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 25.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Dead-space penalty for tiny residuals that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // dead space matters more as the stream advances.
    score += 40.0 * progress * norm_pr * norm_pr;

    // Penalize leaving residual that next item cannot use (smooth gate).
    let next_fits = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        1.0 / (1.0 + gap / 10.0)
    } else {
        0.0
    };
    score -= 12.0 * next_fits * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.3 * (open_bins_count as f64) * ((mean_residual - pr).abs() / cap);

    // New-bin candidate: neutral baseline with slight smooth preference
    // when current bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) + 30.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fraction octiles
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    let octant = (frac * 8.0).floor() as u32; // 0..8

    // Reward placements that land residual in "harmonious" small classes
    match octant {
        0 => score -= 30.0,          // near-perfect fit
        1 => score -= 18.0,
        2 => score -= 8.0,
        3 => score -= 2.0,
        4 => score += 4.0,
        5 => score += 10.0,
        6 => score += 18.0,
        _ => score += 26.0,          // large dead space
    }

    // Modulo arithmetic on post_residual: residuals divisible by small classes
    // pair well with typical item sizes; penalize awkward remainders.
    if post_residual > 0 {
        let r = post_residual % 10;
        if r == 0 {
            score -= 6.0;
        } else if r >= 7 {
            score += 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward scaled by fit tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * tightness;
        } else {
            // next item cannot use this residual: penalize proportional to wasted fraction
            score += 8.0 * (next_item_size.min(post_residual + 100) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Prefer bins among many open bins (reduce bin proliferation)
    score -= 0.5 * open_bins_count as f64;

    // Early stream: be less picky; late stream: be tighter
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Never allow new bin to win if an open bin fits reasonably well
    if bin_residual == bin_capacity {
        score += 55.0 + post_residual as f64;
    }

    score
}

