}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: heavily reward
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits: partial reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - slack / bin_capacity as f64;
            score -= 30.0 * tightness;
        } else {
            // Next item does NOT fit: penalize leaving awkward leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.25 * gap;
        }
    }

    // Penalize tiny unusable dead space (< typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual below the mean (fill emptier-looking space less)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when existing bins fit well, allow when desperate
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only when fits are bad
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin gives good lookahead room
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    score
}

