pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        // Extra reward for a "perfect pair": item + next item exactly fill residual.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize bins whose residual deviates far from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild preference for fuller bins as the stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // or the item fits well somewhere; relax slightly early in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count <= 2 {
            score -= 25.0;
        }
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap;
    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - x) + 0.5 * x * x);
    // Penalize tiny dead space (waste) quadratically
    score += 12.0 * (1.0 - x) * (1.0 - x);
    // Reward tight fits
    score -= 8.0 * (item_size as f64 / cap) * x;
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: prefer it when post_residual is large (good for future items)
    if bin_residual == bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }
    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 5.0 * (1.0 - (post - nx) / cap);
        } else {
            score += 4.0;
        }
    }
    // Mean residual coupling: prefer bins near mean (balance)
    score += 0.05 * (post - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose residual falls in
    // "nice" classes (multiples of small harmonics) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Class 1: residual divisible by 10 (harmonic with min item size 10) -> reward.
        if pr % 10 == 0 {
            score -= 12.0;
            // Extra reward for higher harmonics (20, 30, ...)
            let h = pr / 10;
            score -= (h.min(4)) as f64 * 3.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            // Dead space penalty: residual not matching any harmonic class
            score += 8.0;
        }
        // Very small dead space is nearly useless
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
    } else {
        // Perfect fit: best possible outcome
        score -= 60.0;
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 && pr >= next_item_size {
        // If next item fits harmonically (exact division classes), reward strongly.
        if next_item_size % 10 == 0 && pr % next_item_size == 0 {
            score -= 20.0;
        } else if pr % next_item_size == 0 {
            score -= 10.0;
        } else {
            score -= 5.0;
        }
        // If next item would leave another awkward residual, mild penalty
        let next_post = pr - next_item_size;
        if next_post > 0 && next_post < 10 {
            score += 6.0;
        }
    } else if next_item_size > 0 {
        // Next item does not fit here; if this bin is the last chance, keep it usable anyway
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when all open bins have poor harmonic fits.
    if bin_residual == bin_capacity {
        score = 45.0;
        // Late in the stream or few bins open: opening fresh is cheaper than
        // fragmenting; scale with stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If next item is large and harmonic, a fresh bin is attractive
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Congestion: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Prefer tighter bins when several fit (best-fit bias already via post_residual,
    // but add coupling with item size fraction of capacity).
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0;
    }

    score
}

