pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 15.0;
        }
        // Reward leaving room for the lookahead item if it could use the gap.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance pressure: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly penalize dumping into already-crowded sets,
    // scaled by how much space would remain (wasteful placements hurt more).
    score += open_bins_count as f64 * 0.4 * (post_residual as f64 / bin_capacity as f64);

    // Mild alignment with mean residual: avoid bins deviating far from the pack state.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits strongly (non-linear in post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            // Perfect two-item fill (post_residual == next_item_size) is ideal.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            score += 8.0 * (next - post_residual as f64) / 100.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (large residuals are "easy" bins).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, consolidate: discourage opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when decent fits exist.
        score += 15.0 + 30.0 * progress;
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    // Slight penalty for many open bins to encourage filling existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically
    score += 0.08 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // penalize leaving space that next item only partially uses
            let slack = post_residual - next_item_size;
            score += 0.05 * slack as f64;
        }
        // if next item is big and won't fit here anyway, prefer using this bin
        if next_item_size > post_residual && post_residual < 10 {
            score -= 8.0;
        }
    } else {
        // last item: minimize waste absolutely
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bonus: only bin that fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of opening a bin, modulated by stream progress and crowding
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 35.0 + 20.0 * progress;
        // crowded state: many open bins with low mean residual -> opening is fine
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            new_bin_cost -= 15.0;
        }
        // if this bin can host the next item too, opening is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Mild global pressure: when many open bins, prefer consolidating into existing ones
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Slight preference for bins below mean residual (balancing)
    if bin_residual < bin_capacity {
        score += 0.02 * (bin_residual as f64 - mean_residual);
    }

    score
}

