pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let post = post_residual;
    if post > 0 {
        // Reward post-residuals that are "harmonically compatible" with typical
        // item sizes (divisible by 10, 20, 25, 50) -> likely to be exactly filled later.
        let harmonic_bonus: f64 = if post % 50 == 0 {
            -12.0
        } else if post % 25 == 0 {
            -8.0
        } else if post % 20 == 0 {
            -6.0
        } else if post % 10 == 0 {
            -4.0
        } else {
            0.0
        };
        score += harmonic_bonus;

        // Penalize tiny dead space that nothing (>=1) can use efficiently
        if post < 10 {
            score += 15.0;
        }
    } else {
        // Perfect fill is ideal
        score -= 20.0;
    }

    // Integer-division thresholds: residual fraction classes
    let frac = post as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 5.0; // nearly full bin, fine to use
    } else if frac > 0.5 && post >= next_item_size && next_item_size > 0 {
        // Keep roomy bins for the next item if it fits nicely
        score -= (next_item_size.min(post) as f64) * 0.05;
    }

    // Lookahead coupling: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post && post - next_item_size < 10 {
            score -= 10.0; // near-perfect chain
        } else if next_item_size > post {
            score += 3.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (item_size as f64) * 0.5;
        if crowded && fitting_bins_count > 0 {
            score -= 8.0; // prefer fresh bin when open bins are tight
        } else {
            score += 10.0; // discourage wasting a fresh bin on easy fits
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post as f64) * 0.02;

    // Many open bins: favor filling existing ones
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically gaps < ~15 are hard to reuse) get a heavy penalty.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward reusing tight space: fill fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with open bins count
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But if no open bin fits well (last chance), opening may be fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If next item is small, a fresh bin is more attractive
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly prefer it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins whose residual is close to the item (tight reuse)
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 15.0;
        // Lookahead: if next item fits in the post residual, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize leaving a gap just below next_item_size (near-miss dead space)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild preference to balance residuals across bins
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;

    // Early stream: be slightly more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Slack left for the next item; penalize proportional leftover after the pair.
            let pair_leftover = (post_residual - next_item_size) as f64;
            score += 0.5 * pair_leftover;
        } else {
            // Next item cannot follow in this bin; penalize dead space.
            score += 0.3 * next_item_size as f64;
        }
    }

