    // (concentrating fill), unless it creates unusable sliver.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Penalize tiny unusable residuals (dead space < 10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: default mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        // Late in the stream, prefer reusing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

