    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving large residual that pairs badly.
            score += 4.0 * (post_residual as f64 / 100.0);
        }
    }

    // New-bin candidate handling: neutral baseline with mild preference early,
    // growing penalty late so we consolidate into open bins as the stream ends.
    if bin_residual == bin_capacity {
        let new_bin_bias = 10.0 + 30.0 * progress;
        score += new_bin_bias;
        // Opening a fresh bin is good if the item is large and residual capacity is scarce.
        let avg_resid = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if item_size as f64 > avg_resid {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Mild global pressure: prefer bins below mean residual (keeps residuals balanced).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
