pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening.
    let mut score = pr * (1.0 + 0.6 * fit_norm * (1.0 - fit_norm) * 4.0);

    // Smooth non-linear coupling of dead space with stream progress:
    // late in the stream, small residuals matter more (wasted capacity is costly).
    let late_weight = progress * progress * (3.0 - 2.0 * progress);
    score -= 12.0 * late_weight * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Interaction between post_residual and mean residual: penalize bins whose
    // post-residual deviates upward from the fleet mean (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + late_weight);
    } else {
        score -= 4.0 / (fitting_bins_count as f64);
    }

    // Lookahead: reward leaving room for the next item (smooth hinge).
    let nis = next_item_size as f64;
    if nis > 0.0 {
