    } else if frac < 0.20 {
        score -= 3.0;
    } else if frac < 0.30 {
        // Dead zone: residual too small for most items (1..100 range) — penalize.
        score += 6.0;
    }

    // Harmonic coupling with next item: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 10.0;
        } else if next_post < 10 {
            score -= 6.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize leaving a trap.
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
