    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.10;

    // Modulo threshold on item_size: large items (>= 50) prefer tightest fits.
    if item_size >= 50 {
        score += (post_residual as f64) * 0.05;
    }

    score
}

