        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large and few bins fit,
    // or when no open bin leaves a good post-fit for the next item.
    if bin_residual == bin_capacity {
        score += 25.0; // default penalty for opening a new bin
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pair fits cleanly in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if item_size > bin_capacity / 2 && post_residual < next_item_size {
            score -= 8.0;
        }
        // late in stream, slightly less afraid of new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly prefer minimal leftover space.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * frac * frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead (k=2): reward if the next item can fit into the post residual,
    // penalize if this placement strands space the next item could have used.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // Extra reward for near-perfect chaining.
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 {
                score -= 5.0;
            }
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // This placement destroys a fit the next item could have used.
            score += 4.0;
        }
    }

    // Penalize leaving large residuals when the mean residual is already high
    // (fragmentation pressure): pushes toward consolidating into tight bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins and
    // keep options open; late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: early stream -> cheaper to open; late -> expensive.
        score += 10.0 * (1.0 - progress);
        // If many bins are open already, discourage opening yet another one.
        score += 0.3 * open_bins_count as f64;
        // Never open a new bin for a tiny item if a reasonable fit exists.
        if item_size < 30 {
            score += 15.0;
        }
    } else {
        // Existing bin: late stream rewards packing more strongly.
        score -= 6.0 * progress;
        // Reward using bins with less residual (fill fuller bins first).
        score += 0.1 * bin_residual as f64;
    }

    // Slight preference for bins whose residual is "awkward" (hard to fill later),
    // i.e. residual not matching common item sizes, to clean them out.
    let awkward = (bin_residual % 10 != 0) as f64;
    score -= 2.0 * awkward * (item_size as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via non-linear coupling with progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward filling bins deeply as stream progresses (smooth polynomial)
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 && pr > 0.0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 12.0 * (gap / cap).powi(2) * (1.0 - progress);
        } else {
            score -= 8.0 * (1.0 - progress); // perfect chain with lookahead
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // New-bin candidate handling: penalize opening new bins early,
    // increasingly acceptable late or when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = pr + 40.0 * (1.0 - progress) * (1.0 - fragmentation)
            + 10.0 * open_bins_count as f64 / (10.0 + open_bins_count as f64);
    }

    // Mild penalty for spreading across many open bins
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Prefer bins with residual near the item size (smooth kernel)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * diff * diff;

    score
}

