pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes.
    // Small post_residual in "good" classes (0, 5) means near-perfect fit.
    let pr = post_residual as i64;
    let class = pr % 10;
    match class {
        0 => score -= 18.0,
        5 => score -= 12.0,
        1 | 9 => score += 6.0,
        _ => {}
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: post_residual too small for any plausible item (min size 1)
    if post_residual > 0 && post_residual < 5 {
        score += 25.0; // creates unusable sliver
    }

    // Harmonic fraction of capacity used
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item leaves another clean class
            let nxt_pr = post_residual - next_item_size;
            if nxt_pr % 10 == 0 {
                score -= 14.0;
            } else if nxt_pr % 5 == 0 {
                score -= 7.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; residual becomes dead space if small
            if post_residual < next_item_size && post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // New-bin candidate logic: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let tight_fits = fitting_bins_count;
        // open new bin early in stream or when item is large (few future partners)
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size > bin_capacity / 2 { 20.0 } else { 0.0 };
        score = 45.0 - progress * 10.0 + large_item_bonus
            - if tight_fits == 0 { 10.0 } else { 0.0 };
    }

    // Prefer bins below mean residual (keep balance, save fat bins for big items)
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful again
    // are heavily penalized (items in stream are >= 1, so gap < min useful
    // threshold is near-certain waste unless it can host the next item).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        let can_host_next = next_item_size > 0 && next_item_size <= post_residual;
        if !can_host_next {
            score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        } else {
            // A gap that exactly chains into the next item is a perfect fit.
            score -= 25.0;
        }
    }

    // Reward tight fits (post_residual close to zero but not the penalty zone).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // If the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: with many bins open, prefer consolidating into
    // existing ones; a new empty bin should only win when fits are terrible.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so it loses to decent fits.
        score = bin_capacity as f64 * 0.9 + 15.0 * pressure;
        // Late in the stream, slightly discourage spawning new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        score -= 3.0 * pressure;
    }

    // Prefer bins whose residual is below the mean (filling the emptiest-waste first).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: dead space below a small threshold is heavily penalized.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 150.0;
        } else if gap <= 5 {
            score -= 80.0;
        } else if gap <= 15 {
            score -= 25.0;
        } else if post_residual < next_item_size as f64 {
            // next item cannot use this leftover: dead space penalty scaled by gap
            score += (gap as f64).min(40.0) * 0.5;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual as f64 > mean_residual * 1.5 {
            score += 20.0; // but a very wasteful fit still gets punished
        }
    }

    // New-bin candidate: penalize opening a fresh bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 15.0; // opening new bin is more attractive if next item is large
        }
    }

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // small unusable slivers are wasted capacity
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack);
        } else {
            // next item cannot fit here; mild penalty proportional to gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is costly when decent fits exist elsewhere.
        // Encourage it only when the item is large relative to capacity or
        // open bins are mostly full (low mean residual).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fill_pressure = 1.0 - mean_residual / bin_capacity as f64;
        let open_pressure = (open_bins_count as f64).ln() / 10.0;
        score += 30.0 - 25.0 * item_frac - 20.0 * fill_pressure - 10.0 * progress + open_pressure;
    } else {
        // Prefer fuller bins among open ones: reward low residual relative to mean.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 15.0 * dev; // bins with less residual than mean get lower score
    }

    // Time horizon: early in the stream, be more conservative (favor packing into
    // existing bins); late in the stream, tightness matters most anyway.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Slight tie-break toward bins that leave residuals matching common item sizes.
    if post_residual >= 10 && post_residual <= 80 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, larger post_residual is tolerable (bins stay flexible);
    // late in the stream, dead space becomes costly, so weight grows.
    let base = norm_pr * (1.0 + 2.5 * progress * progress);

    // Cubic penalty on wasted residual, amplified by progress.
    let waste = 1.8 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: item_size close to bin_residual.
    let tightness = -1.2 * (1.0 - norm_pr).max(0.0) * (0.3 + progress);

    // Penalize bins that are much worse than the average residual
    // (deviation coupling, non-linear).
    let dev = (pr - mean_residual) / cap;
    let dev_pen = 0.6 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    let last_chance = if fitting_bins_count == 1 { -2.0 } else { 0.0 };

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item would leave a large awkward residual elsewhere, or
    // when the next item is big and this bin's post-residual can't hold it.
    let is_new_bin = bin_residual == bin_capacity;
    let next_fits_here = (next_item_size as f64) <= pr && next_item_size > 0;
    let next_fits_new = (next_item_size as f64) <= cap;
    let new_bin_penalty = if is_new_bin {
        let awkwardness = (norm_pr - 0.1).max(0.0);
        let lookahead_gain = if next_item_size > 0 && !next_fits_here && next_fits_new {
            0.4 * (next_item_size as f64 / cap)
        } else {
            0.0
        };
        0.9 + 1.5 * awkwardness * (1.0 - progress) - lookahead_gain
    } else {
        0.0
    };

    // Mild synergy: prefer placing into bins whose residual matches the item
    // via a smooth Gaussian-like kernel.
    let match_kernel = -0.8 * (-(norm_item - (1.0 - norm_pr)) * (norm_item - (1.0 - norm_pr)) / 0.02).exp();

    let mut score = base + waste + dev_pen + new_bin_penalty
        + tightness + last_chance + match_kernel;

    // Small regularization against many open bins with large residuals.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

