pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band it falls into.
    // Dead space bands: (0..10] nearly unusable, (10..30] poor, (30..50] fair, >50 good.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 30 {
        score += 8.0;
    } else if pr <= 50 {
        score += 0.0;
    } else {
        score -= 5.0;
    }

    // Harmonic coupling with next item: reward residuals that exactly / nearly fit lookahead.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 15.0;
        } else if slack <= 30 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: residual becomes potential dead space
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Modulo-based harmonic penalty: residuals that are multiples of small classes
    // (10, 20, 25) are more reusable by typical item sizes.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 4.0;
    }

    // Penalize wasting a very full bin on a small item (poor density).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio < 0.3 && bin_residual <= 40 {
        score += 12.0;
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - pr as f64) * 0.1;

    // Mild preference to spread across many open bins when mean residual is high.
    score += (mean_residual - pr as f64).max(0.0) * 0.05;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 30.0; // discourage opening new bin when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver (min item size baseline)
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap cannot hold the lookahead item: dead space relative to lookahead.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit tilt).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when current item is large relative to
    // available fits and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = 55.0 + fragmentation * 0.8 + 20.0 * (1.0 - progress)
            - (item_size as f64) * 0.25;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // pairing lookahead with a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly (post_residual near 0 is already low).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = post_residual - next_item_size;
        score -= 50.0 + (chain_fit as f64).min(30.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use the leftover space.
        score += 40.0 + post_residual as f64 * 0.5;
    }

    // Compare residual against the mean residual of open bins:
    // prefer bins that are already "tight" (below mean residual) to consolidate waste.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could still hold the item,
    // unless the fit is terrible (post_residual large) and the next item is big.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 60.0;
        let next_needs_space = next_item_size > 0 && next_item_size >= post_residual;
        if poor_fit && next_needs_space && open_bins_count > 0 {
            score -= 120.0; // prefer fresh bin for bad fits
        } else {
            score += 100.0; // generally avoid opening new bins
        }
    }

    // Slight consolidation pressure early in the stream: keep bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that can't host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave this bin with a tiny useless remainder, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score += 8.0;
    }

    // New-bin candidate handling: neutral base for empty bin, but discourage
    // opening new bins when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64);
        }
        // Late in stream, opening new bins is fine; early on, reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Prefer bins with residuals below the mean residual (fill the emptier ones? no:
    // fill the tighter ones to keep large residuals available) — reward bins tighter than mean.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Mild penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with a non-linear polynomial in post_residual.
    let mut score = pr_norm * pr_norm * 120.0 + pr_norm * 40.0;

    // Smooth non-linear coupling with stream progress: early on, waste tolerance is high;
    // later, dead space is penalized more aggressively.
    let progress_coupling = (0.5 + 0.5 * progress) * (pr_norm * pr_norm * pr_norm) * 150.0;
    score += progress_coupling;

    // Reward using a nearly-full bin (small post_residual) with a saturating term.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well the item actually fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 60.0 * (0.5 + 0.5 * fit_quality);
    }

    // New-bin candidate handling: an empty bin is a fallback; penalize it mildly so
    // decent fits win, but the penalty shrinks as the stream progresses (avoid
    // accumulating many poorly-filled bins late).
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - 0.6 * progress);
    }

    // Lookahead: if the next item would fit in the resulting residual, reward it;
    // if post_residual is too small for the next item, add a smooth penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 18.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 12.0 * ((nxt - pr) / cap);
        }
    }

    // Mild preference to balance residuals across open bins: prefer bins whose
    // post-residual lands near the current mean residual.
    let mean_gap = (pr - mean_residual).abs();
    score += (mean_gap / cap) * 8.0;

    // Slight bonus for consolidating when many bins are open.
    score -= (open_bins_count.min(20) as f64) * 0.3 * tightness;

    score
}

