pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals in the same "decile band"
    // are treated as equivalent dead-space classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class_band = (post / 10.0).floor(); // 0..=10 harmonic class of leftover
    let dead_penalty = match class_band as u32 {
        0 => 60.0,          // 0-9: perfect fit zone, reward strongly
        1 => 8.0,           // 10-19: awkward sliver
        2 => 14.0,          // 20-29: fits only tiny items
        3 => 18.0,
        4 => 10.0,          // 40-49: half-bin class, decent
        5 => 6.0,
        6 => 12.0,
        7 => 16.0,
        8 => 20.0,
        9 => 4.0,           // 90-99: nearly empty, flexible
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward exact-capacity-fraction fits (harmonic fractions of C).
    let frac = item_size as f64 / cap;
    let frac_err = (frac * 4.0).round() / 4.0 - frac; // distance to 1/4,1/2,3/4 classes
    score -= 25.0 * (1.0 - 4.0 * frac_err.abs());

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let npost = (post_residual - next_item_size) as f64;
            score += npost * 0.6 + if npost < 10.0 { 30.0 } else { 0.0 };
        } else {
            // next item won't fit here; leftover must stand alone
            score += 15.0;
        }
    }

    // Integer-division threshold: post_residual divisible by 10 is a "clean class".
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish score anchored near mid-residual so it wins
    // only when all open bins would create bad classes.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.3 * mean_residual + (open_bins_count as f64).sqrt() * 4.0;
    }

    // Mild stream-phase tilt: later in the stream, consolidation matters more.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * 6.0 * (post / cap);

    score
}

