pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps still mildly penalized relative to tight fits.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Perfect-match lookahead: if the next item exactly fills the post residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item can fit into the resulting gap: mild reward.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 8.0;
    }
    // Next item would leave this gap unusable: penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize placements that leave lots of bins open with
    // scattered residual; prefer consolidating into already-open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; grows with number of open bins.
        score += 25.0 + open_bins_count as f64 * 1.5;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 10.0;
        }
        // Late in the stream, prefer reusing open bins even more.
        score += 30.0 * progress;
        // If the next item is large, a fresh bin may be valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (i.e., fuller bins) to consolidate small gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Aggressive 2-step lookahead: strongly reward exact match of next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward only if next item leaves a small remainder
            score -= (1.0 - slack / bin_capacity as f64) * 25.0;
        } else {
            // next item cannot follow into this bin: penalize proportionally
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.6;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Penalize creating tiny unusable dead space (waste fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins less attractive unless current fits are poor
    if bin_residual == bin_capacity {
        score += 8.0;
        // but if next item is large and this item is small, fresh bin is fine
        if next_item_size >= 70 && item_size <= 30 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, penalize opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 50 {
        score -= 5.0; // reusable space
    } else {
        score += 8.0; // large leftovers suggest wasted capacity
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 4.0;
        }
        // Perfect chaining: item + next exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, pack aggressively into whatever fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual means
    // fragmentation; encourage consolidating into existing bins.
    let fragmentation = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * (open_bins_count.max(1) as f64));
    score += 6.0 * fragmentation;

    // New-bin candidate handling: an empty bin should only win when the item
    // is huge (poor fit everywhere else) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 30.0; // default penalty for opening a new bin
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 35.0; // big items are fine to start fresh
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative at all
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows quadratically as wasted space increases.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling between post_residual and stream progress:
    // later in the stream, tightening fits matters more (quadratic in progress).
    let coupling = 2.0 + 6.0 * progress * progress + 3.0 * progress;
    score *= coupling;

    // Reward tight fits: interaction of item_size with bin_residual,
    // smooth via normalized fill ratio cubed.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill * fill * cap * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth penalty).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let deficit = ((ns - pr) / cap).max(0.0);
        score += 25.0 * deficit * deficit * cap;
        // Reward leaving room exactly for the lookahead item.
        let match_term = 1.0 - ((pr - ns) / cap).abs();
        score -= 8.0 * match_term.max(0.0) * match_term * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    // (avoids opening a new bin), scaled smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 2.0 * progress);
    }

    // Mild preference for bins with residuals near the mean (balance),
    // quadratic in deviation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight penalty for accumulating many open bins late in stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "usable" classes (multiples of common item sizes), penalize dead space
    // in awkward classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: residual divisible by 10 -> highly reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class 2: residual divisible by 5 but not 10 -> mildly reusable.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class 3: residual leaves a small awkward remainder (< 10) -> dead space.
    if post_residual % 10 != 0 && post_residual % 10 < 5 {
        score += 4.0;
    }

    // Integer-division thresholds on post_residual: very small residuals are
    // nearly dead space; large residuals are still flexible.
    let q = post_residual / 10;
    match q {
        0 => score += 12.0,               // post_residual < 10: nearly dead
        1 => score += 5.0,                // 10..19: tight but usable
        2 => score += 1.0,                // 20..29
        3 | 4 => score -= 1.5,            // 30..49: sweet spot
        _ => score -= 0.5,                // >= 50: flexible
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly into the
    // post residual (same class), strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the fit
            let slack = (post_residual - next_item_size) as f64;
            if slack % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 4.0 * (1.0 - slack / 40.0).max(0.0);
            }
        } else {
            // next item won't fit here: slight penalty, worse if the gap is small
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * (1.0 - gap / 50.0).max(0.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large and residuals elsewhere are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // A new bin is attractive only when the item is big and open bins are fragmented.
        let size_frac = item_size as f64 / cap;
        score += 30.0 - 20.0 * size_frac - 10.0 * fragmentation - 5.0 * progress;
    }

    // Mild penalty proportional to how much this placement deviates from the mean
    // residual balance (keeps bin load balanced across harmonics).
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (min item size is 1, but tiny gaps fragment capacity) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // next item fills this bin exactly
        } else if gap < 0 && gap > -10 {
            score += 20.0; // just barely can't fit next item: bad fragmentation
        } else if gap > 0 && gap < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by open-bin pressure and stream position.
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let mut nb = 45.0 + 12.0 * pressure;
        // Late in the stream, opening fresh bins is fine; early on, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 20.0 * progress;
        // If this bin's fit is bad (large post_residual relative to mean), new bin looks better.
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality > 0.5 {
            nb -= 25.0;
        }
        // If next item is large, a fresh bin with full capacity is valuable.
        if next_item_size >= 60 {
            nb -= 15.0;
        }
        score = score.min(nb) + nb * 0.0; // new-bin score is just nb
        score = nb;
    } else {
        // Mild preference for bins tighter than average (best-fit flavor).
        score -= 0.05 * (mean_residual - bin_residual as f64);
        // Open-bin count pressure: discourage spreading across many bins.
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits.
    let post = post_residual as f64;
    score -= 40.0 * (-post / 12.0).exp();

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but imperfectly: mild reward proportional to
        // how tight the second residual would be.
        let second_residual = (post_residual - next_item_size) as f64;
        score -= 15.0 * (-second_residual / 15.0).exp();
    } else if next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize wasted chain
        // potential, scaled by how much space is stranded.
        let stranded = (next_item_size - post_residual) as f64;
        score += 0.08 * stranded;
    }

    // Relative to mean residual: bins tighter than average are better
    // targets for large items; keep loose bins available.
    let dev = mean_residual - post;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize creating dead space that nothing (min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when many bins are open but this is a fresh empty one.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins with decent fits win.
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: post_residual small relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 50.0 / (1.0 + tightness);

    // Penalize dead space that no plausible item can fill (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // small unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 80.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        score += 10.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual below the mean (consolidate emptier space usage)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for many open bins -> encourage filling existing bins early on
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.2 * open_bins_count as f64;

    // New-bin candidate handling: empty bin should only win when fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in stream
        score += 45.0 + 30.0 * (1.0 - progress);
        // If current bin would leave a very awkward residual, opening new bin is fine
        let awkward = (post_residual as f64 / bin_capacity as f64) < 0.15 && post_residual > 0;
        if awkward {
            score -= 40.0;
        }
        // If next item is large and this item is small, new bin gives more room
        if next_item_size >= 50 && item_size <= 30 {
            score -= 15.0;
        }
    }

