pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small but nonzero post_residual is wasted space.
    // Harmonic classes: post_residual buckets via integer division thresholds.
    let cls = post_residual / 10; // class 0..=9
    match cls {
        0 => score += 45.0,           // 1..9: nearly unusable dead space
        1 => score += 25.0,           // 10..19
        2 => score += 12.0,           // 20..29
        3 => score += 5.0,            // 30..39
        4 => score -= 3.0,            // 40..49: half-bin-ish, reusable
        5 => score -= 6.0,            // 50..59
        6 => score -= 8.0,            // 60..69
        7 => score -= 9.0,            // 70..79
        _ => score -= 10.0,           // 80+: very reusable
    }

    // Modulo-10 coupling: residuals divisible by 10 pair well with
    // common item sizes (multiples of 10), reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual != bin_residual {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward scaled by tightness
        let tight = (post_residual - next_item_size) as f64;
        score -= 15.0 - tight.min(30.0) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item does NOT fit here: penalize leaving residual it nearly fits
        let miss = (next_item_size - post_residual) as f64;
        score += miss.min(40.0) * 0.5;
    }

    // New-bin candidate handling: an empty bin has high post_residual;
    // only prefer it when no open bin is attractive (mean residual low
    // relative to item, or item is large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins early / when open bins have room.
        score += 35.0 + progress * 20.0 + open_bins_count as f64 * 2.0;
        if mean_residual >= item_size as f64 {
            score += 25.0; // open bins could host: discourage new bin
        }
        if item_size >= 60 {
            score -= 30.0; // big items are hard to place later: allow fresh bin
        }
    }

    // Mild preference for filling fuller bins (low residual) overall.
    score += (bin_residual as f64) * 0.05;

    // Tie-break with mean residual context: if this bin is fuller than average, favor it.
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.1;

    score
}

