        score += 55.0; // default penalty for opening a new bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 45.0; // existing bins fit poorly; new bin is fine
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if progress > 0.9 {
            score -= 5.0; // late stream: less compounding benefit of reuse
        }
    }

    // Lookahead: penalize placements that leave a gap exactly unusable by next item.
