        score += 8.0;
    }
    // Reward leaving a gap that perfectly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Mild alignment with mean residual: prefer bins near the mean (balanced packing).
    score -= 0.5 * (post_residual as f64 - mean_residual).abs().recip().min(2.0);

    score
}

