    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward if the next item also fits afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + next_item_size as f64;
        // Bonus if post_residual is close to next_item_size (tight chain fit).
        let slack = (post_residual - next_item_size) as f64;
