        if item_size >= bin_capacity * 9 / 10 {
            score -= 100.0;
        }
    }

    // Slight preference to fill bins that are already below average residual
    // (keeps other bins flexible for future items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score += 5.0;
