    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let nxt_tight = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 * nxt_tight;
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted residual.
            let waste = (post_residual as f64).min(next_item_size as f64 - 1.0);
            score += 0.25 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins far below the mean residual (they hoard space), mildly.
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Time horizon: late in the stream, be more conservative about residual waste;
    // early on, allow spreading to build flexible bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
