    // Reward filling bins deeply, with an accelerating (quadratic) fill term.
    let fill = 1.0 - norm_pr;
    score -= cap * 2.5 * fill * fill * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - next_fit) * (1.0 - next_fit) * (1.0 + progress);
        // Slight penalty if next item barely fits, leaving a dead sliver.
        score += 3.0 * next_fit * next_fit;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize wasted residual proportionally to its size.
        score += 2.0 * norm_pr * norm_next * cap;
    }

