    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates far from the mean (fragmentation signal).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * (0.5 + progress);

    // Slight penalty for spreading across many open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: make it attractive only when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
