    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * fit_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor bins where the item fits snugly.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - residual_frac).powi(3);

    // Two-step lookahead: reward if the next item also fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * next_fit_quality;
        // Extra bonus for a perfect 2-step chain (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use, scaled by how much is wasted.
        let waste = post_residual as f64 - (next_item_size as f64 * 0.5);
        if waste > 0.0 {
            score += 0.15 * waste;
        }
    }

    // Relative-to-mean adjustment: bins below mean residual are already tight; prefer
    // filling them rather than spreading load across looser bins.
    let mean_frac = mean_residual / bin_capacity as f64;
