        score -= large_item_bonus;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, discourage new bins unless the fit is excellent.
        score += 15.0 * progress;
    }

    // Mild penalty for creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference to keep the number of open bins manageable.
    score += 0.5 * open_bins_count as f64;

    score
}

