pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post_residual), with non-linear shaping
    let mut score = 100.0 * x * x + 20.0 * x;

    // Smooth polynomial coupling with stream progress:
    // early on, prefer leaving room for medium items; late, prefer very tight fits
    let prog_term = (1.0 - progress) * (x - 0.5) * (x - 0.5) - progress * x * x;
    score += 30.0 * prog_term;

    // Dead-space penalty: post residual that no plausible item can use
    let dead = if x > 0.0 && x < 0.1 { (0.1 - x) * 200.0 } else { 0.0 };
    score += dead;

    // Lookahead: bonus if next item fits exactly or nearly in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            // next item won't fit here; slight penalty for near-full bin waste
            score += 5.0 * (1.0 - x);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty to keep flexibility, scaled by mean residual
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt() * (1.0 - mean_residual / cap);
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, better
    // only when current fits are poor (high post residual relative to next item)
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - 10.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space is worst when it is
    // small-but-not-zero (unusable by typical items). Classify modulo 10.
    let r = post_residual;
    if r == 0 {
        score -= 25.0; // perfect fit: strongly reward
    } else {
        let m = r % 10;
        // residuals just above 0 are the most useless "dead" leftovers
        let dead_penalty = match m {
            0 => 2.0,
            1 => 10.0,
            2 => 9.0,
            3 => 7.0,
            4 => 6.0,
            5 => 4.0,
            6 => 5.0,
            7 => 6.0,
            8 => 7.0,
            _ => 8.0,
        };
        score += dead_penalty;

        // integer-division classes: how many "typical" items still fit
        let quints = r / 20;
        score += 3.0 * (4 - quints.min(4)) as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= r {
        let exact = (r - next_item_size) % 10;
        score -= if r == next_item_size { 18.0 } else if exact == 0 { 12.0 } else { 6.0 };
    } else if next_item_size > r {
        // next item won't fit here: penalize leaving this bin as the trap
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current bin's post-residual
    // is a poor harmonic class and mean residual is already fragmented.
    if bin_residual == bin_capacity {
        score = 12.0 + mean_residual * 0.15;
        if next_item_size > 0 && next_item_size <= r {
            score += 20.0; // don't open new bin if current one chains nicely
        }
        if fitting_bins_count <= 1 && r >= 10 {
            score += 15.0;
        }
    }

    // Stream progression: late in the stream, tighten packing (prefer exact fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (r == 0) as i32 as f64;
    score += 3.0 * progress * ((r > 0 && r < 10) as i32 as f64);

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

