    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps that no item (min size 1..10 typical) can use are toxic.
    // A tiny nonzero gap is worse than a large one; exact fit (0) is perfect.
    if post_residual == 0 {
        score -= 200.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        // unusable sliver: penalize heavily, worse the smaller the sliver
        score += (10 - post_residual) as f64 * 15.0;
    } else if post_residual <= 30 {
        // small-ish gap: mildly penalize, since few item sizes fit well
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward bins whose residual is large enough to still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // bin becomes dead after this placement relative to lookahead
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_penalty = open_bins_count as f64 * (1.0 + 0.5 * progress);
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += bin_penalty * (1.0 - fit_quality);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it beats a poor fit into an open bin.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin, softened when open bins are few or residual is tight
        score += 30.0 + 2.0 * open_bins_count as f64 - 0.2 * mean_residual;
    } else {
        // prefer tighter fits among open bins
        score -= (bin_residual - post_residual) as f64 * 0.1;
    }

    score
}

