        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect chain match gets a big reward.
        if gap < 1.0 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits: reward proportionally to snugness.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize dead space.
            score += 10.0 + gap / bin_capacity as f64 * 15.0;
        }
    }

    // Penalize post-residuals that are small-but-unusable (dead space below min item size 1..100 heuristics).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Favor bins whose residual deviates from the mean (tighter-than-average bins absorb items well).
