    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild reward for keeping many bins consolidated when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Late in the stream, prefer tighter packing (lower post_residual relatively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    // Never prefer a fresh empty bin unless open bins would leave big waste.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

