pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer placements that leave little waste.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.1 {
        score += 8.0 * (0.1 - dead) / 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward for an exact chain fit.
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else if post_residual > 0 {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Global state coupling: when open bins are slack, prefer filling them
    // rather than opening new ones; when they are tight, allow new bins.
    let slack = mean_residual - post_residual as f64;
    score += 0.3 * slack;

    // Time horizon: early in the stream, be conservative (prefer new bins
    // for poor fits); late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - dead);

    // New-bin candidate: only attractive when open bins fit poorly.
