        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            (bin_capacity as f64 - (bin_capacity - item_size) as f64) / bin_capacity as f64
        };
        let pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score -= 18.0 * (1.0 - pressure) - 10.0 * poor_fit + 8.0 * progress;
