    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Base: prefer small post-residual (tight fit), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth non-linear coupling of post-residual with stream progress:
    // later in the stream, dead space becomes more costly (quadratic in progress).
    score += 8.0 * progress * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-ish term).
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= 20.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as f64) < pr {
        // next item fits: mild reward proportional to how much would remain after
        let npr = pr - next_item_size as f64;
        score -= 6.0 * (1.0 - npr / cap);
    } else if next_item_size > 0 {
        // next item won't fit in post-residual: penalize wasted potential
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Compare against mean residual: bins with much less residual than average
    // are more valuable to fill; bins with more residual are safer to keep.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty when many bins are open (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

