    // only when post-residual of existing bins would be very small (poor fits)
    // or very large (item barely fits anywhere).
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 0.5 * pr / cap) + 5.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: how close post_residual is to a "useful" residue
    // (a multiple of a small harmonic unit). Reward post residuals that could host common items.
    let harmonic_units: [u32; 6] = [10, 20, 25, 33, 50, 100];
    let mut best_fit_bonus = 0.0f64;
    for &u in harmonic_units.iter() {
        let r = post_residual % u;
        let dist = r.min(u - r) as f64;
        let closeness = 1.0 - dist / (u as f64 / 2.0);
        best_fit_bonus = best_fit_bonus.max(closeness * (u as f64).sqrt());
    }
    score -= best_fit_bonus * 4.0;

    // Exact-fill bonus: perfect fit is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: post residual too small for the minimum item size (1) is fine,
    // but residuals in the "useless middle" band are penalized.
    let small = item_size.min(next_item_size.max(1));
    if post_residual > 0 && post_residual < small.max(1) {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted opportunity.
            score += 10.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly; scale with stream progress and open bin count.
        score += 25.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // new bin useful if a bigger item follows
        }
    } else {
        // Reward using existing bins proportionally to how full they already are.
        let fill_frac = 1.0 - bin_residual as f64 / cap;
        score -= 20.0 * fill_frac;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter packing).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Progress modulation: later in stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post * 0.1;

    // Modulo-threshold penalty on awkward residual classes (e.g., residual ≡ small odd values mod 10).
    let m = post_residual % 10;
    if m >= 1 && m <= 3 {
        score += 8.0;
    } else if m == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 range, but small gaps < next_item or < 10-ish
    // typical) are likely unusable. Penalize gaps that nothing can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        // gap can't hold the known next item -> probable dead space
        score += 25.0;
    } else {
        // gap is usable: reward tight fits
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 20.0 + 8.0 * open_bins_count as f64;
        // but if this bin would leave the current bin nearly full anyway,
        // new bin is fine (already accounted by post_residual = large)
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // lookahead favors fresh capacity
        }
    }

    // Progression coupling: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from mean (keep mean low).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is already good via the base term.
    // Strongly reward exact 2-step matches: post_residual == next_item_size
    // means the next item fills this bin perfectly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that is too small for the next item but nonzero
        // (dead space blocking the lookahead item).
        if next_item_size > post_residual {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste.min(40.0);
        }
    }

    // Penalize post_residual that is unusably small (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Compare against mean residual: bins with residual far from the mean
    // that remain large after placement are less attractive.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive if no good fit exists; make the empty
    // bin moderately expensive so open bins with decent fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if lookahead item would fit a fresh bin perfectly after this one,
        // soften the penalty.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.5;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins -> prefer filling existing ones (penalize new bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + (open_bins_count as f64).sqrt() * 5.0;
        // If nothing else fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (more crowded bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // Prefer bins with residual close to item size (perfect packing pressure).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, with smooth polynomial growth
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, dead space matters more (fewer chances to fill it)
    let progress_coupling = norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 20.0 * progress_coupling * (norm_pr - 0.5).abs() * 2.0;

    // Reward tight fits: subtract smoothly as post-residual approaches zero
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 15.0 * tightness * (item_size as f64 / cap);

    // Lookahead coupling: reward if next item fits smoothly in post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            score += 5.0 * ((nx - pr) / cap).powi(2);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins near the mean (keeps residuals balanced)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress * 0.5);

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists; smooth in item size and progress.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / cap).powi(2);
        score += 30.0 - 25.0 * large_item - 10.0 * progress;
    }

    // Mild open-bins pressure: discourage proliferation of open bins
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
