    // capacity-fraction bands (dead-space classes).
    let frac = post_residual as f64 / bin_capacity as f64;
    // Harmonic penalty: leftover space is worse the closer it is to a
    // "useless middle band" — too big to ignore, too small for typical items.
    let class = if post_residual == 0 {
