        1.0
    } else if frac <= 0.20 {
        2.0
    } else if frac <= 0.30 {
        3.5
    } else if frac <= 0.40 {
        4.5
    } else if frac <= 0.50 {
        5.0
    } else {
        6.0 // large leftover: bin was probably a bad choice
    };
    score += class * 3.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly,
    // penalize leftovers that nearly-but-not-quite fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 40.0; // chains perfectly into next item
            } else if slack < 10 {
                score -= 12.0; // next item consumes almost everything
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot fit here: leftover likely becomes dead space.
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 8.0; // painful near-miss
            } else {
                score += 2.0;
            }
        }
    } else {
        // Last item: only total leftover matters.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly.
        // Base cost of a fresh bin: its full residual (already in score) plus
        // a fixed opening penalty scaled by how many bins are already open.
        score += 20.0 + (open_bins_count as f64).sqrt() * 5.0;
        // If many bins are open and mean residual is high, prefer existing bins.
        score += mean_residual * 0.3;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Reusing an open bin: reward keeping the number of open bins low.
        score -= 5.0;
        // Slight preference for tighter bins among fitting candidates.
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Modulo/harmonic texture on post_residual: leftovers that are multiples
    // of common item granularities are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

