        score += 0.5 * post_residual as f64;
    }

    // Reward bins tighter than average (packing dense bins first)
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0
            + 0.5 * (bin_capacity - item_size) as f64   // large items waste less
            - 10.0 * (item_size as f64 / bin_capacity as f64);
