    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead synergy: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        let slack_after_next = pr - next_item_size as f64;
        score -= 12.0 * fits_next * (1.0 - (slack_after_next / cap).powi(2));
        score += 6.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, penalize opening a new bin
