        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly early, allow late if residuals are fragmented
    score += is_new * (10.0 + 30.0 * (1.0 - progress) * (mean_residual / cap).powi(2));

    // Penalize bins far from mean residual (fragmentation avoidance)
