    // Mild encouragement to fill fuller bins as stream progresses
    score -= 10.0 * progress * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it decomposes into
    // small-item-friendly residue classes (multiples of 10 / 25 / 50).
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fill
    } else if pr <= 10 {
        -18.0
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: residual too small for typical items (1..=100 range)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Next-item coupling: reward if the next item fits exactly or nearly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 12.0 * (1.0 - waste as f64 / cap);
        } else {
            // next item won't fit here; mildly penalize leaving awkward gap
            score += 4.0 * (next_item_size - pr) as f64 / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fractional-fill coupling: prefer bins whose fill ratio post-placement is high
    let fill = (bin_residual - pr) as f64 / cap;
    score -= 10.0 * fill * fill;

    // Progress-based modulation: later in the stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Penalize opening new bins when decent options exist
    if bin_residual == bin_capacity {
        let avg_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if avg_fit >= item_size as f64 {
            score += 20.0 + 0.3 * avg_fit;
        } else {
            score -= 5.0;
        }
    }

    // Mean-residual alignment: favor bins close to the mean residual (keeps spread balanced)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

