            // proportionally to how "wasted" the gap is.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, allow opening new ones more freely.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score = bin_capacity as f64 * 0.6 + pressure * 12.0;
        // If the item fits poorly anywhere else, new bin is attractive.
        if post_residual == bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        score += pressure * 2.0;
    }

    // Prefer bins whose residual is close to the current mean (balance),
    // slightly penalizing outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Late in the stream, tighten: prefer tighter fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    score
}

