pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // next item still fits: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * snug;
        } else {
            // next item cannot fit here: penalize dead space creation
            score += 80.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin early when open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 + waste * (0.3 + 0.7 * progress);
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Prefer using bins with low residual overall (tight packing) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear squaring
    // so that leaving large dead space is disproportionately punished.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete: prefer reusing the fullest bin,
        // which is already reflected by post_residual, but discourage
        // spreading across many half-empty bins.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead (k=2): if the next item fits exactly-ish in the post_residual,
    // reward this placement (chain packing); if next item is large and this
    // placement leaves a residual that only wastes space, penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            // Reward chains, best when the next item leaves near-zero slack too.
            score -= 15.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: the residual is dead
            // space relative to the stream; penalize proportionally.
            score += 5.0 * (pr / 100.0);
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals clean); late in the stream, squeeze everything into
    // existing bins to avoid a final bin with almost nothing in it.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early, less late.
        score += 25.0 * (1.0 - progress);
        // Opening a new bin is unattractive if the item fits snugly somewhere.
        if post_residual <= 10 {
            score += 40.0;
        }
    } else {
        // Late stream: reward using existing bins.
        score -= 10.0 * progress;
    }

    // Global state coupling: if mean residual across open bins is high,
    // there is plenty of slack available; discourage opening new bins and
    // discourage leaving even more slack behind.
    if mean_residual > 0.0 {
        score += 0.15 * (mean_residual - post_residual as f64).abs();
        if bin_residual == bin_capacity && mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing ones.
    if open_bins_count > 4 {
        if bin_residual < bin_capacity {
            score -= 3.0 * (open_bins_count as f64).ln();
        } else {
            score += 3.0 * (open_bins_count as f64).ln();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly damped by progress (late stream: prefer tight fits even more)
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear penalty on small post-residuals creating dead space, stronger late
    let dead = (1.0 - norm_pr).powi(3);
    score += 40.0 * dead * (0.4 + 0.6 * progress);

    // Smooth coupling: reward large item filling a bin (high norm_item, low post_residual)
    score -= 25.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Prefer bins with residual below mean (consolidate fuller bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for opening new bins when many bins exist
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Harmonic class of post_residual: dead space below the smallest
    // possible item (1..=100 unknown dist, assume min 10) is worthless.
    if post_residual < 10 {
        score -= 25.0; // perfect closure
    } else {
        // Penalize dead space in awkward bands: residual that no typical
        // item can fill well (mod classes of capacity).
        let q = post_residual / 10;
        let r = post_residual % 10;
        // Waste quantization: residuals with small remainder mod 10 are
        // more reusable; large remainders are dead weight.
        score += 0.6 * (r as f64);
        // Penalize large-but-unfillable residuals nonlinearly.
        if post_residual < 20 {
            score += 8.0;
        } else if post_residual < 35 {
            score += 3.0;
        }
        let _ = q;
    }

    // Lookahead coupling: reward residual that exactly hosts next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 12.0; // next item won't fit here
        }
        // Harmonic divisibility bonus: residual divisible by next size.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 45.0 - 25.0 * pressure.min(2.0);
        // Early stream: opening bins is cheap; late stream: expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Mild preference to spread across bins when many are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // (below the minimum plausible item size) are strongly penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 45 {
        score += 8.0;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 50.0;
    } else if (post_residual as i64 - 0).abs() <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual closely matches the item (best-fit refinement).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += fit_gap * 10.0;

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is cheaper.
    let open_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; becomes attractive
        // only when existing bins would leave bad dead space.
        score = 40.0 + open_pressure * 10.0;
        if post_residual >= 45 {
            score -= 5.0;
        }
    } else {
        // Slight reward for reusing an existing bin, scaled by pressure.
        score -= open_pressure * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: penalize bins far below mean residual
    // (they are "almost full" -> good to fill them completely).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;
        // Perfect chain bonus: item + next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Two-item chain: current + next + one more fits exactly (post_residual - next small).
        let chain = post_residual as i64 - next_item_size as i64;
        if chain > 0 && chain <= 10 {
            score -= 8.0;
        }
        // Penalize leaving residual the next item cannot use (dead space until later).
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // Last item: minimize waste directly.
        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near mean (balanced packing),
    // but strongly prefer using very full bins (small residual) to close them out.
    let res = post_residual as f64;
    if res < 20.0 {
        score -= 12.0 * (20.0 - res) / 20.0;
    }
    score += (res - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening unless current bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.8;
        if fitting_bins_count > 0 && !poor_fit {
            score += 20.0 + crowding * 2.0;
        }
        // Early stream: allow opening bins more freely to build a portfolio of residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with tighter fit relative to item size.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 12.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly in post residual.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 20.0;
        } else if next_item_size as f64 > post_residual as f64 {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        } else {
            score -= (post_residual as f64 - next_item_size as f64).min(20.0) * 0.3;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: as stream progresses, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, penalize less when open bins are fragmented.
        score += 8.0 + 10.0 * (1.0 - progress);
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // Existing bin: mild bonus late in the stream to consolidate.
        score -= progress * 3.0;
    }

    // Mild penalty for opening too many bins relative to load.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (penalize large residuals); later, tolerate
    // larger residuals since bins will be closed anyway.
    let tightness = (pr / cap).powi(2) * (1.0 - progress) * 60.0;
    score += tightness;

    // Smooth interaction: residual^3 term scaled by progress to reward
    // filling bins nearly exactly as the stream matures.
    score += (pr / cap).powi(3) * 40.0 * progress;

    // Reward exact-ish fits regardless of progress (smooth exponential bonus).
    score -= (-pr / 12.0).exp() * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (pr / cap);
    }

    // New-bin candidate: mildly penalize early, allow later when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Penalize bins whose residual is far from the mean (fragmentation signal),
    // smoothly weighted by number of open bins.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 20.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction bands. Residuals in [0, ~10] are near-perfect fits;
    // residuals in awkward mid-bands (just below common item sizes) are dead space.
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr <= 5 { 1 }
        else if pr <= 12 { 2 }
        else if pr <= 19 { 3 }
        else if pr <= 34 { 4 }
        else if pr <= 49 { 5 }
        else { 6 };

    // Penalize mid-band dead space quadratically; reward tight fits.
    match class {
        0 => { score -= 30.0; }
        1 => { score -= 18.0; }
        2 => { score += 6.0; }
        3 => { score += 14.0; }
        4 => { score += 4.0; }
        5 => { score -= 2.0; }
        _ => {}
    }

    // Lookahead: does next_item_size fit exactly/nicely into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.35; // penalize leaving unusable slack for next item
            // modulo harmony: post_residual divisible by next item size => good reuse
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual at all: residual value drops
            score -= 3.0 + nxt / cap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // unless the fit is terrible (huge post_residual on an otherwise fresh bin).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + item_size as f64 * 0.15;
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // (mean residual small) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score = 100.0 - mean_residual * 0.4 - progress * 15.0 + open_bonus * 3.0;
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 10.0; // next item may not fit open bins -> new bin good
        }
    }

    // Small global tie-breaker toward fuller bins.
    score -= (1.0 - (bin_residual as f64) / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver gap
    } else if post_residual < 20 {
        score += 25.0; // near-dead gap
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // residual likely dead for next item
    }

    // Prefer tight fits: how well item fills the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open bins pressure: discourage spreading across many bins, but keep
    // mild pressure to close bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: placing in a bin below mean residual keeps
    // larger residuals available for larger future items.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when current
    // open bins would be badly fragmented; otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        score = 45.0 + 3.0 * open_bins_count as f64 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // reward when post_residual exactly matches the next item size (perfect pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            score -= 60.0; // perfect two-item pairing
        } else {
            // penalize residual that cannot accommodate next item, reward partial match
            if post < nxt {
                score += (nxt - post) * 0.35;
            } else {
                score -= (post - nxt).min(20.0) * 0.8;
            }
        }
        // bonus if next item fits exactly in post_residual AND this bin was tight before
        if post >= nxt && (post - nxt) < 5.0 {
            score -= 15.0;
        }
    } else {
        // last item: strongly prefer smallest post residual
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tight bins)
    let res = bin_residual as f64;
    score += (res - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count == 2 {
        score -= 10.0;
    }

    // Penalize new empty bins unless the item fits poorly everywhere:
    if bin_residual == bin_capacity {
        // opening a new bin wastes potential; make it costly, but slightly cheaper
        // when many bins are open (fragmentation risk) or stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0 - 25.0 * (1.0 - progress) - (open_bins_count.min(10) as f64) * 1.5;
        // allow new bin if item is huge (poor fit likely elsewhere)
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    }

    // Mild penalty for dead space that is too small to be useful (below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible future item can use.
    // Items can be as small as 1, but small dead space is still wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    }
    // If next item would fit better in a different bin, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 15.0 - 2.0 * pressure.min(7.0);
        // Early in stream, opening new bins is cheap (future items unknown).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress);
    }

    // Prefer filling fuller bins when many bins are open (consolidation).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill_frac * fill_frac;

    // Global residual balance: prefer bins below mean residual when mean is low.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear penalty for residual dead space: quadratic coupling with progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: cubic in (1 - normalized residual)
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * tight * (1.0 + progress);

    // Dead space unusable by next item: smooth interaction
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 25.0 * gap * gap / (1.0 + norm_next);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer fuller bins relative to mean residual of open bins
    let mean_norm = mean_residual / cap;
    score -= 10.0 * (mean_norm - norm_pr) * (mean_norm - norm_pr).max(0.0);

    // Late stream: penalize leaving large residuals more (less future to fill them)
    score += 20.0 * progress * norm_pr * norm_item;

    // Many open bins: slight penalty to spreading; favor consolidation
    score += (open_bins_count as f64).ln() * norm_pr * 3.0;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 8.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "wasteful" is the leftover space?
    // Residuals that are exact multiples of common item sizes (10, 20, 25, 50) are
    // reusable; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is ideal
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 {
        -18.0 // highly reusable leftover
    } else if pr % 5 == 0 {
        -6.0
    } else {
        // penalize prime/awkward residuals proportionally
        8.0 + (pr % 7) as f64 * 2.0
    };
    score += harmonic_bonus;

    // Integer-division threshold: small post-residuals are dead space
    let dead = pr / bin_capacity; // 0 for pr < 100
    let _ = dead;
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: does post_residual still fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0; // chain placement possible
            // harmonic match: leftover after chaining is a nice class?
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 || chain_left == 0 {
                score -= 8.0;
            }
        } else {
            score += 10.0; // this bin will be stranded after this placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        // among many options, prefer tighter fit: scale by fraction of bin used
        score += (item_size as f64 / bin_capacity as f64) * 4.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no open bin
    // fits well (post_residual large) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin baseline: slightly worse than a good existing fit
        score = 30.0 + progress * 20.0 - (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // fresh bin pairs well with upcoming large items
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

