pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any future item
    // (assume min item size ~ 10, but stay robust for 1..100 ranges) are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // unusable sliver -> strong penalty
    } else if (post_residual as f64) < 25.0 {
        score += 12.0; // likely dead space
    } else {
        // Usable gap: reward proportionally (subtract to favor)
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        if post_residual - next_item_size <= 5 {
            score -= 12.0;
        }
    }
    // If next item does NOT fit the post_residual, mild penalty for tight coupling
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> favor filling existing ones,
    // and make new bins (residual == capacity) less attractive.
    let bin_pressure = open_bins_count as f64 * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure so it's chosen only when
        // existing bins fit poorly.
        score += 35.0 + bin_pressure;
    } else {
        score -= bin_pressure * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already tight; prefer compacting it.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // Early stream: be slightly more willing to open bins (future items unknown);
    // late stream: consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 20.0;
    } else {
        score += progress * 8.0;
    }

    score
}

