pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base score.

    // Dead-space penalty: residual that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, encouraging spread of options
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 3.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, consolidate aggressively (avoid opening new bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses and when open bins exist
        let mut new_bin_penalty = 15.0 + 40.0 * progress;
        if open_bins_count > 0 {
            new_bin_penalty += 10.0 * (open_bins_count as f64).min(10.0);
        }
        // early stream: fresh bins are fine, allow exploration
        new_bin_penalty -= 20.0 * (1.0 - progress);
        score += new_bin_penalty.max(-20.0);
    } else {
        // existing bin: reward using open bins more when many are open
        score -= (open_bins_count as f64).min(8.0) * 1.5 * (0.3 + 0.7 * progress);
    }

    // Large item handling: big items deserve near-full bins to avoid fragmentation
    if item_size >= 60 {
        score += 8.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Small exploration noise substitute: deterministic pseudo-variation from state
    let tie_break = ((bin_residual as f64 * 1.7 + item_size as f64 * 0.9 + step_index as f64 * 0.13) % 7.0) * 0.01;
    score += tie_break;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual (bigger leftover is better), with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tighten bins more aggressively (reward small post_residual)
    score -= 30.0 * progress * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize bins whose residual deviates from mean (encourage uniform packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    } else {
        // Mild reward when many bins compete (we can afford to be picky)
        score += 2.0 / (fitting_bins_count as f64 + 1.0);
    }

    // Lookahead: reward if next item fits smoothly into post_residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 15.0 * (-gap * gap * 20.0).exp() * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many are already open
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (large enough to host typical small items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: leftover too small for even the smallest item.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Harmonic classes via integer division thresholds on post_residual.
    // Class 0: pr == 0  -> perfect fit, huge reward.
    if pr == 0 {
        score -= 200.0;
    } else {
        // Quotient classes: pr / 10 gives a coarse harmonic index 0..=10.
        let q = pr / 10;
        match q {
            0 => score += 25.0,          // 1..9 : nearly dead space
            1 => score -= 10.0,          // 10..19: fits small items
            2 | 3 => score -= 15.0,      // 20..39: versatile zone
            4 | 5 => score -= 20.0,      // 40..59: fits half-bin items
            6 | 7 => score -= 8.0,       // 60..79: medium
            _ => score += 5.0,           // 80..99: large leftover, wasteful placement
        }
    }

    // Modulo arithmetic on post_residual: leftovers divisible by 10 pair well
    // with item sizes drawn from decile-quantized distributions.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Leftovers congruent to small odd residues are awkward.
    if pr % 10 != 0 && pr % 5 == 1 {
        score += 4.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            score += 6.0;
        }
        // Harmonic pairing: next item in same decile class as post residual.
        if (next_item_size / 10) == (pr / 10) && next_item_size <= pr {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening
    // a new bin when mean residual across open bins is still large.
    if bin_residual == bin_capacity {
        score = 0.5 * cap - mean_residual * 1.2;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits: new bin is fine
        }
        if next_item_size > item_size && next_item_size > 50 {
            score -= 8.0; // big item coming, fresh bin attractive
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - prf / cap);

    // Slight preference for fuller bins relative to mean residual.
    score -= (mean_residual - prf) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below the minimum item size 1..~10 are pure waste)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Penalize medium dead-space zone (10..=30) that few items can use
    if post_residual >= 10 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 8.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize with open bin pressure and residual mean context
        score += open_bins_count as f64 * 3.0 + mean_residual * 0.3 + progress * 5.0;
        // Allow new bin only if it can absorb the next item too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0;
        }
    } else {
        // Favor existing bins that can also host the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 {
            score += 3.0;
        }
    }

    score
}

