    // New-bin candidate: penalize unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap;
        score = 40.0 + 30.0 * (1.0 - avg_fullness) + 0.5 * post_residual as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

