        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: smooth in 1/fitting_bins_count
