    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure proportional to open bins
        score += 30.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build a pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    } else {
        // Using existing bins relieves open-bin pressure slightly
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins with below-mean residual (tighter bins first, best-fit style)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if next <= post {
            // Next item fits perfectly into the remaining space.
            score -= 6.0 * (1.0 - gap / post.max(1.0));
            if gap == 0.0 {
                score -= 15.0; // perfect chaining bonus
            }
        } else {
            // Next item would not fit here: penalize leaving awkward space.
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer minimal final waste.
        score += 0.3 * post_residual as f64;
    }

    // Compare against mean residual across open bins.
    let post = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    if post < mean {
        score -= 1.5 * (mean - post); // tighter fit than average
    } else {
        score += 0.8 * (post - mean); // looser fit than average
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // Prefer fuller bins overall.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 2.0 * fill;

    // Penalize tiny unusable dead space (fragmentation).
    if post > 0.0 && post < 10.0 {
        score += 3.0;
    }

    // Mild encouragement to consolidate into fewer bins.
    score += 0.15 * open_bins_count as f64;

    // Slight preference for opening new bins late in the stream if fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when post_residual would still be useful.
        score -= 2.0 * progress;
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
