    // waste becomes more costly as the stream advances (quadratic in progress).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress * progress);
