    let tightness = (-pr / 20.0).exp();
    score -= 25.0 * tightness * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate: penalize so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 55.0 + 30.0 * (1.0 - progress);
    }

