pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (halves, thirds, quarters) and reward placements
    // that land the residual in a "usable" harmonic class.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: residual is a multiple of 25 (quarter harmonics) -> highly reusable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class 2: residual is a multiple of 20 (fifth harmonics)
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Class 3: residual is a multiple of 10 (tenth harmonics)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    // Penalize odd residuals (dead-space prone under integer item sizes)
    if post_residual % 2 == 1 {
        score += 2.0;
    }

    // Fraction-of-capacity thresholds on post_residual
    if pr <= cap / 4.0 {
        score += 5.0; // tiny leftover = wasted bin space
    } else if pr >= cap / 2.0 {
        score -= 3.0; // half or more left = flexible bin
    }

    // Integer-division threshold: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly consumes residual class
            if post_residual % next_item_size.max(1) == 0 && next_item_size == post_residual {
                score -= 10.0;
            } else if next_item_size + 10 >= post_residual {
                score -= 5.0; // near-perfect follow-up fit
            } else {
                score -= 1.5; // next item fits somewhere in this bin
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close it was
            let gap = (next_item_size - post_residual) as f64;
            score += 1.0 + gap / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline new-bin cost: opening a bin is expensive unless open bins are tight
        score += 15.0
            - 10.0 * (mean_residual / cap).min(1.0)
            + (open_bins_count as f64).sqrt() * 0.5;
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
        // If next item is huge, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 4.0;
        }
    }

    // Prefer packing into bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    // Mild pressure to use many-open-bin states efficiently
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item are "dead". Penalize the worst band hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver: almost guaranteed dead space
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // risky zone: only fits small items
    } else if post_residual > 80 {
        score += 8.0; // near-empty bin barely improved: wasteful placement
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when the item fits very poorly everywhere else or open-bin pressure is low.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score = 45.0 + 3.0 * pressure - 10.0 * tightness;
        // If lookahead item is large and current item small, new bin keeps
        // large residual for the big item — mildly attractive.
        if next_item_size > 60 && item_size < 30 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead coupling: if the post residual exactly accommodates the next
    // item, this placement sets up a perfect follow-up — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 15 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins to keep bin count down.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if this bin's residual is far above mean, it is
    // a "loose" bin — placing here wastes the space other items may need.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 20.0 {
        score += 0.15 * dev;
    } else if dev < -20.0 {
        score -= 0.10 * (-dev);
    }

    score
}

