pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strong baseline penalty, reduced when current bin fits are poor.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 0.0 } else { 12.0 };
        return 95.0 + scarcity - (post_residual as f64) * 0.3;
    }

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.6;
    } else {
        // Dead space: post_residual too small for next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
        // Reward tight fits now (small post_residual relative to mean residual).
        if (post_residual as f64) < mean_residual {
            score -= (mean_residual - post_residual as f64) * 0.25;
        } else {
            score += (post_residual as f64 - mean_residual) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Penalize leaving residuals in the awkward 1..=9 dead zone.
    if post_residual >= 1 && post_residual <= 9 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below
    // next-item threshold is worse. Penalize residual that is unusable
    // relative to the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 8.0; // perfect slot for the next item
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6; // dead space for lookahead
        } else {
            score -= 2.0; // can still host the next item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize leaving very small crumbs (<10) which are likely wasted.
    if post_residual < 10 {
        score += 4.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when existing fits are poor
        // (many fitting bins means we should use one of them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 4.0 * (fitting_bins_count as f64).min(5.0) + 3.0 * progress;
        // If the item perfectly fills a fresh bin, opening is great.
        if post_residual == 0 {
            score -= 20.0;
        }
    } else {
        // Reward filling existing bins nearly completely.
        if post_residual == 0 {
            score -= 15.0;
        }
        // Encourage using bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score -= (1.0 - tightness / bin_capacity as f64) * 3.0;

        // Global pressure: when many bins are open with small mean residual,
        // prefer consolidating into fuller bins.
        let pressure = mean_residual / bin_capacity as f64;
        score += pressure * 2.0;
    }

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    // normalized stream progress in (0,1)
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = t.clamp(0.0, 1.0);
    // normalized post residual
    let x = pr / cap;
    // smooth non-linear coupling: dead-space penalty grows quadratically with residual,
    // modulated by stream progress (late stream -> punish wasted space more)
    let dead = x * x * (0.5 + 1.5 * t);
    let mut score = base + 40.0 * dead;
    // reward tight fits: small post residual gets a smooth cubic bonus
    let tight = (1.0 - x).powi(3);
    score -= 30.0 * tight;
    // lookahead: if next item fits exactly in post residual, reward strongly (smooth gate)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 - pr).abs() / cap;
        let gate = (-8.0 * fits * fits).exp();
        score -= 25.0 * gate * (1.0 - 0.5 * t);
    }
    // last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // slight pull toward bins below mean residual (balance residuals smoothly)
    score += 0.15 * (pr - mean_residual) * (1.0 - t);
    // new-bin candidate: residual == capacity -> penalize smoothly, stronger early
    if (bin_residual as f64 - cap).abs() < 0.5 {
        score += 15.0 + 20.0 * (1.0 - t) + 0.5 * open_bins_count as f64;
    }
    score
}

