pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in (0,10) is nearly useless
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr < 10 {
        score += 25.0; // tiny unusable sliver
    } else if pr < 25 {
        score += 8.0;
    } else if pr < 50 {
        score -= 5.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalty scaled by how far the next item misses this bin
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with less residual among equally-good fits (best-fit bias)
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    // Progress-aware new-bin control: opening a fresh bin is attractive early,
    // discouraged when many bins are already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score -= 40.0 - 20.0 * progress - 2.0 * openness.min(10.0);
    }

    // Slight preference for bins already below mean residual (balancing)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Modulo harmonic class: multiples of 10 residual are more reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
