pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post residual just barely too small for next item: small dead space, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Post residual slightly larger than next item: leaves awkward sliver afterwards.
    if next_item_size > 0 && post_residual > next_item_size {
        let overshoot = post_residual - next_item_size;
        if overshoot <= 10 {
            score += 6.0 + overshoot as f64 * 0.5;
        }
    }

    // Exact fill of the bin is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Reward bins tighter than the mean residual (good consolidation).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Large items early in stream justify a fresh bin.
        if item_size >= 70 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Progression: later in stream, be greedier about closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: early vs late stream behavior.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small to ever fit typical items are wasted.
    // Anything below the minimum plausible item size is pure loss.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.max(item_size as f64 * 0.15);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 2.5;
        }
