pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimizing post residual, with smooth non-linear shaping.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, leave flexible space; late, pack tightly (quadratic/cubic blend).
    let flex = 1.0 - progress;
    score += 0.35 * flex * post * post / cap;
    score -= 0.20 * progress * post * post * post / (cap * cap);

    // Reward tight fits (small post residual) with a smooth saturating bonus.
    let tightness = 1.0 - post / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize dead space that can't fit the mean-size item.
    if post > 0.0 {
        let waste = 1.0 - (post / (mean_residual.max(1.0) + post)).max(0.0);
        score += 2.0 * waste * post / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (post - nx).max(0.0) / cap;
        score -= 3.0 * fit_next * (1.0 - fit_next);
        // Penalize post residual that is just barely too small for next item.
        if post < nx && post > 0.0 {
            score += 2.5 * (nx - post) / cap;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when existing bins would leave tiny unusable slivers,
        // or when many bins are open and mean residual is large.
        let sliver_penalty = if post < 10.0 { 0.0 } else { 0.0 };
        let _ = sliver_penalty;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let mean_tight = (mean_residual / cap).max(0.0);
        // New bin is attractive late in stream or when open bins are already tight.
        score += 10.0 - 6.0 * pressure * mean_tight - 4.0 * progress;
        // But a brand-new bin wastes full capacity; keep a floor penalty.
        score += 0.15 * cap * (1.0 - mean_tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small residuals that no item (>=1) can use well
        // Items are 1..=100; residual < next plausible item is dead-ish
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }

        // Harmonic residue classes: residuals near half-capacity are valuable
        let half = cap * 0.5;
        let quarter = cap * 0.25;
        if ((pr - half).abs() < 10.0) {
            score -= 6.0;
        }
        if ((pr - quarter).abs() < 5.0) {
            score -= 3.0;
        }

        // Integer-division threshold classes on post_residual
        let class = post_residual / 20; // 0..5
        score -= (class as f64) * 4.0; // larger usable residual slightly favored
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here anyway; slight penalty for leaving awkward gap
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current bin would leave
    // an awkward gap and mean residual across bins is already low.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 90.0;
        // cheaper to open new bin when stream is early (amortization)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // if existing fit would be terrible (large post residual gap vs item), new bin more attractive
        let gap = (bin_residual - item_size) as f64;
        score -= (gap / cap) * 10.0;
        // if many open bins with high mean residual, prefer filling them
        score += (open_bins_count as f64).ln().max(0.0) * 8.0 + (mean_residual / cap) * 20.0;
    }

    // Tight-fit reward relative to residual before placement
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) {
        score += 60.0;
    }
    // Gaps too small for any plausible item (below typical minimum) are dead space.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0;
    }
    // Gap below the lookahead item but nonzero: future-unusable, penalize scaled by lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to residual).
    if bin_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 20.0 * tightness;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins, favor consolidation
    // unless this is a last-chance fit.
    if fitting_bins_count == 1 {
        score -= 35.0; // last chance before opening a new bin
    } else {
        score += 0.8 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose leftover deviates favorably from the mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: default moderate score; only attractive when all fits are bad.
    if bin_residual == bin_capacity {
        score = 120.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is fine early in the stream or when many bins exist.
        if step_index < total_items / 10 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Slight progression bias: later in the stream, avoid opening new bins.
    score += 10.0 * (step_index as f64 / total_items as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1000.0;
    }
    // Reward if next item fits into the post-residual (chain continuation).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * (next_item_size as f64) / (post_residual as f64).max(1.0);
    }
    // Penalize if post_residual is a dead sliver the next item cannot use.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 0.3 * (post_residual as f64) * (post_residual as f64) / (item_size as f64).max(1.0);
    }

    // Prefer bins whose residual is already below mean (tight bins) to keep loose bins open.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * item_size as f64;
        // But allow opening a new bin when many bins are open and item is big.
        if item_size >= 70 && open_bins_count > 2 {
            score -= 120.0;
        }
    }

    // Late in the stream, consolidate: prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: early vs late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual is already favored by the base score,
    // but amplify near-perfect fits nonlinearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill, always take it
    } else if post_residual <= 10 {
        score -= 30.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 50.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual is dead space relative to the next item: penalize proportionally,
        // especially for small leftovers that nothing can use.
        score += 0.5 * post_residual as f64 * (1.0 - progress * 0.5);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has huge residual, so its raw score is high.
    // Only prefer it when existing fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Neutralize the raw residual so a new bin competes fairly; then add a mild
        // opening cost that shrinks as the stream progresses (fewer chances left to reuse).
        score = bin_capacity as f64 * 0.6 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> encourage consolidation
    // into existing bins; penalize placements that leave big gaps when bins are abundant.
    if open_bins_count > 3 {
        let waste = (post_residual as f64 - mean_residual).abs();
        score += 0.1 * waste * (open_bins_count as f64).ln().max(1.0);
    }

    // Small penalty for very large dead space late in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (1.0 - progress); // tiny gaps early are risky, less so late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nres = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * (nres * nres) * (1.0 - t);
    score += 20.0 * (nres * nres * nres) * t;
    score -= 6.0 * nres * t * (1.0 - t);

    // Perfect fit reward (smooth, no piecewise)
    let fit_quality = 1.0 - nres;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize wasted residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 10.0 * gap * gap;
        score -= 8.0 * ((pr / next_item_size as f64).min(2.0)) * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild pressure toward consolidating many open bins
    score += (open_bins_count as f64) * 0.05 * nres;

    // Prefer bins below-average residual when stream is late
    score += 3.0 * (pr - mean_residual) / cap * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the leftover space (decile classes)
    let class = post_residual / 10;
    match class {
        0 => { score -= 25.0; }              // near-perfect fit, almost no dead space
        1 => { score -= 12.0; }              // small but usable
        2 => { score -= 4.0; }               // moderate leftover
        3 => { score += 3.0; }
        4 => { score += 6.0; }
        5 => { score += 9.0; }               // half-empty bin: mediocre
        6 => { score += 12.0; }
        7 => { score += 15.0; }
        8 => { score += 18.0; }
        _ => { score += 22.0; }              // nearly full residual before placement
    }

    // Lookahead: reward residuals that exactly host the next item, penalize
    // residuals that waste space relative to it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // leftover still fits next item: mild bonus scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - (slack / 10.0).min(10.0);
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly reward, avoids opening a new bin needlessly.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into
    // already-open bins rather than fragmenting further.
    if !is_new_bin {
        score -= (open_bins_count.min(20) as f64) * 0.5;
        score -= mean_residual * 0.1;
    }

    // New-bin candidate: acceptable only for large items or when open bins
    // would be badly fragmented; scale by stream progress.
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let penalty = 35.0 + 40.0 * (1.0 - item_frac) + 15.0 * progress;
        score += penalty;
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative: opening a new bin is fine
        }
    }

    // Integer-division threshold coupling: residual/10 == item_size/10
    // suggests the leftover belongs to the same harmonic class family.
    if post_residual > 0 && (post_residual / 10) == (item_size / 10) {
        score += 5.0; // leftover similar in size to item: harder to reuse
    }

