    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Opening a new bin is acceptable if item is large and would leave a
        // small unusable gap in an existing bin.
        if post_residual < 10 && post_residual > 0 {
            score -= 70.0;
        }
        // Favor new bin late in the stream when residuals are fragmented.
        if open_bins_count as f64 > mean_residual / 10.0 {
            score -= 10.0;
        }
    } else {
        // Slight penalty for using a bin whose residual deviates from mean
        // (keep bin profile uniform).
        score += 0.05 * ((bin_residual as f64) - mean_residual).abs();
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0; // dead space confirmed by lookahead
    }

    // Progression: earlier in stream, be more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Exact match: dominant bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leftovers too small for the next item (dead space risk).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative-to-mean term: prefer bins with below-average residual (denser bins).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Tight fit reward: small post residual relative to capacity is good, but
    // avoid creating tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: neutral baseline; only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 10.0;
        // Late in the stream, opening new bins is more costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins fit already, discourage opening a new one.
        score += 5.0 * fitting_bins_count as f64;
    }

    // Mild pressure to prefer filling bins with many open bins (bin-count control).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    let post = post_residual as f64;
    score -= 60.0 * (-post / 8.0).exp();

    // Penalize tight-but-not-perfect fits that leave awkward slivers
    if post > 0.0 && post < 10.0 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // chain fit is possible: reward, scaled by how well the chain uses space
            score -= 25.0 * (nxt / (post - nxt + nxt)).min(1.0);
        } else {
            // leftover dead space relative to next item: penalize mildly
            score += 0.15 * (nxt - post).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into tightest bin
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling: an empty bin is a last resort unless it enables
    // a much better long-term packing. Penalize it, less so late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let early_bonus = 40.0 * (1.0 - progress);
        score += 55.0 - early_bonus;
        // opening a new bin is more attractive when open bins are mostly full
        score -= 0.3 * mean_residual;
    }

    // Prefer bins with below-average residual (tighter bins) slightly
    score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

