    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling: post_residual weighted by stream progress
    score *= 0.8 + 0.4 * progress * progress;
    // reward tight fits with a non-linear term
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness;
    // penalize residuals that cannot fit the lookahead item (smooth ramp)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 20.0 * gap * gap;
        // bonus if post_residual exactly accommodates next item
        let match_fit = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 10.0 * match_fit * match_fit;
    }
    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }
    // penalize spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs();
    // new-bin candidate: keep neutral-ish, mildly penalized unless residuals are wasted
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }
    score
