            // next item won't fit here; penalize mildly so we prefer bins that chain
            score += 6.0;
            if post_residual < 10 {
                score += 10.0; // chained dead space is fine actually -> but keep penalty consistent
            }
        }
    } else {
        // last item: just minimize waste
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral baseline, but discourage when open bins fit well
    if bin_residual == bin_capacity {
        // base cost of opening a bin; adjusted by stream progress and current open count
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // if next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 15.0;
        }
        // if mean residual across open bins is small, opening new bin is worse
        score += mean_residual * 0.5;
    }

    // Mild preference to fill bins with larger mean residual (balance)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

