pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that the next item cannot use (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover can host the next item.
            let slack = post_residual - next_item_size;
            score -= 3.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to waste.
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 6.0; // near-perfect fill leaves almost unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is penalized more early (want bins filled first),
        // slightly relaxed late in the stream.
        score += 12.0 + 6.0 * (1.0 - progress);
        // If many bins fit already, new bin is clearly worse.
        if fitting_bins_count > 0 {
            score += 5.0 * fitting_bins_count as f64;
        }
        // If mean residual across open bins is large, prefer using them.
        score += 0.15 * mean_residual;
        // If the next item is large and current bins are fragmented, new bin
        // becomes more attractive.
        if next_item_size > 50 {
            score -= 4.0;
        }
    } else {
        // Prefer filling bins with below-average residual (balance fragmentation).
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
        // Prefer bins over emptier ones when many bins are open (consolidation).
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild time-horizon coupling: early on, be greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on leftover space (waste minimization)
    let mut score = norm_pr * norm_pr * cap;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; smooth polynomial blend
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward exact-ish fits with smooth falloff
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness * cap * 0.01;

    // Lookahead: if next item fits exactly into post_residual, reward strongly (smooth)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 20.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize creating dead space the next item cannot use, scaled by how dead
        let dead = (next_item_size - post_residual) as f64 / cap;
        score += 10.0 * dead * dead * cap * 0.1;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's residual is already small relative to mean residual
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Smoothly discourage new bins unless item is large and fits would be poor
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        let openness = (mean_frac - norm_pr).max(0.0);
        score += 30.0 - 25.0 * fit_pressure - 15.0 * item_frac * item_frac - 20.0 * openness * openness * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Smooth mean-residual coupling: prefer bins below mean residual (tighter bins)
    let mean_gap = (mean_residual - pr) / cap;
    score += 5.0 * mean_gap * mean_gap * mean_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable slot classes"
    let r = (post_residual % 10) as f64;
    // Small residue => post_residual nearly a multiple of 10 => reusable slot
    score += r * 0.8;

    // Integer-division thresholds on post_residual: dead-space bands
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver (min item size 1..100 interface: still penalize)
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // barely usable band
    }

    // Perfect fit / near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: harmonic class match between post_residual and next item
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 55.0; // next item fits exactly
        } else if diff > 0 && (diff as u32) < 10 {
            score -= 15.0; // next item nearly fills remainder
        } else if diff < 0 {
            // next item won't fit here; penalize proportionally to overshoot class
            let over = (-diff) as f64;
            score += (over / 10.0).floor() * 3.0;
        }
        // residue harmony: post_residual and next_item_size share a modulo class
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it slightly expensive unless current bin leaves bad class
    if bin_residual == bin_capacity {
        score += 15.0;
        // open new bin early when many bins already open and mean residual is high
        score += (open_bins_count as f64).sqrt() * 2.0;
        score -= (mean_residual - 40.0).max(0.0) * 0.5;
    }

    // Tightness reward: reward filling bins proportionally
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 20.0;

    // Stream progression: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual coupling: if this bin is far below mean residual, it's "wasted space keeper"
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical future items are wasted.
    // Treat gaps below a plausible minimum item size as fully wasted (double-count them).
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.15);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits (near-zero post residual) strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect fill of the bin: residual equals capacity exactly => new-bin candidate;
    // penalize opening a new bin unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is only attractive for large items; otherwise prefer existing bins.
        score += 30.0 * (1.0 - fill_ratio);
        // If this is the last-chance bin, discourage opening a new bin heavily.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // Under bin pressure, opening new bins is natural; slight discount.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Last-chance pressure: if this bin is the only one that fits, favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving large-ish gaps that nothing uses.
            score += 5.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // i.e. penalize leaving large residuals scattered (favor filling this bin deeper).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt();
    score += (post_residual as f64 / bin_capacity as f64) * pressure * (1.0 + progress);

    // Mean residual coupling: if this bin's residual is far below the mean, filling it
    // reduces fragmentation of the fleet.
    let this_residual = post_residual as f64;
    if this_residual > mean_residual {
        score += (this_residual - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - this_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual,
    // with extra reward for an exact two-item fill.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 120.0;
            if post_residual == next_item_size {
                score -= 500.0;
            }
            // prefer chains that keep post residual after next item small
            let after_next = (post_residual - next_item_size) as f64;
            score -= 0.5 * (50.0 - after_next.min(50.0)) as f64;
        } else {
            // next item cannot use the leftover: penalize dead space, worse when large
            score += 0.8 * post_residual as f64;
            // small leftover that nothing can use is worse
            if post_residual < 10 {
                score += 60.0;
            }
        }
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0 + 0.3 * (item_size as f64);
    }

    // New-bin candidate handling: neutral-ish score so we only open a new bin
    // when fits into open bins are bad.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.5 * (item_size as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // pairing large items together is fine
        }
    }

    // Compare against mean residual: bins with less residual than average are
    // better targets for filling up; penalize placing into already-loose bins.
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0) * -1.0;
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, tighten up: prefer exact fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 0.5 {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual as f64 - nr) / cap;
        } else {
            score += 4.0 * (nr - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fit = (post_residual as f64 / cap) > 0.4;
        if poor_fit && fitting_bins_count > 0 {
            score -= 8.0 + 10.0 * (1.0 - progress);
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time horizon: early in the stream, be conservative (favor compact fills);
    // late in the stream, avoid leaving large residuals.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / cap);
    score -= progress * 5.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
