            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }
    // Mean residual divergence penalty
    score += ((pr - mean_residual).abs() / cap) * 5.0 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals that are "harmonic" sizes
    // (common divisors of capacity: 1,2,4,5,10,20,25,50) — these are reusable.
    let harmonic = |r: u32| -> bool {
        r == 0 || r % 10 == 0 || r % 25 == 0 || r == 50 || r == 20 || r == 5 || r == 2 || r == 1
    };
    if harmonic(post_residual) {
        score -= 12.0;
    } else {
        // penalize odd dead space proportionally
        score += (post_residual % 10) as f64 * 0.8;
    }

    // Perfect fit is best
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > post_residual {
        // next item can't use leftover: penalize large leftovers
        score += post_residual as f64 * 0.15;
    }

    // Last chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New bin candidate: penalize opening a new bin unless current bin
    // would leave bad dead space and next item is large.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= 50 {
            score -= 20.0; // roomy new bin good for future large items
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0;
        }
    }

    // Small residual bins: prefer to dump items into them (cleanup)
    if bin_residual < 30 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Progression-aware: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 25.0;
    }

    // Reward tight fits relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins with residual below the mean (consolidate fragmented space).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate logic: only attractive when item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_score = 55.0 - 20.0 * fragmentation - 15.0 * (item_size as f64 / bin_capacity as f64) - 10.0 * progress;
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fill: bin becomes exactly full
