            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 40.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it enables a good lookahead chain
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            100.0
        };
        score += 15.0 + chain_bonus * 0.6;
        // early in stream, new bins are cheaper to open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference to fill already-open bins when many are open
    score += open_bins_count as f64 * 0.15;

    // Prefer exact fills overall
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good, amplify it.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / 100.0);
            // Exact pairing bonus: residual exactly consumed by next item.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    } else {
        // Last item: strongly prefer filling as tightly as possible.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless current item is large and would
        // leave open bins fragmented. Scale penalty with stream progress:
        // late in the stream, prefer reusing existing bins more aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 30.0 * progress;

        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.3;

        // If many bins already fit the item, definitely prefer them.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
    } else {
        // Prefer bins whose residual is close to mean residual (balanced usage),
        // slightly rewarding consolidation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Mild preference for bins with larger residual when item is large
    // (large items need room), via item-size coupling.
    score -= (item_size as f64 / 100.0) * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
