    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = pr + 6.0 * fragmentation * (0.4 + progress) - 4.0 * (1.0 - fragmentation);
    }

    score
}

