pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic dead-space penalty
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / cap;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits in post_residual (chained packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= 10.0 + 0.3 * (next_item_size as f64) - 0.2 * (pair_waste as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here; penalize large leftover dead space
        score += 0.15 * pr;
    }

    // Harmonic class logic: modulo classes on post_residual
    let m10 = post_residual % 10;
    if m10 == 0 && post_residual > 0 {
        score -= 8.0; // clean class, easy to fill later
    } else if m10 <= 3 && post_residual > 0 {
        score -= 4.0; // small dead space class, often unusable -> slightly favored to consume
    } else if m10 >= 7 {
        score += 3.0; // awkward class
    }

    // Integer-division threshold: residual below quarter capacity is near-dead
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are poor fits
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < 0.35 * cap
            && (mean_residual > 0.45 * cap || open_bins_count > 4);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 15.0;
        }
        // Early stream: prefer opening bins to build flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 5.0;
        }
    }

    // Spread pressure: when many bins are open, favor bins below mean residual (balance)
    if bin_residual < bin_capacity {
        score += 0.1 * ((post_residual as f64) - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Reward filling a bin deeply (low post_residual relative to capacity).
    score += (bin_capacity as f64 - post_residual as f64).recip() * 30.0;

    // Pressure to close out bins when many are open.
    score += open_bins_count as f64 * 2.5;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item can't use the gap
    }

    // Mean residual coupling: prefer bins near the mean (keeps distribution balanced).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.4;

    // Prefer using existing bins over the fresh empty bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Early stream: be a bit more tolerant of spreading out.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
