    // prefer bins whose residual is close to the item (below-mean residual bins).
    if item_size as f64 > mean_residual {
        score += 25.0; // item barely fits: risky but last resort
    } else {
        let rel = (mean_residual - item_size as f64) / (bin_capacity as f64);
        score -= 15.0 * (1.0 - rel.min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with how many bins are already open.
        score += 70.0 + 5.0 * open_bins_count as f64;
        // If no other bin fits (fitting_bins_count == 1 means only this new bin),
        // opening is necessary: reduce the penalty.
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        // Early in the stream, opening bins is cheaper (build a portfolio of bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild penalty for very large dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny leftover is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 30 {
        // mid-range dead space: mildly penalize if next item can't use it
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Perfect-ish fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Dead-space penalty: leaving a sliver that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement;
    // otherwise penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = 1.0 - (next_item_size as f64 / post_residual.max(1) as f64);
            score -= 18.0 * chain;
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 20.0 {
                score += 4.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive for large items or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins for small items; large items justify fresh bins.
        score += 45.0 * (1.0 - item_frac);
        // Slight discount late in stream (fewer future chances to fill fresh bins anyway).
        score -= 10.0 * progress;
        // If many open bins with slack, discourage new bin.
        score += 0.15 * open_bins_count as f64;
        score += 0.5 * (mean_residual - item_size as f64).max(0.0);
    }

    // Mild preference for using bins with larger residuals when fit ratios are equal,
    // keeping smaller residuals available for small items.
    score += 0.05 * bin_residual as f64 * (1.0 - fit_ratio);

    // Global state coupling: when mean residual is high, prefer placements that
    // reduce fragmentation the most (already captured by fit_ratio, add small coupling).
    score -= 0.02 * mean_residual * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, mildly compressed
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual normalized, shaped by progress
    let x = pr / cap; // in [0,1]
    let coupling = x * x * (1.0 - progress) - x * x * x * progress;
    score += 40.0 * coupling;

    // Tight fits are good: penalize large residuals more at later stages
    score += progress * pr * 0.5;

    // Dead space penalty: residual too small for typical future items
    let min_item = 1.0f64;
    if pr < min_item {
        score += 100.0;
    }

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - nxt / cap);
        } else {
            // wasted residual relative to next item
            score += 0.3 * (nxt - pr);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Avoid fragmenting many bins early: penalize near-empty usage when alternatives exist
    let near_empty = (bin_residual as f64 / cap) > 0.9;
    if near_empty && open_bins_count > 1 {
        score += 10.0 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins whose residual is close to mean (balanced packing)
    score += 0.2 * ((pr - mean_residual).abs());

    score
}

