pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets dead space
    let pr = post_residual as u32;
    let class = pr % 10;
    // Dead space penalty: residual that cannot plausibly fit a small item
    if pr > 0 && pr < 10 {
        score += 12.0; // tiny unusable sliver
    } else if class >= 1 && class <= 4 && pr < 25 {
        score += 4.0 + 0.5 * class as f64; // awkward harmonic class
    } else if pr == 0 {
        score -= 8.0; // perfect closure
    }

    // Fraction-of-capacity coupling: reward residuals that are near multiples
    // of common item sizes (harmonic alignment of capacity fractions)
    let harmonic_align = [10u32, 20, 25, 50].iter().any(|&k| pr % k == 0);
    if harmonic_align {
        score -= 5.0;
    }

    // Integer-division threshold on post residual relative to next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: strongly favor, more so if tight fit
            let slack = pr - next_item_size;
            score -= 6.0 + 4.0 * (slack as f64 / cap).recip().min(3.0);
        } else {
            // next item cannot use this residual: penalize by wasted fraction
            score += 3.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0; // base reluctance to open new bin
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, must open
        } else if fitting_bins_count == 1 {
            score -= 12.0; // only one alternative, mild preference to open
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
        // if mean residual across open bins is small, opening is sensible
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Tightness bonus: prefer bins where item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio;

    // Penalize spreading across too many bins when open bins already plentiful
    if open_bins_count > 8 && bin_residual == bin_capacity {
        score += 6.0;
    }

    // Mild noise-free tie-break via harmonic class of bin residual
    score += (bin_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot hold even the smallest plausible future item is "dead".
    let dead_threshold = 8.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0;
    }

    // Penalize mid-range residuals that are too small for typical items
    // (items >= 10), creating quasi-dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty scales with how much of the bin is wasted relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.15 {
        score += 20.0 * (0.15 - waste_ratio);
    }

    // Open bins pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item won't fit here; leaving a gap larger than next item is wasted.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 6.0;
        }
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: be more conservative, keep bins tight; later, allow more slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

