pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // exact 2-step chain: fill now, fill fully next step
        } else if (post_residual as u32) >= next_item_size {
            score -= 18.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: dead space penalty
