        }
    }

    // Prefer bins whose residual is already small (tight packing).
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight bonus for reusing bins when many are open.
    score -= 0.4 * open_bins_count as f64;

    // Early in stream: be pickier about wasting space (dead space matters long-term).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already low; amplify)
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }
    // Reward leaving exactly enough space for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening new bins when many open bins already fit the item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let new_bin_penalty = 10.0 + 12.0 * (1.0 - progress) + 2.0 * fit_ratio;
        // Allow new bin if it would be a perfect fit and no existing bin is tight
        let perfect = item_size == bin_capacity;
        if !perfect {
            score += new_bin_penalty;
        } else {
            score -= 5.0;
        }
    }

    // Prefer bins with residual below mean (consolidate emptier space usage)
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 3.0 * dev;
    }

    // Mild preference for using bins in later stages to keep options open early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 1.5 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Small penalty proportional to open bin count to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
