pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Non-linear polynomial coupling: penalize large residuals more than linearly,
    // scaled by stream progress (late-stage waste is costlier).
    let x = pr / cap;
    score += (x * x) * cap * (0.15 + 0.35 * progress);
    score += (x * x * x) * cap * 0.10 * progress;

    // Reward tight fits (small post residual) more strongly as stream advances.
    score -= item_size as f64 * (0.05 + 0.10 * progress);

    // Lookahead: if next item fits exactly in post residual, strong reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if nx <= pr {
            score -= 12.0 * (1.0 - diff / cap);
        } else {
            score += 4.0 * (diff / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    // (many open bins with high mean residual and poor fits elsewhere).
    if bin_residual == bin_capacity {
        let avg_fit_pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).recip()
        } else {
            1.0
        };
        score += 30.0 * avg_fit_pressure - 8.0 * (mean_residual / cap);
        score += 10.0 * progress;
    }

    // Mild coupling with open bins count: spreading items across many bins
    // slightly penalized when residuals are fragmented.
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 2.0;

    score
}

