pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small residual that could still fit a future item is acceptable; large residual is fine.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would NOT fit here, mild penalty so we don't block it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure against opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    // Favor bins with residuals below the mean (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight progression term: tighten packing as stream advances.
    score -= (step_index as f64 / total_items.max(1) as f64) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else {
        // Penalize residual quadratically relative to capacity (dead space).
        score += (post_residual as f64 / cap) * (post_residual as f64 / cap) * 30.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chaining if next item fits too, scaled by how tight the chain is.
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit after this placement: penalize blocking.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let ratio = (bin_residual as f64) / mean_residual;
        if ratio < 1.0 {
            score -= (1.0 - ratio) * 10.0; // tighter (fuller) bin favored
        } else {
            score += (ratio - 1.0) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or when the item is large relative to the empty space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin; discourage when many bins already open.
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        // If item is large, opening a fresh bin may be fine (less penalty).
        score -= (item_size as f64 / cap) * 25.0;
        // Early in stream, new bins are cheaper.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 15.0;
        }
        // Lookahead: fresh bin leaves room for next item.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to item size before placement.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual is naturally good, amplify it).
