            // post-residual too small for next item: dead space relative to lookahead
            score += 5.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Neutral baseline plus a mild cost so we don't proliferate bins carelessly.
        score += 8.0;
        // When many bins are open, discourage opening yet another one.
        score += 0.5 * open_bins_count as f64;
        // If the current bin would leave a large awkward residual, opening a new
        // bin becomes relatively more attractive.
        if bin_residual >= item_size && post_residual > 40 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state coupling: if mean residual across open bins is high, we have
    // slack everywhere -> be pickier, penalize loose fits more.
