pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex in normalized residual
    let mut score = pr + 20.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of residual with stream progress:
    // early on, waste tolerance is high; late, dead space is heavily penalized.
