    // Perfect fit reward (smooth, non-piecewise): strongly subtract near zero residual
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * (1.0 - norm_pr * norm_pr) * (1.0 + late);

    // Penalize residual that cannot fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        let gate = 1.0 / (1.0 + (-gap / 10.0).exp()); // ~1 if next item won't fit
