    } else {
        score += 10.0 * norm_pr; // last item: just minimize waste
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - late * 0.5);
    }

    // Crowd penalty: many open bins -> prefer consolidating into fuller bins
    let crowd = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 8.0 * crowd * (mean_residual / cap);

    // Mild preference for larger item placement (dense packing)
    score -= 0.05 * it;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that fall into "small leftover"
    // classes are ideal; large leftovers waste capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic classes):
    // class 0: pr == 0 (perfect fit) -> strong reward
    // class 1: pr < 10  (dead space, unusable for items >=10 but maybe for 1..)
    // class 2: pr in [10,25)
    // class 3: pr in [25,50)
    // class 4: pr >= 50 (huge waste)
    let class = post_residual / 25; // 0,1,2,3+
    match class {
        0 => score -= 30.0,                       // near-perfect fit
        1 => score -= 12.0,                       // tight residual
        2 => score += 6.0,                        // moderate leftover
        _ => score += 14.0,                       // large leftover penalty
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for typical minimum item
    // (unknown distribution, so use a soft harmonic band rather than hard cut)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a chained perfect fit -> reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // next item fits: leftover after chain matters
            let chain_left = post_residual - next_item_size;
            score -= (15.0 * (1.0 - chain_left as f64 / cap)).max(0.0);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover is stranded
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin should only win when all
    // existing fits are poor. Penalize it via harmonic class of the item
    // it would hold relative to capacity.
    if bin_residual == bin_capacity {
        // item_size / capacity fraction classes (integer division on quarters)
        let q = item_size / 25; // 0..3
        score += 18.0 + 6.0 * q as f64; // big items justify new bins more
        // early in the stream, new bins are cheaper (few open bins to fragment)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // many open bins already: avoid adding more unless necessary
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (consume the tightest space first), scaled by fraction of capacity.
    score += 0.25 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.10 * (bin_residual as f64 - mean_residual).max(0.0);

    // Modulo harmonic texture: residuals that are multiples of common item
    // sizes (10/20/25) are more likely reusable -> small reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Mild late-stream tightening: as stream progresses, penalize waste more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are pure waste. Penalize them super-linearly.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual as f64 <= bin_capacity as f64 * 0.05 {
        score -= 15.0;
    }

    // Coupling: residual wasted scales with how crowded the system is.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += post_residual as f64 * pressure * 0.8;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + post_residual as f64 * 0.3;
    }

    // New-bin candidate: prefer existing bins generally; only allow the new
    // bin to win when the item is large and fits would leave big gaps.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Large items leaving small leftovers elsewhere: new bin is attractive.
        let gap = bin_residual - item_size;
        if gap <= 5 {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= (1.0 - progress) * 8.0;
        // If open bins are already fragmented (high mean residual), a fresh
        // bin is a good reset.
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 45.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal waste
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (fill fuller bins first)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage unless current residual would be wasted
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight preference for tight fits overall
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Late in stream: be more aggressive about keeping bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness);

    // Penalize dead space: residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; make it unattractive unless current bins fit badly.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if item is huge and mean residual is small, new bin becomes reasonable.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    }

    // Prefer filling bins with larger residuals (consolidate waste) early;
    // later in the stream, prefer perfect fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - tightness);

    // Mild penalty for spreading across many bins: favor dense packing when
    // mean residual is high.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    // Exact-fit jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Tight-fit reward: strongly favor small post residuals (non-linear).
    score += (pr / cap).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize post residuals too small for the smallest plausible follow-up item,
    // with lookahead coupling to the actual next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * 1.5;
        } else {
            // reward residuals that can still host the next item
            score -= ((pr - nxt) / cap).powi(2) * 25.0;
        }
        // residual just above next item is ideal (smooth coupling)
        let gap = (pr - nxt).abs();
        score -= (1.0 - gap / cap).powi(2) * 15.0;
    }

    // Dead-space penalty: residual below 10 is nearly unusable.
    if pr > 0 && pr < 10.0 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity unless
    // the item fits poorly everywhere; make the empty-bin candidate mildly
    // unattractive, with progress-dependent pressure to consolidate.
    if bin_residual == bin_capacity {
        let waste = pr; // capacity left after placing item in a fresh bin
        score += 30.0 + progress * 50.0 + (waste / cap) * 40.0;
    }

    // Consolidation pressure: many open bins with high mean residual -> prefer
    // filling existing bins (smooth polynomial in progress).
    let consolidation = (mean_residual / cap).powi(2) * (1.0 - progress) * 20.0;
    if bin_residual != bin_capacity {
        score -= consolidation;
    }

    // Slight preference for bins with less residual already used up earlier.
    score += (bin_residual as f64 / cap) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, slightly above tight fits so only
    // genuinely poor fits in open bins get overridden.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.55 + post_residual as f64;
    }

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Harmonic class of the post residual (mod arithmetic) ----
    // Classes of residual: 0 (perfect), small residues 1..=10 (dead space),
    // mid residues, large residues. Use modulo-10 classes.
    let r = post_residual;
    let class = (r % 10) as i64;
    let div = r / 10; // how many full 10-blocks remain

    // Perfect fit reward: strongest bonus.
    if r == 0 {
        score -= 120.0;
    } else if r <= 10 {
        // small dead space: penalize proportionally to how "wasted" it is
        score += 18.0 + (10 - r) as f64 * 2.2;
    } else {
        // Reward larger usable remainders, but with a harmonic decay per decade
        score -= (div as f64) * 4.0;
        // mid-class residues that pair well with common item sizes get a bonus
        if class >= 2 && class <= 5 {
            score -= 6.0;
        }
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item fits here: big reward, scaled by tightness of that fit
            let tight = (r - next_item_size) as f64;
            score -= 40.0 - tight * 0.8;
        } else {
            // next item cannot follow here: mild penalty, worse if this was our
            // only remaining capacity chunk
            score += 8.0;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= 15.0;
    }

    // ---- Last-chance bin ----
    if fitting_bins_count == 1 {
        // Only bin that fits the item: strong reward to avoid opening a new bin
        score -= 55.0;
        // extra reward if the resulting residual is small (good packing)
        if r <= 20 {
            score -= 12.0;
        }
    } else if fitting_bins_count > 1 {
        // Many alternatives: slight penalty so tight fits elsewhere win
        score += 3.0 * (fitting_bins_count.min(6) as f64 - 1.0);
    }

    // ---- Open-bin pressure ----
    // When many bins are open, encourage consolidation into low-residual bins.
    score += (open_bins_count as f64).sqrt() * 1.5;
    // Prefer bins whose residual is below the mean (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // ---- Progress adaptation ----
    // Late in the stream, be greedier about perfect fills; early, keep options open.
    if progress > 0.7 {
        score -= (r as f64) * 0.15;
    } else if progress < 0.3 {
        // early: favor leaving flexible mid-size residuals
        if r >= 20 && r <= 60 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..=100) are wasted. Penalize gaps in the "dead zone"
    // where nothing small is likely to fit well.
    if post_residual > 0 {
        // Nonlinear penalty peaking for unusable tiny gaps
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * 3.0; // severe penalty for near-dead space
        } else if pr < 34.0 {
            score += (34.0 - pr) * 1.2; // moderate penalty for awkward gaps
        } else {
            // Larger residual slack is less costly; mild reward for big gaps
            score -= (pr - 34.0).min(50.0) * 0.3;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving exactly enough room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 45.0; // next item fits perfectly
        } else if (post_residual as u32) >= next_item_size {
            score -= 15.0; // next item still fits
        } else {
            score += diff as f64 * 0.5; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin waste is high
    if bin_residual == bin_capacity {
        // Base neutral cost of opening a bin; offset by how bad existing fits are
        score += 40.0;
        // If open bins are already crowded with large residuals, new bin is fine
        score -= open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating rather than opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly
    score += open_bins_count as f64 * 0.5;

    // Prefer filling bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Mild reward when bin residual is far above average (use the loosest bin)
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fits snugly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin;
    // if next item is slightly smaller than residual but leaves waste, mild penalty.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let slack = post_residual as f64 - next;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else if next > post_residual as f64 && next <= bin_residual as f64 {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize this bin when many bins fit (prefer the tightest anyway; mild noise-free tiebreak).
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: opening a new bin is wasteful unless it is the
    // only option or residuals across open bins are all very tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        let mut new_bin_penalty = 30.0 + 20.0 * progress + 5.0 * open_pressure;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty;
    }

    // Global state: when mean residual across bins is small, conserve open bins
    // (favor existing bins); when residuals are large, allow spreading.
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * residual_gap;

    // Time horizon: late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste term, non-linearly amplified as the stream progresses.
    let mut score = pr * (1.0 + 1.5 * t * t);

    // Quartic penalty on residual near capacity (dead space creation).
    score += 12.0 * norm_pr * norm_pr * norm_pr * norm_pr * (0.5 + t);

    // Tight-fit reward: smooth Gaussian-like coupling of post_residual to item_size.
    let tightness = (pr - 0.5 * item_size as f64) / cap;
    score -= 8.0 * (-tightness * tightness * 4.0).exp();

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (-gap * gap * 9.0).exp();
        // Penalize residual just barely too small for the next item.
        if gap < 0.0 && -gap < 0.15 {
            score += 6.0 * (1.0 - (-gap / 0.15).powi(2));
        }
    }

    // Last-chance bin bonus: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.3 * (open_bins_count as f64).ln() * (mean_residual - pr).abs() / cap;

    // New-bin candidate: prefer it only when current fit is very loose.
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * norm_pr; // effectively baseline; tight fits in open bins beat it
        score -= 3.0 * t; // later in stream, slightly cheaper to open fresh bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no item (1..=100)
    // can ever use is worthless; space usable by small items retains value.
    let dead = post_residual < 10; // nothing in [1,100] fits if < 10 residual? items 1..100, so residual 1..9 is dead
    if dead {
        score += 50.0;
    }

    // Classify post_residual into harmonic remainder classes mod 10
    // (residuals that are multiples of common item sizes are reusable).
    let pr = post_residual;
    if pr > 0 && pr <= 100 {
        if pr % 10 == 0 {
            score -= 8.0; // highly reusable residual class
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else if pr >= 50 {
            score -= 3.0; // half-bin or more still flexible
        }
    }

    // Lookahead coupling: reward when next item exactly fits the post residual,
    // penalize when next item cannot fit this bin's remainder anyway.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr && pr - next_item_size < 10 {
            score -= 25.0; // near-perfect chain
        } else if next_item_size > pr {
            score += 2.0; // next item won't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a decent fit,
    // better than a terrible fit. Encourage new bins early when few bins open.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 20.0 - (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score += 10.0; // big next item may want a fresh bin
        }
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Dead-space pressure grows with stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * (0.5 + progress);

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // to discourage spreading; but reward using an existing bin when few are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would be blocked by the residual left here, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // penalize wasting space in already-loose bins.
    score += (mean_residual - post_residual as f64).max(0.0) * -0.2;

    // New-bin candidate: make an empty bin mildly attractive only when no tight fit exists;
    // baseline penalty so it is chosen only when open bins score poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (0.9 + 0.3 * progress) - 10.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize by leftover after the pair
            let chain_residual = post_residual - next_item_size;
            score += 0.6 * chain_residual as f64;
            if chain_residual == 0 {
                score -= 400.0;
            }
        } else {
            // next item won't fit here: penalize slightly
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose post_residual
    // is small relative to the fleet mean (tight packing), penalize outliers
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        score += 120.0 + 200.0 * progress;
        // but allow a new bin if item is large and would leave a big hole anyway
        if item_size > 60 {
            score -= 60.0;
        }
    }

    // Prefer filling bins that are already mostly used
    score -= 0.5 * (bin_capacity as f64 - bin_residual as f64);

    score
}

