pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Penalize large dead space after placement (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < item_size.min(30) {
        // residual too small for typical future items: dead space penalty
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize leaving awkward residual
            let waste = post_residual as f64 - (next_item_size as f64 * 0.5);
            if waste > 0.0 {
                score += 0.25 * waste;
            }
        }
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (spread load); late in stream, pack existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * tightness;
    score += progress * 0.05 * post_residual as f64;

    // Many open bins with high mean residual: prefer consolidating
    // into existing bins rather than opening more.
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // or the current bin fit is poor.
        let poor_fit = if bin_residual >= item_size && post_residual < bin_capacity {
            (bin_residual - item_size) as f64 / bin_capacity as f64
        } else { 0.0 };
        score += 30.0 - 6.0 * poor_fit - 0.5 * open_bins_count as f64;
        // Late in stream, opening a fresh bin is more acceptable.
        score -= 10.0 * progress;
    }

    // Mild penalty for bins whose residual is far below mean (already
    // fragmented); prefer bins with residual near or above mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.1 * diff.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + t) + norm_item * norm_item * (1.0 - t);
    score += 40.0 * poly;
    // penalize tight fits more as stream progresses (dead space is costlier late)
    let tight = 1.0 - norm_pr;
    score += 25.0 * tight * tight * (0.5 + t);
    // reward using bins with low mean residual (consolidation)
    score -= 10.0 * (mean_residual / cap) * (1.0 - norm_pr);
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let next = next_item_size as f64 / cap;
        let gap = norm_pr - next;
        if gap >= 0.0 {
            score -= 15.0 * gap * (1.0 - gap);
        } else {
            score += 20.0 * gap * gap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - t);
    }
    // new-bin candidate: penalize opening new bins early, mildly late
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - t) + 5.0 * t;
    }
    // mild open-bin pressure
    score += 2.0 * (open_bins_count as f64).ln();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose residual falls into
    // "small, hard-to-fill" classes are penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division into decade classes
    let harmonic_penalty: f64 = match class {
        0 => -30.0,                     // near-perfect fit
        1 => -12.0,                     // 10..19 residual, still useful
        2 | 3 => 5.0,                   // awkward mid-range dead space
        4 => 2.0,                       // ~40..49, half-bin class
        5 => 0.0,                       // exactly half-full is flexible
        6 => 4.0,
        7 => 8.0,
        8 => 6.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Modulo coupling: residuals divisible by common item sizes are reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 4.0; }
        // Prime-ish residuals are dead space.
        if pr % 2 == 1 && pr % 5 != 0 { score += 2.0; }
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && (pr as u64) >= next_item_size as u64 {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap <= 10 {
            score -= 10.0;
        } else {
            score -= 5.0 * (1.0 - gap as f64 / cap);
        }
    } else if next_item_size > pr as u64 && pr > 0 {
        // Next item won't fit here; mildly penalize leaving a stranded residual.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are bloated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score = cap * 0.55 + openness * 2.0 + progress * 15.0 - mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Tight-fit bonus relative to item size.
    score -= (item_size as f64 / cap) * 6.0;

    // Tie-break noise-free stability: tiny deterministic nudge.
    score += (pr as f64 % 3.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        // Unusable dead space (items are >= 1, but small gaps rarely reused): heavy penalty
        score += 60.0 * (1.0 - dead / 10.0);
    } else if dead >= 10.0 && dead < 25.0 {
        // Marginal gap: moderate penalty that decays as gap grows
        score += 20.0 * (1.0 - (dead - 10.0) / 15.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward using a bin when it's the last fitting option (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot use the post residual (creates stranded space)
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 10.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Prefer bins with below-average residual (pack tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: mildly penalize opening a new bin unless current bin creates bad dead space
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits here: strongly reward tight chains.
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit in the leftover: penalize dead space growth.
            score += 12.0 * (gap / bin_capacity as f64);
        }
    }

    // Tightness coupling: prefer bins where post_residual is small relative to mean residual.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit,
    // but strongly prefer it when the fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 10 {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 1.5 + post_residual as f64;
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: normalized waste fraction
    score += (post_residual as f64 / cap) * 12.0;

    // Reward tight fits strongly
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * tightness * 25.0;

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let nxt_tight = 1.0 - (post_residual as f64 - nxt) / cap;
            score -= nxt_tight * 20.0;
        } else {
            // next item won't fit here: mild penalty proportional to mismatch
            score += ((nxt - post_residual as f64) / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening new bins unless the stream
    // is young and mean residual across open bins is low
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let residual_pressure = mean_residual / cap; // high = many open bins have room
        score += 15.0 + 35.0 * residual_pressure + 20.0 * (1.0 - progress);
        // if item is small, opening a new bin wastes capacity
        score += (cap - item_size as f64) * 0.15;
    }

    // Prefer bins whose residual is close to the mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 6.0;

    // Crowding: with many open bins, favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tightness;

    // Late-stream consolidation: as stream ends, discourage leaving many scraps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste coupling with stream progress.
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));

    // Smooth interaction: penalize residuals that neither fit the next item nor vanish.
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (nx - pr).abs();
        let gap_norm = gap / cap;
        score += 0.6 * gap_norm * gap_norm * (1.0 - progress);
        // Reward exact/near fit for next item.
        score -= 0.8 * (1.0 - gap_norm).max(0.0) * (pr / nx.min(cap)).min(1.0);
    } else {
        // Last item: strongly reward fullness.
        score -= 2.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: only bin that fits -> reward using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.2 * (1.0 - progress);
    }

    // Crowd penalty: many open bins -> prefer consolidating into tighter fits.
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 0.5 * crowd * norm_pr;

    // Deviation from mean residual: prefer bins tighter than average.
    let mr = mean_residual / cap;
    score += 0.4 * (norm_pr - mr) * (1.0 + progress);

    // New-bin candidate: penalize opening a bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * (1.0 - progress) - 0.5 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Harmonic thresholds: 1/4, 1/3, 1/2 — leftover in low bands is "dead space".
    if frac < 0.25 {
        score -= 30.0; // tiny leftover = tight fit, reward
    } else if frac < 1.0 / 3.0 {
        score -= 12.0;
    } else if frac < 0.5 {
        score += 8.0; // awkward mid-band leftover
    } else {
        score += 18.0; // large leftover = wasted capacity
    }

    // Integer-division classes: leftover mod common item sizes tells if the gap
    // can be exactly filled by future items (harmonic divisibility reward).
    let pr_u = post_residual;
    if pr_u >= 10 {
        if pr_u % 10 == 0 { score -= 15.0; }
        else if pr_u % 5 == 0 { score -= 7.0; }
        else { score += 5.0; }
