    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= (1.0 - (post_residual as f64) / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = post_residual - next_item_size;
        score -= 15.0 + (leftover as f64) / bin_capacity as f64 * 10.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item would need this bin anyway; penalize wasting space now.
        score += 5.0;
    }

