    if post_residual < 3 {
        score -= 8.0; // near-perfect fill
    } else if post_residual < 10 {
        score += 3.0; // small but annoying dead space
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    score
}

