pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residual mod capacity fractions
    let pr = post_residual as u32;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Penalize residuals in "dead zones": too small for typical items (1..100)
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable sliver
    } else if pr < quarter {
        score += 12.0 * (1.0 - pr as f64 / quarter as f64);
    }

    // Reward residuals that are multiples of common item classes (mod arithmetic)
    let mod_class = pr % 10;
    if mod_class == 0 {
        score -= 8.0; // divisible by 10: likely exact fits later
    } else {
        score += mod_class as f64 * 0.5;
    }

    // Integer-division thresholds: reward residuals that can host next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            if (pr % nxt) == 0 {
                score -= 15.0; // perfect chaining potential
            } else {
                score += slack * 0.3;
            }
            // Harmonic pair: nxt + pr near capacity
            if nxt + pr as u32 >= bin_capacity.saturating_sub(eighth) && nxt + pr as u32 <= bin_capacity {
                score -= 10.0;
            }
        } else {
            score += 25.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64 / cap) * 30.0;
        score = cap as f64 - pressure;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if open_bins_count > 0 && mean_residual > 0.6 * cap {
            score -= 5.0; // open bins are crowded, new bin fine
        }
    }

    // Mild tightness reward scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - (bin_residual as f64 / cap)) * 5.0 * (0.5 + progress);

    // Penalize proliferation of open bins with large residual spread
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64).abs() * 0.1;
    }

    score
}

