    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // favor filling existing bins when the fit is decent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins with residual near the mean
    // (keeps residual distribution balanced, avoids stranding outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: make opening a new bin costly unless
    // the item is large relative to the best possible residual usage.
    if bin_residual == bin_capacity {
