            // partial lookahead fit: favor small leftover after hypothetical pair
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= 20.0 * (1.0 - two_step_leftover / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space relative to next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // fresh bin is fine if next item chains into it
