    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that would create stranded space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling fuller bins first.
    score += 0.1 * (bin_residual as f64 - post_residual as f64).signum() * -1.0;

    score
}

