        } else if next_item_size < post_residual {
            // harmonic residue of (post_residual - next_item_size)
            let chain = post_residual - next_item_size;
            score -= 30.0 + (chain as f64) * 0.3;
            if chain % 10 == 0 { score -= 10.0; }
        } else {
            // next item won't fit here: penalize tight bins less than roomy ones
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make empty-bin
    // score follow mean residual so it only wins when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = c - (item_size as f64); // post_residual of fresh bin
        score += 120.0;                 // base cost of opening a bin
        score -= open_bins_count as f64 * 0.5;
        score -= mean_residual * 0.3;   // if open bins are roomy, new bin looks worse
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Slight preference for keeping fewer open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Penalize residuals that are awkward (not expressible as common item sizes).
    let awkward = (1..=100u32).filter(|&s| s <= post_residual && post_residual % s == 0).count();
    if post_residual > 0 && awkward <= 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 40.0;
    } else {
        // Larger residuals are mildly penalized quadratically beyond a sweet spot.
        let pr = post_residual as f64;
        score += 0.15 * (pr - 10.0) * (pr - 10.0) / 10.0;
    }

    // Penalize wasting a large residual on a small item when next item could use it.
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx > pr {
            // next item cannot use this leftover anyway -> leftover is dead space.
            score += 0.5 * pr;
        } else {
            // next item fits the leftover: reward leaving exactly that gap.
            score -= 0.3 * (pr - nx);
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (new bin candidate has bin_residual == capacity,
    // so it gets a large post_residual and suffers here).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild alignment with mean residual: bins far below mean residual are
    // "emptier" and slightly less preferred.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to ever be useful
        // (items are 1..=100, but small residuals below a typical item floor are waste).
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += 40.0 * (dead_threshold - post_residual as f64);
        }

        // 2-step lookahead: strongly reward a residual that exactly matches
        // the next item, and mildly reward residuals that can host it.
        if next_item_size > 0 {
            let nr = next_item_size as f64;
            let pr = post_residual as f64;
            if pr == nr {
                score -= 300.0; // exact match: chain placement
            } else if pr > nr {
                // residual can host next item: reward proportional to closeness
                let gap = pr - nr;
                score -= 120.0 - 0.8 * gap;
            } else {
                // next item cannot fit in this residual: penalize tight misses
                score += 0.6 * (nr - pr);
            }
        }

        // Favor bins whose residual deviates from the mean in a "tightening"
        // direction (packing into already-loose bins keeps tight bins usable).
        let dev = post_residual as f64 - mean_residual;
        score += 0.15 * dev;

        // Last-chance bin: if this is the only bin that fits, strongly prefer
        // using it over opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 250.0;
        }

        // New-bin candidate: make it attractive only when the item leaves a
        // large, flexible residual and no existing bin fits well.
        if bin_residual == bin_capacity {
            let flex = post_residual as f64; // = capacity - item
            score += 30.0;                  // mild cost of opening a bin
            if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
                score -= 60.0; // fresh bin can host the next item too
            }
            if flex > 60.0 {
                score -= 0.3 * (flex - 60.0);
            }
            // Opening new bins late in the stream is fine; early on, discourage
            // bin proliferation.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 40.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 900.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 55.0 ; }
        else if next_item_size <= post_residual { score -= 11.0 + 0.22 * (post_residual - next_item_size) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size . min (21) { score += 15.0 + 0.32 * (next_item_size . min (21) - post_residual) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size > post_residual + 4 { score += 0.42 * (next_item_size - post_residual) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 4 { score -= 7.0 ; }
        if post_residual >= next_item_size && post_residual - next_item_size < 8 { score -= 2.0 + 0.15 * (8 - (post_residual - next_item_size)) as f64 ; }
        if post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            score += 0.10 * dead as f64 ;
            let waste_ratio = dead as f64 / next_item_size as f64 ;
            score += 1.5 * waste_ratio + 1.2 * waste_ratio * waste_ratio ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 16 { score -= 0.06 * (16 - (post_residual - next_item_size)) as f64 ; }
        if post_residual >= next_item_size && post_residual - next_item_size >= 16 { score += 0.02 * ((post_residual - next_item_size) as f64 - 16.0) ; }
        let dead_gap = if post_residual >= next_item_size { post_residual - next_item_size } else { next_item_size - post_residual } ;
        if dead_gap as f64 > mean_residual * 0.6 { score += 0.35 * (dead_gap as f64 - mean_residual * 0.6) ; }
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64) ;
            score -= 8.0 + 6.0 * tightness ;
            if post_residual - next_item_size <= 2 { score -= 5.0 ; }
            if post_residual == 2 * next_item_size { score -= 4.0 ; }
            if post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 { score -= 3.5 ; }
        }
        // two-step lookahead proxy: prefer residual that still fits next item with slack
        if post_residual >= next_item_size && post_residual < next_item_size * 3 && fitting_bins_count > 1 {
            score -= 0.8 * (1.0 - (post_residual - next_item_size) as f64 / (2.0 * next_item_size as f64)) ;
        }
        // strand a mid-size gap in a big residual
        if post_residual > 0 && post_residual < next_item_size && post_residual > bin_capacity / 3 { score += 3.6 ; }
        // residual deviation from mean pressure
        if post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual) . abs () ;
            score += 0.08 * dev ;
            if (post_residual as f64) < mean_residual * 0.35 { score += 1.8 ; }
            if ((post_residual as f64 - mean_residual) . abs () as u32) <= 2 { score -= 2.0 ; }
        }
        if post_residual > 0 && post_residual < 6 { score += (6 - post_residual) as f64 * 2.2 ; }
        if post_residual > 0 && post_residual < next_item_size && next_item_size <= 30 { score += 0.18 * (next_item_size - post_residual) as f64 ; }
        if post_residual > 0 && post_residual >= next_item_size && fitting_bins_count > 1 && post_residual as f64 <= mean_residual * 1.3 { score -= 1.2 ; }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 120.0 ; }
    if bin_residual == bin_capacity {
        score += 2.5 + 0.05 * (post_residual as f64) ;
        if post_residual < 10 { score += 6.0 - 0.5 * (post_residual as f64) ; }
        if fitting_bins_count <= 1 && post_residual > 40 { score -= 3.0 ; }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 } ;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 2.0 ; }
        if next_item_size > 0 && post_residual == 0 { score -= 20.0 ; }
        if next_item_size > 0 && post_residual == next_item_size { score -= 10.0 ; }
        if mean_residual < item_size as f64 * 0.5 && progress < 0.9 { score -= 40.0 ; }
        if fitting_bins_count >= 3 { score += 6.0 ; }
        if item_size as f64 > 0.7 * bin_capacity as f64 { score -= 8.0 ; }
        if item_size as f64 > 0.55 * bin_capacity as f64 && fitting_bins_count <= 2 && progress < 0.85 { score -= 14.0 ; }
        if progress < 0.5 && mean_residual < 0.35 * bin_capacity as f64 { score -= 4.0 ; }
        if progress > 0.85 && item_size as f64 > 0.4 * bin_capacity as f64 && fitting_bins_count <= 2 { score -= 5.0 ; }
        if progress > 0.9 && fitting_bins_count >= 2 { score += 10.0 ; }
        // fresh-bin lookahead — open a new bin early if next item would otherwise strand residual
        if progress < 0.6 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && item_size as f64 > 0.45 * bin_capacity as f64 { score -= 7.5 ; }
        if progress < 0.75 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.8 { score -= 4.0 ; }
        if progress < 0.7 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.5 { score -= 2.5 ; }
        if progress > 0.8 && next_item_size > 0 && post_residual != next_item_size && post_residual > 0 { score += 3.0 ; }
    } else {
        if next_item_size > 0 && post_residual == 0 { score -= 25.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let dead = next_item_size - post_residual ;
            if dead > 12 { score += 0.5 * (dead - 12) as f64 ; }
        }
        if bin_residual < bin_capacity / 8 { score -= 3.0 ; }
        if fitting_bins_count >= 4 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 3.0 * (1.0 - (slack / 20.0) . min (1.0)) ;
        }
        if next_item_size > 0 && post_residual == next_item_size { score -= 6.0 ; }
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size { score -= 2.0 + 0.1 * ((post_residual - next_item_size) . min (10)) as f64 ; }
        if post_residual > 0 && post_residual >= next_item_size && post_residual <= bin_capacity / 2 { score -= 2.0 ; }
        if next_item_size > 0 && post_residual > next_item_size && (post_residual as f64) > mean_residual * 1.8 { score += 1.2 ; }
        if post_residual > 0 && post_residual <= 4 { score -= 2.5 ; }
        if post_residual > 0 && post_residual <= 2 && fitting_bins_count >= 3 { score -= 1.5 ; }
    }
    if item_size >= bin_residual { score -= 5.0 ; }
    score += 0.3 * (bin_residual as f64 - mean_residual) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}
